  s+=`<line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}" stroke="#3E4A63" stroke-width="2" stroke-linecap="round"/>`;
  s+=`<circle cx="${Vx}" cy="${Vy}" r="2.4" fill="#3E4A63"/>`;
