// v71 扩容：原仅 a+b 一种题型（容量 10）。补减法/填未知数/分解与组成/比大小，容量 80+
function g1_5_addsub(){
  let a=ri(1,4), b=ri(1,5-a), s=a+b;      // 加法，和 ≤5
  let c=ri(2,5), d=ri(1,c-1);              // 减法
  let n=ri(2,5), k=ri(1,n-1);              // 分解与组成
  let p=ri(1,4), sp=p+ri(1,5-p);           // 填未知数 p+( )=sp
  let x=ri(1,4), y=ri(1,5-x), sx=x+y;      // 减法变式
  const reps=[
    {q:`${a}+${b}=？`,a:s,d:[s+1,Math.max(0,s-1),s+2]},
    {q:`${c}-${d}=？`,a:c-d,d:[c-d+1,Math.max(0,c-d-1),c-d+2]},
    {q:`${p}+（　）=${sp}，括号里填几？`,a:sp-p,d:[Math.max(0,sp-p-1),sp-p+1,sp-p+2]},
    {q:`（　）+${p}=${sp}，括号里填几？`,a:sp-p,d:[Math.max(0,sp-p-1),sp-p+1,sp-p+2]},
    {q:`${n}可以分成${k}和几？`,a:n-k,d:[Math.max(0,n-k-1),n-k+1,n-k+2]},
    {q:`${k}和${n-k}合起来是几？`,a:n,d:[Math.max(0,n-1),n+1,n+2]},
    {q:`${sx}-${x}=？`,a:y,d:[Math.max(0,y-1),y+1,y+2]},
    {q:`比${a}大1的数是几？`,a:a+1,d:[a,a+2,Math.max(0,a-1)]},
    {q:`比${c}小1的数是几？`,a:c-1,d:[c,c+1,Math.max(0,c-2)]},
    {q:`${a}和${b}合起来是几？`,a:s,d:[Math.max(0,s-1),s+1,s+2]},
    {q:'小明有'+a+'块糖，小华有'+b+'块糖，谁的多？',a:a>b?'小明':(a<b?'小华':'一样多'),d:[a>b?'小华':(a<b?'小明':'小明'),'一样多','无法比较']},
    {q:'小朋友排队，从前往后数小红排第2，她前面有（　）人',a:'1人',d:['2人','0人','3人']},
    {q:'5个苹果和3个苹果比，（　）多一些',a:'5个',d:['3个','一样多','不知道']},
  ];
  let it=pick(reps);
  if(Math.random()<0.35) return mf(it.q,it.a);
  return mc(it.q,it.a,it.d);
}
