// v57：题面去重。原题库有 5 处题面完全相同（只有配图参数不同），整卷按题面严格去重时
// 会把它们压成 1 题 → 单元卷只能组出 25 题。给重复题面补上图形参数说明即可各自成题。
const _triSeen = new Set();
TRI_RAW.forEach(r => {
  if (_triSeen.has(r.q)) {
    r.q = r.q.replace(/([？。])$/, '') + `（底边 ${r.n} 段${r.l > 1 ? '、' + r.l + ' 层' : ''}${r.d ? '、含斜线' : ''}）` + (r.t === 'c' ? '？' : '。');
  }
  _triSeen.add(r.q);
});

const TRI_Q = TRI_RAW.map(r => {
  const svg = triSVG(r.n, r.l, r.d);
  if (r.t === 'c') {
    return {
      type: 'choice', question: r.q, svg: svg,
      // v69：改回字符串数组（对象格式会让 PC 端显示 [object Object]）
      options: r.o,
      answer: r.o[r.a], answerIdx: r.a
    };
  }
  return { type: 'fill', question: r.q, svg: svg, answer: String(r.ans), inputType: 'number' };
});

let _triIdx = 0;
function g_triangle_count() {
  const q = TRI_Q[_triIdx % TRI_Q.length];
  _triIdx++;
  return q;
}

function loadData() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY)) || { wrong: [], stats: {}, history: [] };
  } catch(e) {
    return { wrong: [], stats: {}, history: [] };
  }
}

function saveData(data) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
}

// 错题库为数学/英语共用存储，getWrongBank 只返回「数学」错题（无 module 字段的历史数据视为数学）
function getAllWrongBank() { return loadData().wrong || []; }
function getWrongBank() { return getAllWrongBank().filter(w => !w.module || w.module === '数学'); }
function addToWrongBank(question, userAnswer, unitName, grade) {
  let data = loadData();
  // 避免重复
  let existing = data.wrong.find(w => (!w.module || w.module === '数学') && w.question && w.question.question === question.question && w.question.answer === question.answer);
  if (existing) {
    existing.count = (existing.count || 1) + 1;
    existing.lastWrong = Date.now();
  } else {
    data.wrong.push({
      id: Date.now() + '_' + Math.random().toString(36).slice(2, 8),
      module: '数学',
      question: question,
      userAnswer: userAnswer,
      unitName: unitName,
      grade: grade,
      time: Date.now(),
      count: 1
    });
  }
  saveData(data);
}

function removeFromWrongBank(id) {
  let data = loadData();
  data.wrong = data.wrong.filter(w => w.id !== id);
  saveData(data);
}

function clearWrongBank() {
  let data = loadData();
  data.wrong = [];
  saveData(data);
}

function recordHistory(grade, unitName, score, total, wrong) {
  let data = loadData();
  if (!data.history) data.history = [];
  data.history.unshift({
    module: '数学',
    grade: grade,
    unitName: unitName,
    score: score,
    total: total,
    accuracy: Math.round(score / total * 100),
    time: Date.now(),
    wrong: Array.isArray(wrong) ? wrong : [],
    synced: false
  });
  if (data.history.length > 50) data.history = data.history.slice(0, 50);

  if (!data.stats) data.stats = {};
  if (!data.stats[grade]) data.stats[grade] = { totalDone: 0, totalCorrect: 0 };
  data.stats[grade].totalDone += total;
  data.stats[grade].totalCorrect += score;

  saveData(data);
}

// ============================================================
// 页面导航
// ============================================================
function showPage(pageId) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.getElementById('page-' + pageId).classList.add('active');
  window.scrollTo(0, 0);
}

// v79：底部导航已统一为全局一套（#globalNav）。
// 「统计 / 家长」是全局页（三科共用），其余按当前模块分发到数学 / 语文 / 英语。
function switchTab(tab) {
  const app = window.App;
  const mod = (app && app.module) || 'math';

  if (app && typeof app.setNavActive === 'function') app.setNavActive(tab);
  else {
    document.querySelectorAll('.nav-tab').forEach(t => t.classList.remove('active'));
    const t = document.querySelector(`.nav-tab[data-page="${tab}"]`);
    if (t) t.classList.add('active');
  }

  // 全局页：隐藏三个模块 Root，显示 #globalPages
  if (tab === 'stats' || tab === 'parent') {
    app.showGlobal('page-' + tab);
    // 两个渲染函数分别在 math.js / parent.js，缺任一都不该让整页导航崩掉
    if (tab === 'stats') { if (typeof renderStats === 'function') renderStats(); }
    else if (typeof renderParent === 'function') renderParent();
    return;
  }

  app.showRoot(mod);

  if (mod === 'chinese') {
    if (tab === 'home') { if (window.CN && CN.goHome) CN.goHome(); }
    else if (tab === 'wrong') { if (window.CN && CN.switchTab) CN.switchTab('wrong'); }
    else if (tab === 'exam') { if (window.CN && CN.showExam) CN.showExam(); }
    return;
  }

  if (mod === 'english') {
    if (typeof switchMain === 'function') {
      switchMain(tab === 'home' ? 'phonics' : (tab === 'exam' ? 'ipa' : 'wrong'));
    }
    return;
  }

  // 数学
  const backBtn = document.getElementById('backBtn');
  if (backBtn) backBtn.style.display = 'none';

  if (tab === 'home') { showPage('home'); renderHome(); }
  else if (tab === 'wrong') { showPage('wrong'); renderWrongBank(); }
  else if (tab === 'exam') { showPage('exam'); renderExamCenter(); }
}

function goBack() {
  if (state.quizMode === 'exam') {
    if (confirm('确定要交卷并退出本次考试吗？')) {
      if (state.examTimer) { clearInterval(state.examTimer); state.examTimer = null; }
      switchTab('exam');
      state.quizMode = null;
      state.quizQuestions = [];
      state.quizIndex = 0;
      state.quizScore = 0;
      state.quizCorrect = 0;
      state.quizWrong = 0;
      state.quizWrongQuestions = [];
  state.qStatus = [];
  state.wrongMap = {};
      state.qStatus = [];
      state.wrongMap = {};
    }
    return;
  }
  if (state.quizMode === 'unit' || state.quizMode === 'quick' || state.quizMode === 'wrong' || state.quizMode === 'upload') {
    if (confirm('确定要退出本次练习吗？')) {
      goHome();
    }
  } else {
    goHome();
  }
}

function goHome() {
  state.quizQuestions = [];
  state.quizIndex = 0;
  state.quizScore = 0;
  state.quizCorrect = 0;
  state.quizWrong = 0;
  state.quizWrongQuestions = [];
  state.qStatus = [];
  state.wrongMap = {};
  state.selectedAnswer = null;
  state.answered = false;
  state.examPaper = null;
  state.quizMode = null;
  if (state.examTimer) { clearInterval(state.examTimer); state.examTimer = null; }
  document.getElementById('examPaperHeader').style.display = 'none';
  switchTab('home');
}

// ============================================================
// v80：今日任务驾驶舱
// 解决「打开 App 后要自己想今天练什么」——首屏直接给倒计时、三科任务、薄弱提醒。
// 数据全部来自本地 localStorage（三科共用 math_practice_data），离线可用。
// ============================================================
const EXAM_DATE_KEY = 'lyj_exam_date';
const EXAM_DATE_DEFAULT = '2027-06-15';  // 小升初（家长确认：2027 年 6 月左右）
const SPRINT_START = '2026-09-01';       // 六年级开学，冲刺进度条起点
const TASK_DONE_KEY = 'lyj_task_done';   // 英语等无判分科目的「今日已完成」标记
const TASK_CLICK_KEY = 'lyj_task_click'; // 埋点：驾驶舱任务点击数（按天聚合，留 30 天）

const DAY_MS = 86400000;

function todayStart() {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  return d.getTime();
}

function _dateToTs(s) {
  const d = new Date(s + 'T00:00:00');
  return isNaN(d.getTime()) ? null : d.getTime();
}

function getExamDate() {
  try {
    const v = localStorage.getItem(EXAM_DATE_KEY);
    if (v && /^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
  } catch (e) { /* 隐私模式下 localStorage 不可用，走默认值 */ }
  return EXAM_DATE_DEFAULT;
}

function setExamDate() {
  const cur = getExamDate();
  const v = prompt('设置小升初考试日期（格式如 2027-06-15）', cur);
  if (v === null) return;
  const s = String(v).trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) { showToast('日期格式不对，示例：2027-06-15'); return; }
  if (_dateToTs(s) === null) { showToast('这个日期不存在，请重新输入'); return; }
  try { localStorage.setItem(EXAM_DATE_KEY, s); } catch (e) {}
  renderTodayPanel();
}

// 倒计时 + 六年级冲刺进度
function getCountdown() {
  const examTs = _dateToTs(getExamDate());
  const startTs = _dateToTs(SPRINT_START);
  const now = todayStart();
  const days = Math.round((examTs - now) / DAY_MS);
  const span = Math.max(1, Math.round((examTs - startTs) / DAY_MS));
  const passed = Math.min(span, Math.max(0, Math.round((now - startTs) / DAY_MS)));
  return { days: days, pct: Math.round(passed / span * 100), examDate: getExamDate() };
}

// 英语等科目没有判分记录，用「当日点击标记」判定完成
function _taskDoneObj() {
  try { return JSON.parse(localStorage.getItem(TASK_DONE_KEY)) || {}; } catch (e) { return {}; }
}
function _todayKey() {
  const d = new Date();
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}
function markTaskDone(k) {
  try {
    const o = _taskDoneObj();
    o[k] = _todayKey();
    localStorage.setItem(TASK_DONE_KEY, JSON.stringify(o));
  } catch (e) {}
}
function isTaskMarked(k) {
  return _taskDoneObj()[k] === _todayKey();
}

// 埋点：记录「打开首页 → 点任务开始练」的次数，用于连续观察驾驶舱是否真的带动练习
function recordTaskClick(k) {
  try {
    const o = JSON.parse(localStorage.getItem(TASK_CLICK_KEY)) || {};
    const d = _todayKey();
    if (!o[d]) o[d] = {};
    o[d][k] = (o[d][k] || 0) + 1;
    const keys = Object.keys(o).sort();
    while (keys.length > 30) { delete o[keys.shift()]; }
    localStorage.setItem(TASK_CLICK_KEY, JSON.stringify(o));
  } catch (e) {}
}

// 今日三科任务：数学/语文看当日练习记录，英语看当日标记
function getTodayTasks() {
  const data = loadData();
  const hist = data.history || [];
  const wrong = data.wrong || [];
  const s = todayStart();
  const e = s + DAY_MS;
  const practicedToday = function (mod) {
    return hist.some(function (h) { return (h.module || '数学') === mod && h.time >= s && h.time < e; });
  };
  const countWrong = function (mod) {
    return wrong.filter(function (w) { return (w.module || '数学') === mod; }).length;
  };

  const mathWrong = countWrong('数学');
  const cnWrong = countWrong('语文');
  const grade = state.currentGrade || 6;

  return [
    {
      key: 'math', subject: '数学',
      title: mathWrong > 0 ? '重做 ' + mathWrong + ' 道错题 + 1 组练习' : '完成 1 组' + (grade === 6 ? '六年级' : grade + '年级') + '练习（30 题）',
      hint: mathWrong > 0 ? '先清错题再练新题' : '保持手感',
      done: practicedToday('数学'),
      action: 'doMathTask()'
    },
    {
      key: 'chinese', subject: '语文',
      title: cnWrong > 0 ? '重做 ' + cnWrong + ' 道语文错题' : '完成 1 组语文练习（24 题）',
      hint: cnWrong > 0 ? '错题为王' : '课本同步 + 阅读',
      done: practicedToday('语文'),
      action: cnWrong > 0 ? 'doChineseWrongTask()' : 'doChineseTask()'
    },
    {
      key: 'english', subject: '英语',
      title: '拼读 1 课 + 复习本课单词',
      hint: '每日 15 分钟',
      done: isTaskMarked('english'),
      action: 'doEnglishTask()'
    }
  ];
}

function doMathTask() {
  recordTaskClick('math');
  selectGrade(state.currentGrade || 6);
}
function doChineseTask() {
  recordTaskClick('chinese');
  if (window.App) App.switchModule('chinese');
}
function doChineseWrongTask() {
  recordTaskClick('chinese');
  if (window.App) App.switchModule('chinese');
  if (window.CN && typeof CN.switchTab === 'function') CN.switchTab('wrong');
}
function doEnglishTask() {
  recordTaskClick('english');
  markTaskDone('english');
  if (window.App) App.switchModule('english');
}

// 薄弱单元：按错题所属单元聚合，取错题最多的前 n 个
function getWeakUnits(n) {
  const wrong = (loadData().wrong || []).filter(function (w) { return !w.module || w.module === '数学'; });
  const map = {};
  wrong.forEach(function (w) {
    const k = w.unitName || '未分类';
    if (!map[k]) map[k] = { name: k, count: 0, grade: w.grade || 0 };
    map[k].count += (w.count || 1);
    // 六年级错题优先，复习更贴近小升初
    if (w.grade === 6) map[k].grade = 6;
  });
  return Object.keys(map).map(function (k) { return map[k]; })
    .sort(function (a, b) { return b.count - a.count; })
    .slice(0, n || 3);
}

// 只按单元名反查 KNOWLEDGE_BASE 坐标，六年级优先（错题可能来自任何年级）。
// 注意：math.js 里已有一个 findUnitByName(grade, name)（供公式卡按「年级+单元名」查），
// 这里必须换名，否则函数声明提升会互相覆盖。
function findUnitCoordByName(name) {
  for (let g = 6; g >= 1; g--) {
    if (!KNOWLEDGE_BASE[g]) continue;
    for (let s = 1; s <= 2; s++) {
      const arr = KNOWLEDGE_BASE[g][s] || [];
      for (let i = 0; i < arr.length; i++) {
        if (arr[i] && arr[i].name === name) return { grade: g, sem: s, idx: i };
      }
    }
  }
  return null;
}

function practiceWeakUnit(name) {
  recordTaskClick('weak');
  const u = findUnitCoordByName(name);
  if (u) {
    startSpecialQuiz(u.grade, u.sem, u.idx);
  } else {
    showToast('该单元暂无专项练习，已打开错题库');
    switchTab('wrong');
  }
}

// 最近 7 天概览
function getWeekSummary() {
  const hist = (loadData().history || []);
  const end = todayStart() + DAY_MS;
  const start = end - 7 * DAY_MS;
  const w = hist.filter(function (h) { return h.time >= start && h.time < end; });
  const questions = w.reduce(function (s, h) { return s + (h.total || 0); }, 0);
  const correct = w.reduce(function (s, h) { return s + (h.score || 0); }, 0);
  return {
    times: w.length,
    questions: questions,
    accuracy: questions > 0 ? Math.round(correct / questions * 100) : 0
  };
}

function renderTodayPanel() {
  const box = document.getElementById('todayPanel');
  if (!box) return;  // PC 端（pc.html）无此节点，直接跳过

  const cd = getCountdown();
  const tasks = getTodayTasks();
  const doneN = tasks.filter(function (t) { return t.done; }).length;
  const weak = getWeakUnits(3);
  const week = getWeekSummary();

  // ---- 倒计时卡 ----
  let html = '<div class="dash-card dash-count">'
    + '<div class="dash-count-head">'
    + '<span class="dash-count-label">小升初冲刺</span>'
    + '<button class="dash-date-btn" onclick="setExamDate()">' + cd.examDate + ' ›</button>'
    + '</div>'
    + '<div class="dash-count-num">' + (cd.days >= 0 ? cd.days : 0) + '<span>天</span></div>'
    + '<div class="dash-count-sub">' + (cd.days >= 0 ? '距离小升初考试' : '考试日期已过，点右上角更新目标') + '</div>'
    + '<div class="dash-bar"><div class="dash-bar-fill ' + wpCls(cd.pct) + '"></div></div>'
    + '<div class="dash-count-foot">六年级冲刺进度 ' + cd.pct + '%</div>'
    + '</div>';

  // ---- 今日任务 ----
  html += '<div class="dash-card dash-tasks">'
    + '<div class="dash-head"><span class="dash-title">今日任务</span>'
    + '<span class="dash-badge' + (doneN === tasks.length ? ' done' : '') + '">' + doneN + '/' + tasks.length + '</span></div>';
  tasks.forEach(function (t) {
    html += '<div class="dash-task' + (t.done ? ' is-done' : '') + '">'
      + '<span class="dash-check' + (t.done ? ' ok' : '') + '">' + (t.done ? '✓' : '') + '</span>'
      + '<div class="dash-task-main">'
      + '<div class="dash-task-top"><span class="dash-subj ' + t.key + '">' + t.subject + '</span>'
      + '<span class="dash-task-title">' + t.title + '</span></div>'
      + '<div class="dash-task-hint">' + t.hint + '</div>'
      + '</div>'
      + (t.done ? '<span class="dash-task-done">已完成</span>'
        : '<button class="btn btn-primary btn-sm dash-go" onclick="' + t.action + '">去做</button>')
      + '</div>';
  });
  html += '</div>';

  // ---- 薄弱提醒 ----
  if (weak.length > 0) {
    html += '<div class="dash-card dash-weak">'
      + '<div class="dash-head"><span class="dash-title">薄弱提醒</span>'
      + '<span class="dash-sub">错题最多的单元</span></div>';
    weak.forEach(function (w) {
      html += '<div class="dash-weak-item">'
        + '<span class="dash-weak-name">' + w.name + '</span>'
        + '<span class="dash-weak-count">错 ' + w.count + ' 题</span>'
        + '<button class="btn btn-outline btn-sm dash-go" onclick="practiceWeakUnit(\'' + w.name.replace(/'/g, "\\'") + '\')">专项练</button>'
        + '</div>';
    });
    html += '</div>';
  }

  // ---- 本周概览 ----
  html += '<div class="dash-card dash-week">'
    + '<div class="dash-week-item"><div class="dash-week-val">' + week.times + '</div><div class="dash-week-lbl">本周练习</div></div>'
    + '<div class="dash-week-item"><div class="dash-week-val">' + week.questions + '</div><div class="dash-week-lbl">本周题量</div></div>'
    + '<div class="dash-week-item"><div class="dash-week-val">' + week.accuracy + '%</div><div class="dash-week-lbl">本周正确率</div></div>'
    + '</div>';

  box.innerHTML = html;
}

// ============================================================
// 首页渲染
// ============================================================
function renderHome() {
  let grid = document.getElementById('gradeGrid');
  // v78：pc.html 没有 #gradeGrid（年级网格属移动端首页），此处直接返回，
  // 避免 PC 端加载时抛出「Cannot set properties of null (setting 'innerHTML')」。
  if (!grid) return;
  let gradeNames = {
    1: '一年级', 2: '二年级', 3: '三年级',
    4: '四年级', 5: '五年级', 6: '六年级',
    7: '七年级', 8: '八年级', 9: '九年级'
  };

  // v79：年级已持久化，这里回显「当前年级」并高亮对应卡片，
  // 省得孩子每次重开都要重新点一遍六年级。
  let hintEl = document.getElementById('gradeCurrentHint');
  if (hintEl) {
    let cg = state.currentGrade || 6;
    hintEl.innerHTML = '<div class="grade-current-hint">当前年级 <strong>' + gradeNames[cg] +
      '</strong><button class="btn btn-primary btn-sm" onclick="selectGrade(' + cg + ')">继续学习 ›</button></div>';
  }

  grid.innerHTML = '';
  for (let g = 1; g <= 9; g++) {
    let card = document.createElement('div');
    card.className = 'grade-card' + (g === state.currentGrade ? ' active' : '');
    card.dataset.grade = g;
    card.innerHTML = `
      <div class="grade-badge">${g}</div>
      <div class="grade-name">${gradeNames[g]}</div>
      <div class="grade-sub">人教版 上下册</div>
    `;
    card.onclick = () => selectGrade(g);
    grid.appendChild(card);
  }

  // 最近练习
  let data = loadData();
  let recent = (data.history || []).slice(0, 3);
  let recentEl = document.getElementById('recentList');
  if (recent.length === 0) {
    recentEl.innerHTML = `<div class="empty-state"><div class="empty-icon u-c-lighter"><svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"><path d="M7 3h8l4 4v14H7z"/><path d="M15 3v4h4"/></svg></div><div class="empty-text">还没有练习记录，快开始吧！</div></div>`;
  } else {
    recentEl.innerHTML = recent.map(r => {
      let gradeNames2 = {1:'一年级',2:'二年级',3:'三年级',4:'四年级',5:'五年级',6:'六年级',7:'七年级',8:'八年级',9:'九年级'};
      let rateLabel = r.accuracy >= 90 ? '优秀' : r.accuracy >= 60 ? '良好' : '加油';
      return `<div class="card u-flex u-ac u-g10 u-p12-16">
        <div class="u-fs12 u-fw700 u-c-ok u-bg-ok-s2 u-p3-10 u-rpill">${rateLabel}</div>
        <div class="u-f1">
          <div class="u-fw600 u-fs14">${gradeNames2[r.grade]} · ${r.unitName}</div>
          <div class="u-fs12 u-c-lighter">${r.score}/${r.total} · 正确率${r.accuracy}%</div>
        </div>
        <div class="u-c-primary u-fw700 u-fs18">${r.accuracy}%</div>
      </div>`;
    }).join('');
  }

  // 专项练习板块：汇总所有年级中的“专项”单元
  renderSpecialSection();

  // v80：今日任务驾驶舱（倒计时 / 三科任务 / 薄弱提醒 / 本周概览）
  renderTodayPanel();
}

function renderSpecialSection() {
  const el = document.getElementById('specialList');
  if (!el) return;
  const gradeNames = {1:'一年级',2:'二年级',3:'三年级',4:'四年级',5:'五年级',6:'六年级',7:'七年级',8:'八年级',9:'九年级'};
  const found = [];
  for (let g = 1; g <= 9; g++) {
    const gradeUnits = KNOWLEDGE_BASE[g];
    if (!gradeUnits) continue;            // 防御：初中(7-9)由 math_junior.js 注入，缺失时不抛错
    for (let s = 1; s <= 2; s++) {
      const units = gradeUnits[s];
      if (!units) continue;
      units.forEach((unit, idx) => {
        if (unit.group === '专项' || unit.name.includes('专项')) found.push({ grade: g, sem: s, idx, unit });
      });
    }
  }
  if (found.length === 0) {
    el.innerHTML = '<div class="empty-text u-tc u-p8-0">暂无专项练习</div>';
    return;
  }
  el.innerHTML = found.map(item => `
    <div class="unit-item special-unit" onclick="startSpecialQuiz(${item.grade}, ${item.sem}, ${item.idx})">
      <div class="unit-number">专</div>
      <div class="unit-info">
        <div class="unit-name">${item.unit.name}</div>
        <div class="unit-meta">${gradeNames[item.grade]} · ${item.sem === 1 ? '上册' : '下册'}</div>
      </div>
      <div class="unit-arrow">›</div>
    </div>`).join('');
}

function startSpecialQuiz(grade, sem, idx) {
  state.currentGrade = grade;
  // v80：专项练习也会切年级，此前漏了持久化，下次打开又回到原年级
  if (window.App && typeof App.setGrade === 'function') App.setGrade('math', grade);
  state.currentSemester = sem;
  let unit = KNOWLEDGE_BASE[grade][sem][idx];
  showUnitDiagrams(unit, grade, sem, idx);
}

function selectGrade(grade) {
  state.currentGrade = grade;
  // v79：记住这次选择，下次打开直接落在该年级
  if (window.App && typeof App.setGrade === 'function') App.setGrade('math', grade);
  state.currentSemester = 1;
  showPage('units');
  document.getElementById('backBtn').style.display = 'block';
  document.getElementById('backBtn').onclick = () => goHome();
  renderUnits();
}

function switchSemester(sem) {
  state.currentSemester = sem;
  document.querySelectorAll('.semester-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.semester == sem);
  });
  renderUnits();
}

function renderUnits() {
  let gradeNames = {1:'一年级',2:'二年级',3:'三年级',4:'四年级',5:'五年级',6:'六年级',7:'七年级',8:'八年级',9:'九年级'};
  let semName = state.currentSemester == 1 ? '上册' : '下册';
  document.getElementById('unitsTitle').textContent = `${gradeNames[state.currentGrade]}${semName} · 单元列表`;

  let units = KNOWLEDGE_BASE[state.currentGrade][state.currentSemester];
  let listEl = document.getElementById('unitList');
  let data = loadData();

  // v49：含「课本」单元的年级（六年级）→ 课本同步 + 专项练习分区展示
  const isTbGrade = units.some(u => u.group === '课本');

  function unitItemHTML(unit, idx) {
    let isSpec = unit.group === '专项' || unit.name.includes('专项');
    let cls = 'unit-item' + (isSpec ? ' special-unit' : '');
    let records = (data.history || []).filter(h => h.grade === state.currentGrade && h.unitName === unit.name);
    let bestScore = records.length > 0 ? Math.max(...records.map(r => r.accuracy)) : 0;
    let metaText = records.length > 0
      ? `<span class="unit-progress">最高正确率 ${bestScore}%</span>`
      : `<span class="u-fs12 u-c-lighter">${getTypeName(unit.type)}${unit.summary ? ' · 含同步学习' : ''}</span>`;
    let badge = isSpec ? '专' : (unit.unit ? unit.unit : idx + 1);
    return `<div class="${cls}" onclick="startUnitQuiz(${idx})">
      <div class="unit-number">${badge}</div>
      <div class="unit-info">
        <div class="unit-name">${unit.name}</div>
        <div class="unit-meta">${metaText}</div>
      </div>
      <div class="unit-arrow">›</div>
    </div>`;
  }

  if (isTbGrade) {
    let html = '';
    let tb = units.filter(u => u.group === '课本');
    let sp = units.filter(u => u.group !== '课本');
    html += `<div class="section-title u-mt2">课本同步（${semName}）</div>`;
    tb.forEach(u => { html += unitItemHTML(u, units.indexOf(u)); });
    if (sp.length) {
      html += `<div class="section-title">专项练习</div>`;
      sp.forEach(u => { html += unitItemHTML(u, units.indexOf(u)); });
    }
    listEl.innerHTML = html;
    return;
  }

  listEl.innerHTML = '';
  units.forEach((unit, idx) => {
    let item = document.createElement('div');
    item.className = 'unit-item' + (unit.name.includes('专项') ? ' special-unit' : '');

    // 查看是否有练习记录
    let records = (data.history || []).filter(h => h.grade === state.currentGrade && h.unitName === unit.name);
    let bestScore = records.length > 0 ? Math.max(...records.map(r => r.accuracy)) : 0;

    let metaText = records.length > 0
      ? `<span class="unit-progress">最高正确率 ${bestScore}%</span>`
      : `<span class="u-fs12 u-c-lighter">${getTypeName(unit.type)}</span>`;

    item.innerHTML = `
      <div class="unit-number">${idx + 1}</div>
      <div class="unit-info">
        <div class="unit-name">${unit.name}</div>
        <div class="unit-meta">${metaText}</div>
      </div>
      <div class="unit-arrow">›</div>
    `;
    item.onclick = () => startUnitQuiz(idx);
    listEl.appendChild(item);
  });
}

function getTypeName(type) {
  const names = { basic: '基础运算', application: '应用题', shape: '图形认知', mixed: '综合练习' };
  return names[type] || type;
}

// ============================================================
// 答题逻辑
// ============================================================
function startUnitQuiz(unitIdx) {
  let unit = KNOWLEDGE_BASE[state.currentGrade][state.currentSemester][unitIdx];
  showUnitDiagrams(unit, state.currentGrade, state.currentSemester, unitIdx);
}

function showUnitDiagrams(unit, grade, sem, idx) {
  state.currentGrade = grade;
  state.currentSemester = sem;
  document.getElementById('specialIntroTitle').textContent = unit.name;

  const cardsEl = document.getElementById('diagramCards');
  const imgWrap = document.getElementById('specialIntroImgWrap');
  const imgEl = document.getElementById('specialIntroImg');
  const studyEl = document.getElementById('studyCards');
  const descEl = document.getElementById('specialIntroDesc');
  const btnEl = document.getElementById('specialIntroBtn');
  cardsEl.innerHTML = '';
  imgWrap.style.display = 'none';

  // ===== 同步学习三层结构（v49：知识点总结 / 万能公式 / 万能方法） =====
  const hasStudy = !!(unit.summary && unit.summary.length) || !!(unit.fidx && unit.fidx.length) || !!(unit.method && unit.method.length);
  if (studyEl) studyEl.innerHTML = '';
  if (hasStudy) {
    let h = '';
    // 1) 知识点总结卡（米白底）
    if (unit.summary && unit.summary.length) {
      h += '<div class="u-fs12 u-fw700 u-c-gold u-m4-0-8">知识点总结</div>';
      h += '<div class="sum-list u-bg-page-f u-bd-gold-s25 u-r12 u-p12-14b u-mb14">';
      unit.summary.forEach(function (s, i) {
        // v82：末项去间距交给 .sum-list > div:last-child，不再在 JS 里算索引
        h += '<div>';
        h += '<span class="u-c-gold u-fw700 u-noshrink">' + (i + 1) + '.</span><span>' + s + '</span></div>';
      });
      h += '</div>';
    }
    // 2) 万能公式卡（金色描边）
    if (unit.fidx && unit.fidx.length) {
      h += '<div class="u-fs12 u-fw700 u-c-gold u-m4-0-8">万能公式</div>';
      unit.fidx.forEach(function (f) {
        h += '<div class="fidx-card">';
        h += '<div class="u-fs125 u-fw700 u-c-gold u-mb4">' + f.t + '</div>';
        h += '<div class="u-fs135 u-lh17 u-c-primary-f">' + f.f + '</div>';
        if (f.warn) h += '<div class="u-fs115 u-c-red u-mt4">'+UI_ICON.svg('warn',13)+' ' + f.warn + '</div>';
        h += '</div>';
      });
    }
    // 3) 万能答题方法卡（黛蓝底）
    if (unit.method && unit.method.length) {
      h += '<div class="u-fs12 u-fw700 u-c-gold u-m4-0-8">万能答题方法</div>';
      h += '<div class="mtd-list u-bg-grad-dark u-r12 u-p12-14b u-mb6">';
      unit.method.forEach(function (m) {
        // v82：同上，末项去间距交给 .mtd-list > div:last-child（i 因此不再需要）
        h += '<div>';
        h += '<div class="u-fs12 u-fw700 u-c-palegold u-mb3">' + m.t + '</div>';
        h += '<div class="u-fs13 u-lh175 u-c-paper">' + m.s + '</div>';
        h += '</div>';
      });
      h += '</div>';
    }
    if (studyEl) studyEl.innerHTML = h;
    if (descEl) descEl.textContent = '先看知识点、公式和方法，再开始练习，效果加倍。';
    if (btnEl) btnEl.textContent = '开始练习';
  } else {
    if (descEl) descEl.textContent = '动手拖动下面的图形，先观察再答题。';
    if (btnEl) btnEl.textContent = '开始答题';
  }

  // 静态方法图（若有）
  if (unit.introImg) {
    imgWrap.style.display = 'block';
    imgEl.src = unit.introImg;
  }
  // 交互式探索（若有）
  if (unit.interactiveIntro) {
    const card = document.createElement('div');
    card.className = 'diag-card';
    card.innerHTML = '<div class="diag-card-title">'+UI_ICON.svg('film',16)+' 动手探索</div><div class="diag-card-body"></div><div class="diag-card-hint">'+UI_ICON.svg('pointer',14)+' 拖动滑块，看角的变化</div>';
    cardsEl.appendChild(card);
    renderShapeExplore(card.querySelector('.diag-card-body'));
  }
  // 通用交互动图（按知识点映射，每单元 1~3 个）
  const diags = (typeof getUnitDiagrams === 'function') ? getUnitDiagrams(unit, grade, sem) : [];
  diags.forEach(d => {
    const card = document.createElement('div');
    card.className = 'diag-card';
    card.innerHTML = '<div class="diag-card-title">'+UI_ICON.svg('film',16)+' ' + d.title + '</div><div class="diag-card-body"></div><div class="diag-card-hint">' + (d.hint || UI_ICON.svg('pointer',14)+' 动手试一试，看图形怎么变') + '</div>';
    cardsEl.appendChild(card);
    try { d.fn(card.querySelector('.diag-card-body'), d.opts || {}); }
    catch (e) { console.error('diagram render error', d.title, e); }
  });

  document.getElementById('specialIntroBtn').onclick = () => askUnitQuizSettings(idx, grade, sem, unit.name);
  document.getElementById('backBtn').style.display = 'block';
  document.getElementById('backBtn').onclick = () => goHome();
  showPage('special-intro');
}

// 交互式图形探索器：拖动滑块看角度变化
function renderShapeExplore(container){
  let deg = 45;
  function angType(d){
    if(d===0) return {label:'零角',color:'#9AA0AB',cls:''};
    if(d>0&&d<90) return {label:'锐角 &lt; 90°',color:'#4E8C6E',cls:'锐角'};
    if(d===90) return {label:'直角 = 90°',color:'#E57373',cls:'直角'};
    if(d>90&&d<180) return {label:'钝角 &gt; 90°',color:'#C08A3E',cls:'钝角'};
    if(d===180) return {label:'平角 = 180°',color:'#6B7894',cls:'平角'};
    if(d>180&&d<360) return {label:'优角 &gt; 180°',color:'#B4945A',cls:'优角'};
    return {label:'周角 = 360°',color:'#3E4A63',cls:'周角'};
  }
  function draw(d){
    let cx=180,cy=160,r=100,ar=70, a=Math.PI*d/180;
    let ex=cx+r*Math.cos(a), ey=cy-r*Math.sin(a);
    let pts=[]; for(let k=0;k<=20;k++){let dd=d*k/20,aa=Math.PI*dd/180;pts.push(`${(cx+ar*Math.cos(aa)).toFixed(1)},${(cy-ar*Math.sin(aa)).toFixed(1)}`);}
    let t=angType(d);
    return `<svg class="u-w100 u-xw360" viewBox="0 0 360 300">
      <!-- 量角器背景 -->
      <path d="M ${cx-r} ${cy} A ${r} ${r} 0 0 1 ${cx+r} ${cy}" fill="rgba(180,148,90,0.05)" stroke="#B4945A" stroke-width="1"/>
      <line x1="${cx-r}" y1="${cy}" x2="${cx+r}" y2="${cy}" stroke="#B4945A" stroke-width="0.8"/>
      ${[0,30,60,90,120,150,180].map(dd=>{
        let aa=Math.PI*dd/180;
        let lx=cx+(r-12)*Math.cos(aa), ly=cy-(r-12)*Math.sin(aa);
        return `<text x="${lx.toFixed(1)}" y="${(ly+4).toFixed(1)}" text-anchor="middle" font-size="9" fill="#9AA0AB">${dd}</text>`;
      }).join('')}
      ${[0,30,60,90,120,150,180].map(dd=>{
        let aa=Math.PI*dd/180;
        return `<line x1="${(cx+(r-6)*Math.cos(aa)).toFixed(1)}" y1="${(cy-(r-6)*Math.sin(aa)).toFixed(1)}" x2="${(cx+r*Math.cos(aa)).toFixed(1)}" y2="${(cy-r*Math.sin(aa)).toFixed(1)}" stroke="#B4945A" stroke-width="0.7"/>`;
      }).join('')}
      <!-- 角的边 -->
      <line x1="${cx}" y1="${cy}" x2="${cx+r}" y2="${cy}" stroke="#3E4A63" stroke-width="2.5" stroke-linecap="round"/>
      <line x1="${cx}" y1="${cy}" x2="${ex.toFixed(1)}" y2="${ey.toFixed(1)}" stroke="${t.color}" stroke-width="3" stroke-linecap="round"/>
      <circle cx="${cx}" cy="${cy}" r="3.5" fill="#3E4A63"/>
      <!-- 角的弧 -->
      <polyline points="${pts.join(' ')}" fill="none" stroke="${t.color}" stroke-width="2.5"/>
      <!-- 角度数字 -->
      <text x="${(cx+ar*Math.cos(a/2)).toFixed(1)}" y="${(cy-ar*Math.sin(a/2)-8).toFixed(1)}" text-anchor="middle" font-size="14" font-weight="bold" fill="${t.color}">${d}°</text>
      <!-- 类型文字 -->
      <rect x="${cx-45}" y="228" width="90" height="24" rx="12" fill="${t.color}" opacity="0.15"/>
      <text x="${cx}" y="245" text-anchor="middle" font-size="13" font-weight="bold" fill="${t.color}">${d}° — ${t.label.replace(/<[^>]*>/g,'')}</text>
    </svg>`;
  }
  container.innerHTML = `
    <div class="u-m12-0">
      <div class="u-fs13 u-c-light u-mb8 u-tc">
        ${UI_ICON.svg('pointer',14)}拖动下面滑块，观察角从<strong class="u-c-green">锐角</strong>→<strong class="u-c-coral">直角</strong>→<strong class="u-c-amber">钝角</strong>→<strong class="u-c-steel">平角</strong>→<strong class="u-c-ink">周角</strong>的全过程
      </div>
      <div id="shapeExploreSvg">${draw(45)}</div>
      <div class="u-p8-0">
        <input type="range" id="shapeExploreSlider" min="0" max="360" value="45" step="1"
          class="angle-scale-range">
        <input class="u-w100 u-h8 u-mt6 u-appear0 u-bg-trans u-r4 u-outline0 u-cp u-bd-border" type="range" id="shapeExploreSlider2" min="0" max="360" value="45" step="1">
      </div>
      <div class="u-tc u-fs13 u-c-lighter u-mt4">
        ${UI_ICON.svg('info',15)}上面是精细滑块(步长1°)，下面是快速滑块
      </div>
    </div>`;
  let svgEl=document.getElementById('shapeExploreSvg');
  function update(v){let d=parseInt(v)||0;if(svgEl)svgEl.innerHTML=draw(d);}
  let s1=document.getElementById('shapeExploreSlider');
  let s2=document.getElementById('shapeExploreSlider2');
  if(s1)s1.addEventListener('input',function(){update(this.value);if(s2)s2.value=this.value;});
  if(s2)s2.addEventListener('input',function(){update(this.value);if(s1)s1.value=this.value;});
}

// v73：单元练习出题。
// diff：1 基础 / 2 提高 / 3 拓展（沿用站内既有难度命名，默认基础）。
// 策略（用户确认）：反复调用 unit.gen() 生成新题，直到凑满 30 道「视觉上互不相同」的题；
// 达到采样上限仍凑不满时按实际上限出卷——克隆凑数等于让孩子连做 30 道一模一样的题。
// v86 P0：单元练习「跨场次」题面记忆——记录每个单元近期出过的题面，
// 下次练习优先出没练过的；单元题面枯竭时按「最久没练」的顺序回收复用。
// 只存题面 key（不含答案），按单元分桶、每桶最多保留 UNIT_SEEN_CAP 条。
const UNIT_SEEN_KEY = 'math_unit_seen_v1';
const UNIT_SEEN_CAP = 300;
function unitSeenSlot(g, s, i) { return g + '_' + s + '_' + i; }
function loadUnitSeenMap() {
  try { return JSON.parse(localStorage.getItem(UNIT_SEEN_KEY) || '{}') || {}; } catch (e) { return {}; }
}
// 返回 { seen:Set, rank:Map }，rank 越小 = 越久没练过
function unitSeenCtx(g, s, i) {
  const m = loadUnitSeenMap();
  const arr = m[unitSeenSlot(g, s, i)] || [];
  const rank = new Map();
  arr.forEach((k, idx) => { if (!rank.has(k)) rank.set(k, idx); });
  return { seen: new Set(arr), rank: rank };
}
function markUnitSeen(g, s, i, keys) {
  if (!keys || !keys.length) return;
  try {
    const m = loadUnitSeenMap();
    const slot = unitSeenSlot(g, s, i);
    const arr = (m[slot] || []).concat(keys);
    const st = new Set(), out = [];
    for (let j = arr.length - 1; j >= 0; j--) { if (st.has(arr[j])) continue; st.add(arr[j]); out.unshift(arr[j]); }
    m[slot] = out.slice(-UNIT_SEEN_CAP);
    localStorage.setItem(UNIT_SEEN_KEY, JSON.stringify(m));
  } catch (e) {}
}
// 单元题面已全部练过时清空记忆，让题库重新循环（避免永远出不到「新题」）
function resetUnitSeen(g, s, i) {
  try {
    const m = loadUnitSeenMap();
    delete m[unitSeenSlot(g, s, i)];
    localStorage.setItem(UNIT_SEEN_KEY, JSON.stringify(m));
  } catch (e) {}
}

function buildUnitQuizQuestions(unit, diff, want, ctx) {
  want = want || UNIT_QUIZ_LENGTH;
  // v86 P0：候选池扩到 want*3（原只凑 want 道，导致 6:3:1 分档后
  // 基础档只剩 18 题、提高档 9 题、拓展档 3 题 —— 与「固定 30 题」不符）。
  const CAND = Math.max(want * 3, 90);
  const seenSet = (ctx && ctx.seen) || null;
  const rankMap = (ctx && ctx.rank) || null;
  let seen = new Set();
  let fresh = [], old = [];
  let stall = 0;
  const push = q => {
    if (!q || !q.question || q.answer == null || q.answer === undefined) return false;
    let k = visKey(q);
    if (seen.has(k)) return false;
    seen.add(k);
    if (seenSet && seenSet.has(k)) old.push(q); else fresh.push(q);
    return true;
  };
  while (fresh.length < CAND && stall < UNIT_GEN_MAX_STALL) {
    let g;
    try { g = unit.gen(); } catch (e) { stall++; continue; }
    let arr = Array.isArray(g) ? g : [g];
    let got = false;
    arr.forEach(q => { if (push(q)) got = true; });
    stall = got ? 0 : stall + 1;      // 连续拿不到新题面 = 生成器已榨干
  }
  // 新鲜题不够时用旧题补齐：优先挑「最久没练过」的，避免连场撞题
  let cands = fresh.slice();
  if (cands.length < want && old.length) {
    if (rankMap && rankMap.size) old.sort((a, b) => (rankMap.get(visKey(a)) || 0) - (rankMap.get(visKey(b)) || 0));
    else shuffleArr(old);
    cands = cands.concat(old.slice(0, Math.max(0, CAND - cands.length)));
  }
  if (!cands.length) return [];
  tagRelativeDifficulty(cands);
  if (!diff) diff = 1;
  // v86：命中难度档优先，不足时按「由易到难」用相邻档补齐到 want（不再只给 18/9/3 题）
  const order = diff === 2 ? [2, 1, 3] : diff === 3 ? [3, 2, 1] : [1, 2, 3];
  let out = [];
  order.forEach(function (d) {
    if (out.length >= want) return;
    let band = cands.filter(q => questionDifficulty(q) === d);
    shuffleArr(band);
    out = out.concat(band.slice(0, want - out.length));
  });
  if (!out.length) { shuffleArr(cands); out = cands.slice(0, want); }
  // 卷面顺序：基础 → 提高 → 拓展
  out.sort((a, b) => (questionDifficulty(a) - questionDifficulty(b)));
  return out;
}

// v73：单元练习的入口——先弹「练习设置」选难度，再开始练习。
// 从「错题同类练习」等快捷入口进来时不弹层（那里已经明确知道要练什么）。
function askUnitQuizSettings(idx, grade, sem, unitName) {
  if (typeof openPracticeSettings !== 'function') { beginUnitQuiz(idx, grade, sem, 1); return; }
  openPracticeSettings({
    title: '练习设置',
    note: (unitName ? unitName + ' · ' : '') + '每次固定 30 题',
    okText: '开始练习',
    onStart: function (diff) { beginUnitQuiz(idx, grade, sem, diff); },
  });
}

function beginUnitQuiz(idx, grade, sem, diff) {
  let unit = KNOWLEDGE_BASE[grade][sem][idx];
  // v51：practiceSimilarWrong 等入口直连时不经过 showUnitDiagrams，须在此确保年级/学期上下文
  state.currentGrade = grade;
  state.currentSemester = sem;
  state.quizMode = 'unit';
  state.quizTitle = unit.name;
  state.quizQuestions = [];
  if (unit.paper) {
    // v51：整卷题组也做相对难度打标（浅拷贝避免污染题池），卷面显示难度徽标
    let arr = unit.gen();
    if (Array.isArray(arr) && arr.length && !arr[0].diff) {
      arr = arr.map(q => Object.assign({}, q));
      tagRelativeDifficulty(arr);
    }
    state.quizQuestions = arr;
  } else {
    let first = unit.gen();
    if (Array.isArray(first)) {
      // gen 已返回完整题组（如角度计算：一次从题库随机抽 N 道）
      state.quizQuestions = first;
    } else {
      // v86：带上该单元的「已练题面」上下文，优先出没练过的题
      const ctx = unitSeenCtx(grade, sem, idx);
      state.quizQuestions = buildUnitQuizQuestions(unit, diff || 1, UNIT_QUIZ_LENGTH, ctx);
    }
  }
  // v86：本场题面入库，下一场优先避开；题面已练遍时自动清空记忆重新循环
  if (!unit.paper && state.quizQuestions && state.quizQuestions.length) {
    try {
      const keys = state.quizQuestions.map(q => visKey(q));
      const ctxNow = unitSeenCtx(grade, sem, idx);
      if (ctxNow.seen.size >= UNIT_SEEN_CAP && keys.every(k => ctxNow.seen.has(k))) resetUnitSeen(grade, sem, idx);
      markUnitSeen(grade, sem, idx, keys);
    } catch (e) {}
  }
  state.quizIndex = 0;
  state.quizScore = 0;
  state.quizCorrect = 0;
  state.quizWrong = 0;
  state.quizWrongQuestions = [];
  state.qStatus = [];
  state.wrongMap = {};
  state.userAnswers = [];
  state.quizStartTime = Date.now();
  showPage('quiz');
  document.getElementById('backBtn').style.display = 'block';
  document.getElementById('backBtn').onclick = () => goBack();
  renderQuestion();
}

function startQuickPractice(mode) {
  state.quizMode = 'quick';
  state.quizTitle = mode === 'basic' ? '基础运算' : '综合练习';
  state.quizQuestions = [];
  let gen = mode === 'basic' ? quickBasicGen : quickMixedGen;
  for (let i = 0; i < QUIZ_LENGTH; i++) {
    state.quizQuestions.push(gen());
  }
  state.quizIndex = 0;
  state.quizScore = 0;
  state.quizCorrect = 0;
  state.quizWrong = 0;
  state.quizWrongQuestions = [];
  state.qStatus = [];
  state.wrongMap = {};
  state.userAnswers = [];
  state.quizStartTime = Date.now();
  showPage('quiz');
  document.getElementById('backBtn').style.display = 'block';
  document.getElementById('backBtn').onclick = () => goBack();
  renderQuestion();
}

// v84 P4：快速测评入口（10 题 · 5 分钟）。跨单元随机抽题，快速测出各知识点掌握情况；
// 交卷后成绩页生成「知识点掌握度」报告。复用答题/判分/零打字输入全链路。
function startQuickAssess() {
  state.currentGrade = state.currentGrade || 6;
  state.currentSemester = state.currentSemester || 1;
  state.quizMode = 'quick';
  state.quizTitle = '快速测评';
  let allUnits = (KNOWLEDGE_BASE[state.currentGrade] && KNOWLEDGE_BASE[state.currentGrade][state.currentSemester]) || [];
  let pool = [];
  allUnits.forEach(function (u) {
    if (!u || typeof u.gen !== 'function') return;
    for (let k = 0; k < 8; k++) {
      try {
        let r = u.gen();
        (Array.isArray(r) ? r : [r]).forEach(function (x) { if (x && x.question) pool.push(x); });
      } catch (e) {}
    }
  });
  shuffleArr(pool);
  let seen = new Set(), picked = [];
  for (let i = 0; i < pool.length && picked.length < 10; i++) {
    let key = pool[i].question + '|' + pool[i].answer;
    if (seen.has(key)) continue;
    seen.add(key);
    picked.push(pool[i]);
  }
  if (picked.length < 10) picked = picked.concat(pool.slice(0, 10 - picked.length));
  state.quizQuestions = picked.slice(0, 10);
  state.quizIndex = 0;
  state.quizScore = 0;
  state.quizCorrect = 0;
  state.quizWrong = 0;
  state.quizWrongQuestions = [];
  state.qStatus = [];
  state.wrongMap = {};
  state.userAnswers = [];
  state.quizStartTime = Date.now();
  showPage('quiz');
  document.getElementById('backBtn').style.display = 'block';
  document.getElementById('backBtn').onclick = () => goBack();
  renderQuestion();
  // 5 分钟倒计时自动交卷（测评轻量，只做提交，不显示独立计时器）
  if (state.examTimer) { clearInterval(state.examTimer); state.examTimer = null; }
  state.examEndTime = Date.now() + 5 * 60 * 1000;
  state.examTimer = setInterval(function () {
    if (Date.now() >= state.examEndTime) { clearInterval(state.examTimer); state.examTimer = null; if (!state.answered || true) finishQuiz(); }
  }, 1000);
}

function startWrongReview() {
  let wrongBank = getWrongBank();
  if (wrongBank.length === 0) {
    showToast('错题库是空的！');
    return;
  }
  state.quizMode = 'wrong';
  state.quizTitle = '错题重练';
  // 从错题库中随机取全部错题，最多30题
  let shuffled = [...wrongBank].sort(() => Math.random() - 0.5);
  let picked = shuffled.slice(0, Math.max(QUIZ_LENGTH, wrongBank.length));
  state.quizQuestions = picked.map(w => w.question);
  state.quizWrongSourceIds = picked.map(w => w.id);
  state.quizIndex = 0;
  state.quizScore = 0;
  state.quizCorrect = 0;
  state.quizWrong = 0;
  state.quizWrongQuestions = [];
  state.qStatus = [];
  state.wrongMap = {};
  state.userAnswers = [];
  state.quizStartTime = Date.now();
  showPage('quiz');
  document.getElementById('backBtn').style.display = 'block';
  document.getElementById('backBtn').onclick = () => goBack();
  renderQuestion();
}

// ============================================================
// 数据备份与同步（导出 / 导入）
// ============================================================
function downloadBlob(content, filename, mime) {
  let blob = new Blob([content], { type: mime + ';charset=utf-8' });
  let url = URL.createObjectURL(blob);
  let a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 3000);
}

function stamp() {
  let d = new Date();
  let p = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}_${p(d.getHours())}${p(d.getMinutes())}`;
}

function exportUserData() {
  let data = loadData();
  let payload = {
    app: '吕泳冀学习站',
    version: 1,
    exportedAt: new Date().toISOString(),
    data: data,
  };
  downloadBlob(JSON.stringify(payload, null, 2), `数学练习数据_${stamp()}.json`, 'application/json');
  showToast('已导出，可发送到电脑再导入');
}

function importUserData(event) {
  let file = event.target.files && event.target.files[0];
  if (!file) return;
  let reader = new FileReader();
  reader.onload = e => {
    try {
      let obj = JSON.parse(e.target.result);
      let incoming = obj && obj.data ? obj.data : obj;
      if (!incoming || typeof incoming !== 'object') throw new Error('格式不对');

      let cur = loadData();
      // 错题合并去重
      let merged = (cur.wrong || []).slice();
      let keys = new Set(merged.map(w => (w.question && w.question.question) + '|' + (w.question && w.question.answer)));
      (incoming.wrong || []).forEach(w => {
        let k = (w.question && w.question.question) + '|' + (w.question && w.question.answer);
        if (!keys.has(k)) { keys.add(k); merged.push(w); }
      });
      // 历史合并按时间倒序取前50条
      let history = (cur.history || []).concat(incoming.history || [])
        .sort((a, b) => (b.time || 0) - (a.time || 0)).slice(0, 50);
      // 统计相加
      let stats = Object.assign({}, cur.stats || {});
      Object.keys(incoming.stats || {}).forEach(g => {
        if (!stats[g]) stats[g] = { totalDone: 0, totalCorrect: 0 };
        stats[g].totalDone += incoming.stats[g].totalDone || 0;
        stats[g].totalCorrect += incoming.stats[g].totalCorrect || 0;
      });

      saveData({ wrong: merged, history: history, stats: stats });
      showToast(`导入成功：错题 ${merged.length} 道`);
      renderStats();
    } catch (err) {
      showToast('导入失败：文件格式不正确');
    }
    event.target.value = '';
  };
  reader.readAsText(file, 'utf-8');
}

function exportWrongBookText() {
  let bank = getWrongBank();
  if (bank.length === 0) { showToast('错题库是空的'); return; }
  let lines = ['小学数学错题本', '导出时间：' + new Date().toLocaleString('zh-CN'), '共 ' + bank.length + ' 道', ''];
  bank.forEach((w, i) => {
    let q = w.question || {};
    lines.push(`${i + 1}. 【${w.unitName || '未知单元'}】${(q.question || '').replace(/\n/g, ' ')}`);
    if (q.options && q.options.length) {
      let labels = ['A', 'B', 'C', 'D'];
      // v85：labels 只有 A~D，选项超 4 个时旧版导出「undefined.」
      lines.push('   选项：' + q.options.map((o, k) => (labels[k] || String.fromCharCode(65 + k)) + '. ' + (typeof o === 'object' ? o.value : o)).join('　'));
    }
    lines.push(`   正确答案：${q.answer}　我的答案：${w.userAnswer}　错误次数：${w.count || 1}`);
    lines.push('');
  });
  downloadBlob(lines.join('\n'), `错题本_${stamp()}.txt`, 'text/plain');
  showToast('错题本已导出');
}

// ============================================================
// 考试系统：单元考 / 月考 / 期中 / 期末
// ============================================================
const EXAM_TYPES = [
  { key: 'unit',  icon: UI_ICON.svg('book',20), name: '单元考试', desc: '针对单个单元的达标检测 · 100分' },
  { key: 'month', icon: UI_ICON.svg('calendar',20), name: '月　考',   desc: '阶段性综合测试（累计单元）· 100分' },
  { key: 'mid',   icon: UI_ICON.svg('book',20), name: '期中考试', desc: '半册内容综合测试 · 100分' },
  { key: 'final', icon: '', name: '期末考试', desc: '整册内容综合测试 · 100分' },
];

// ============================================================
// v73：卷面结构改为「广西近 10 年小学期末真题」结构（人教版）
//
// 采样来源（2020-2025 学年各地期末质量监测卷）：
//   南宁六上（人教版）：填空9 / 作图3 / 选择10 / 计算3 / 解答7 = 32 题
//   玉林六上（人教版）：填空9 / 选择12 / 计算3 / 作图1 / 解答6 = 31 题
//   钦州六上（北师版）：选择 8×2 分 / 填空 24 分 / 计算 30 分 / 看图列式 / 解决问题
//   桂林六上（北师版）：选择 5×2 / 填空 10×2 / 计算 30 / 操作 10 / 解决问题 30
//   南宁二上（2020 真卷）：选择 / 填空 24 分 / 计算 / 判断 5 分 / 操作 9 分 / 解决问题 27 分
//
// 归纳出的共性权重：填空 18~24 · 判断 5~10 · 选择 10~20 · 计算 24~30 ·
//                   操作 4~10 · 解决问题 20~30，满分 100。
// 低年级（1-2）判断与操作占比更高（重动手与辨析），
// 高年级（3-6）解决问题占比更高（重综合应用）。
//
// 相比旧结构（填空/选择/计算/应用四区）的实质差异：
//   ① 新增「判断题」——广西卷 1-6 年级全学段必有，旧题库完全没有这类题；
//   ② 原 v73 加的「操作题」分区在 v73.2 已移除：屏幕无法真实手绘作图，带图选择题
//      承担时选项会暴露图形答案造成泄题，故整卷重平衡为五区固定 30 题 / 100 分。
// ============================================================
const GX_PAPER_TOTAL = 30;                     // 真题整卷题数（满分 100）
const GX_CNUM = ['一', '二', '三', '四', '五', '六'];
// [分区键, 分区名, 题数, 该区总分] —— v73.2 起去掉「操作题」分区（屏幕无法真实作图，
// 原题用带图选择题承担会出现「无图选项暴露答案」的泄题问题），整卷重平衡为五区固定 30 题 / 100 分。
const GX_SECTIONS_LOW = [                      // 1-2 年级
  { key: 'fill',   name: '填空题',   count: 9, score: 18 },
  { key: 'judge',  name: '判断题',   count: 5, score: 10 },
  { key: 'choice', name: '选择题',   count: 5, score: 10 },
  { key: 'calc',   name: '计算题',   count: 5, score: 30 },
  { key: 'app',    name: '解决问题', count: 6, score: 32 },
];
const GX_SECTIONS_HIGH = [                     // 3-6 年级
  { key: 'fill',   name: '填空题',   count: 10, score: 20 },
  { key: 'judge',  name: '判断题',   count: 5, score: 5  },
  { key: 'choice', name: '选择题',   count: 5, score: 10 },
  { key: 'calc',   name: '计算题',   count: 5, score: 30 },
  { key: 'app',    name: '解决问题', count: 5, score: 35 },
];

// 把 total 分拆到 n 个小题（最大余数法，余数摊到前几题）
function splitScores(total, n) {
  n = Math.max(1, n | 0);
  let base = Math.floor(total / n), r = total - base * n, arr = [];
  for (let k = 0; k < n; k++) arr.push(base + (k < r ? 1 : 0));
  return arr;
}

// 分区小标题的分值说明：各题同分写「每题N分，共M分」，否则写「共M分」
function gxSectionScoreText(scores) {
  let total = scores.reduce((a, b) => a + b, 0);
  let same = scores.every(v => v === scores[0]);
  return same ? `（每题${scores[0]}分，共${total}分）` : `（共${total}分）`;
}

// 生成分区配置：capQ 为整卷题数（真题为 30；单元出题能力不足时等比收缩）
function buildPaperStructure(grade, capQ) {
  const base = (grade <= 2) ? GX_SECTIONS_LOW : GX_SECTIONS_HIGH;
  let counts, scoresArr;
  if (capQ >= GX_PAPER_TOTAL) {
    counts = base.map(s => s.count);
    scoresArr = base.map(s => splitScores(s.score, s.count));
  } else {
    // 权重等比收缩（最大余数法保证合计 = capQ，且每区至少 1 题）
    const W = base.map(s => s.score);
    const sumW = W.reduce((a, b) => a + b, 0);
    counts = W.map(w => Math.max(1, Math.round(capQ * w / sumW)));
    let diff = capQ - counts.reduce((a, b) => a + b, 0);
    const order = [3, 4, 0, 2, 1];             // 余量优先加/减在权重大的区（计算/解决/填空/选择/判断）
    let guard = 0;
    while (diff !== 0 && guard++ < 400) {
      let moved = false;
      for (const i of order) {
        if (i >= counts.length) continue;
        if (diff > 0) { counts[i]++; diff--; moved = true; }
        else if (counts[i] > 1) { counts[i]--; diff++; moved = true; }
        if (diff === 0) break;
      }
      if (!moved) break;
    }
    // 收缩时各区总分按题数占比重算，保证整卷仍是 100 分
    scoresArr = counts.map((n, i) => splitScores(Math.round(W[i] * n / base[i].count), n));
  }
  return base.map((s, i) => ({
    key: s.key,
    count: counts[i],
    scores: scoresArr[i],
    score: scoresArr[i][0] || 1,
    title: GX_CNUM[i] + '、' + s.name + '。' + gxSectionScoreText(scoresArr[i]),
  }));
}

const examState = {
  type: null,
  grade: 1,
  semester: 1,
  unitIdx: 0,
  month: 1,
};

function renderExamCenter() {
  // 考试类型卡片
  let html = '';
  EXAM_TYPES.forEach(t => {
    html += `<div class="exam-type-card ${examState.type === t.key ? 'selected' : ''}" onclick="selectExamType('${t.key}')">
      <div class="exam-type-icon">${t.icon}</div>
      <div class="u-f1">
        <div class="exam-type-name">${t.name}</div>
        <div class="exam-type-desc">${t.desc}</div>
      </div>
      <div class="u-c-ok u-fs18 u-fw700">${examState.type === t.key ? '✓' : '›'}</div>
    </div>`;
  });
  document.getElementById('examTypeList').innerHTML = html;

  // 年级
  let gHtml = '';
  for (let g = 1; g <= 9; g++) {
    gHtml += `<button class="chip ${examState.grade === g ? 'selected' : ''}" onclick="selectExamGrade(${g})">${g}年级</button>`;
  }
  document.getElementById('examGradeBtns').innerHTML = gHtml;

  // 册别
  document.querySelectorAll('#examSemesterRow .chip').forEach(c => {
    c.classList.toggle('selected', Number(c.dataset.sem) === examState.semester);
  });

  let hasType = !!examState.type;
  document.getElementById('examConfigCard').style.display = hasType ? 'block' : 'none';
  document.getElementById('startExamBtn').style.display = hasType ? 'block' : 'none';

  let units = (KNOWLEDGE_BASE[examState.grade] && KNOWLEDGE_BASE[examState.grade][examState.semester]) || [];
  // v49：含课本单元的年级，月考次数按课本单元数计算（专项不进整册组卷）
  let tbUnits = units.filter(u => u.group === '课本');
  let scopeUnits = tbUnits.length ? tbUnits : units;

  // 单元选择（仅单元考；索引基于原始数组，含专项）
  let unitRow = document.getElementById('examUnitRow');
  if (examState.type === 'unit') {
    unitRow.style.display = 'flex';
    if (examState.unitIdx >= units.length) examState.unitIdx = 0;
    let uHtml = '';
    units.forEach((u, i) => {
      let label = (u.group === '课本') ? `第${u.unit}单元 ${u.name}` : u.name;
      uHtml += `<button class="chip chip-sm ${examState.unitIdx === i ? 'selected' : ''}" onclick="selectExamUnit(${i})">${label}</button>`;
    });
    document.getElementById('examUnitBtns').innerHTML = uHtml;
  } else {
    unitRow.style.display = 'none';
  }

  // 月考次数（仅月考，按课本单元范围）
  let monthRow = document.getElementById('examMonthRow');
  if (examState.type === 'month') {
    monthRow.style.display = 'flex';
    let maxMonth = Math.max(1, Math.ceil(scopeUnits.length / 2));
    if (examState.month > maxMonth) examState.month = 1;
    let mHtml = '';
    for (let m = 1; m <= maxMonth; m++) {
      let cover = Math.min(scopeUnits.length, m * 2);
      mHtml += `<button class="chip chip-sm ${examState.month === m ? 'selected' : ''}" onclick="selectExamMonth(${m})">第${m}次月考（1~${cover}单元）</button>`;
    }
    document.getElementById('examMonthBtns').innerHTML = mHtml;
  } else {
    monthRow.style.display = 'none';
  }

  // 开始按钮文案
  if (hasType) {
    let t = EXAM_TYPES.find(x => x.key === examState.type);
    document.getElementById('startExamBtn').textContent = `开始${t.name.replace(/\s/g, '')}`;
  }
}

function selectExamType(key) { examState.type = key; renderExamCenter(); }
function selectExamGrade(g) { examState.grade = g; examState.unitIdx = 0; examState.month = 1; renderExamCenter(); }
function selectExamSemester(s) { examState.semester = s; examState.unitIdx = 0; examState.month = 1; renderExamCenter(); }
function selectExamUnit(i) { examState.unitIdx = i; renderExamCenter(); }
function selectExamMonth(m) { examState.month = m; renderExamCenter(); }

// 根据考试类型确定考查范围
function getExamUnits() {
  let raw = (KNOWLEDGE_BASE[examState.grade] && KNOWLEDGE_BASE[examState.grade][examState.semester]) || [];
  if (raw.length === 0) return { units: [], rangeText: '' };
  // v49：含课本单元的年级（六年级），期中/期末/月考只考课本单元（专项不进整册组卷，对齐真实期末范围）
  let hasTb = raw.some(u => u.group === '课本');
  let all = hasTb ? raw.filter(u => u.group === '课本') : raw;

  if (examState.type === 'unit') {
    // 单元考试索引基于原始数组（含专项），任选一个单元
    let u = raw[examState.unitIdx] || raw[0];
    let label = (u.group === '课本') ? `第${u.unit}单元 ${u.name}` : u.name;
    return { units: [u], all: all, rangeText: label };
  }
  if (examState.type === 'month') {
    let n = Math.min(all.length, examState.month * 2);
    return { units: all.slice(0, n), all: all, rangeText: `第1~${n}单元` };
  }
  if (examState.type === 'mid') {
    let n = Math.max(1, Math.ceil(all.length / 2));
    return { units: all.slice(0, n), all: all, rangeText: `第1~${n}单元（半册）` };
  }
  // final
  return { units: all, all: all, rangeText: `全册（共${all.length}个单元）` };
}

// 判断题目是否适合"填空/计算"（答案可直接输入）
function isTypableAnswer(ans) {
  if (ans === undefined || ans === null) return false;
  let s = String(ans).trim();
  if (s === '' || s.length > 12) return false;
  return true;
}

function isNumericAnswer(ans) {
  let s = String(ans).trim();
  return s !== '' && !isNaN(parseFloat(s)) && /^[-\d.\/:：%元角分个人天时分秒厘米米千克克]+$/.test(s);
}

// 是否为"文字叙述型"题目（应用题特征）
// 概念/辨析题判定：题面是概念问答而非计算/应用（如「25%=几分之几」「用什么统计图」「…表示什么」）
function isConceptOnly(q) {
  let t = (q.question || '');
  if (/^[\d.]+[+\-×÷][\d.]+=?？$/.test(t.replace(/\s/g,''))) return false; // 纯算式不算
  return /几分之几|是什么|叫什么|表示|适合|看到的是|看到的形状|几个面|几条棱|几个底面|可能性|等于多少度|公式是|用什么统计图|统计图|几个正方形|组成|打八折|是原价的|时间间隔/.test(t);
}
function isWordyQuestion(q) {  let t = q.question || '';
  return t.length >= 14 && /[，,。？?、；]/.test(t);
}

// 是否为纯算式（计算题特征）
function isPureExpression(q) {
  let t = (q.question || '').replace(/\s/g, '');
  return /^[\d+\-×÷=?？.()（）:：/％%]+$/.test(t) && /[+\-×÷]/.test(t);
}

// 应用题关键词（生活情境）
const APP_KEYWORDS = /(小明|小红|小华|小刚|小丽|同学|老师|妈妈|爸爸|一共|共有|共多少|平均|每人|每个|每小时|每天|剩下|还剩|买|卖|花了|付|应付|找回|行驶|速度|相距|相遇|追上|合作|完成|工作|人数|多少人|多少元|多少个|多少只|多少千克|多少米|多少本|多少块|几小时|几分钟|几个|几只|几元|几本|原价|打折|利息|存入)/;
// 明显不是应用题的开头（纯知识点考查）
const NOT_APP_PREFIX = /^(读数|写数|写作|读作|计算|求|比较|下面|下列|在括号|填上|把|用|判断|选择)/;

function isApplicationLike(q) {
  let t = q.question || '';
  if (NOT_APP_PREFIX.test(t)) return false;
  return APP_KEYWORDS.test(t);
}

// v69：估算一个单元「到底能出多少道互不相同的题」。
// 去重键 = 题面 + 答案 + 配图：同题面但配图不同的图形题（如「这是什么图形？」配不同图形）
// 属于不同的题，不能只按题面判重；反过来同题面同答案的就是实打实的重复题。
// 连续 stagnant 次采样都没新增就提前收手，避免小池子被反复空跑。
function estimateUnitCapacity(unit, budget) {
  budget = budget || 120;
  const seen = new Set();
  let stagnant = 0;
  for (let i = 0; i < budget; i++) {
    let raw;
    try { raw = unit.gen(); } catch (e) { continue; }
    const arr = Array.isArray(raw) ? raw : [raw];
    const before = seen.size;
    arr.forEach(q => {
      if (!q || q.question === undefined || q.question === null) return;
      seen.add(String(q.question) + '|' + String(q.answer) + '|' + String(q.svg || ''));
    });
    if (seen.size === before) { if (++stagnant >= (budget || 120)) break; } else stagnant = 0;
  }
  return seen.size;
}

// 生成候选题池：轮转各单元、全局去重，保证均衡
function buildQuestionPool(units, target, seen, isCore) {
  seen = seen || new Set();
  let pool = [];
  if (!units || units.length === 0) return pool;
  let maxRound = Math.ceil(target / units.length) + 6;
  let zeroRounds = 0;   // v73.2：连续多轮 0 新增才判枯竭，避免单轮运气差提前收手
  for (let r = 0; r < maxRound && pool.length < target; r++) {
    let addedThisRound = 0;
    for (let u of units) {
      if (pool.length >= target) break;
      // v50：尝试次数 8→24。单单元组卷（单元考试）时去重键有限，随机采样
      // 8 连撞已见键的概率不低，会触发 addedThisRound===0 提前枯竭，池子
      // 随机缩水（实测 20~59 波动）→ 单元卷间歇性缺题。24 次可基本榨干键空间。
      for (let tries = 0; tries < 24; tries++) {
        let raw;
        try { raw = u.gen(); } catch (e) { continue; }
        // v23 契约：gen() 可返回单题对象，或整组题目数组（如角度计算/专项类返回 20~34 题）。
        // 数组直接作为本轮候选，避免 q.question 为 undefined 导致整单元抽空、考试串题。
        let cands = Array.isArray(raw) ? raw : [raw];
        let q = cands[tries % cands.length];
        if (!q || !q.question || q.answer === undefined || q.answer === null) continue;
        let key = q.question + '|' + q.answer;
        if (seen.has(key)) continue;
        seen.add(key);
        q._unitType = u.type;
        q._unitName = u.name;
        q._core = (isCore !== false);
        pool.push(q);
        addedThisRound++;
        break;
      }
    }
    if (addedThisRound === 0) { if (++zeroRounds >= 5) break; } // 连续 5 轮零新增才判枯竭
    else zeroRounds = 0;
  }
  return pool;
}

// v73：视觉去重键。
// v49 定的「按题面文本严格去重」铁律，对「参数只体现在配图里」的题会误杀：
// 一年级「认识钟表」整单元只有 1 种题面「钟面上是几时？」，参数（几点）只画在 SVG 里，
// 按题面去重会把整单元滤到只剩 1 道，卷面只能靠克隆凑数，反而满屏雷同。
// 配图本身就是题面的一部分——图形不同就是不同的题，故带图题用「题面 + SVG」作键。
function visKey(q) {
  let t = String((q && q.question) || '');
  let svg = String((q && q.svg) || '');
  return svg.indexOf('<') >= 0 ? (t + '||' + svg) : t;
}

// 从题池中挑选 n 道题：分数越高越优先，同时避免同一单元扎堆
// v49 去重铁律：主池构建按「题面|答案」去重（保留参数化图形题的多样答案），
// 但选题时必须再按「题面文本」严格去重——同题面、参数只在 SVG 图里的题，
// 在卷面上就是视觉重复题（跨单元模板题同理）。严格模式凑不满时（单元卷题面
// 种类有限），放宽允许少量重复，保证整卷题量完整。
function pickFromPool(pool, used, n, scorer, usedText) {
  let out = [];
  let unitCount = {};
  let tplCount = {};
  const tplOf = q => (q.question || '')
    .replace(/\d+(\.\d+)?/g, '#')
    .replace(/(.)\1+/gu, '$1')   // 折叠重复符号，如「●●●●」与「●●」视为同一题型
    .slice(0, 20);
  const run = (allowRepeat) => {
    while (out.length < n) {
      let best = -1, bestScore = -1;
      for (let i = 0; i < pool.length; i++) {
        if (used.has(i)) continue;
        // 视觉上已出现过的题：严格轮直接跳过（v73：带图题按「题面+图形」判重）
        if (!allowRepeat && usedText && usedText.has(visKey(pool[i]))) continue;
        let base = scorer(pool[i]);
        if (base <= 0) continue;
        if (pool[i]._core === false) base *= 0.35;   // 补充题让位于本次考查范围
        let c = unitCount[pool[i]._unitName] || 0;
        let tc = tplCount[tplOf(pool[i])] || 0;
        let s = base / (1 + 0.7 * c) / (1 + 1.1 * tc) + Math.random() * 0.8;
        if (s > bestScore) { bestScore = s; best = i; }
      }
      if (best < 0) return;
      used.add(best);
      if (usedText) usedText.add(visKey(pool[best]));
      let name = pool[best]._unitName;
      unitCount[name] = (unitCount[name] || 0) + 1;
      let tpl = tplOf(pool[best]);
      tplCount[tpl] = (tplCount[tpl] || 0) + 1;
      out.push(pool[best]);
    }
  };
  run(false);                    // 第一轮：题面文本严格去重
  if (out.length < n) run(true); // 第二轮：题面种类不足时放宽，凑满整卷
  return out;
}

// 各分区的选题打分器
function getSectionScorer(key) {
  if (key === 'app') {
    // 应用题：优先带生活情境的文字题；概念/辨析题一律不进应用区
    return q => {
      let wordy = isWordyQuestion(q);
      let appLike = isApplicationLike(q);
      if (isConceptOnly(q)) return 0.05;              // 概念题不占 6 分应用位
      if (appLike && wordy && q._unitType === 'application') return 14;
      if (appLike && wordy) return 11;
      if (appLike) return 8;
      if (q._unitType === 'application' && wordy) return 5;
      if (wordy) return 2;
      return 0.3;
    };
  }
  if (key === 'calc') {
    // 计算题：优先纯算式，答案必须是数；概念/互化/辨析题降权
    return q => {
      if (!isNumericAnswer(q.answer)) return 0.2;
      if (isConceptOnly(q)) return 0.4;               // 「25%=几分之几」等概念互化题不进计算区
      if (isPureExpression(q)) return 12;
      if (/[+\-×÷=]/.test(q.question) && !isWordyQuestion(q)) return 8;
      if (q._unitType === 'basic' && !isWordyQuestion(q)) return 5;
      return 0.8;
    };
  }
  if (key === 'judge') {
    // 判断题：分区的题由 deriveJudgeQuestions 在组卷时派生后注入题池，
    // 这里只负责把它们捞出来（原生题一律不让进，避免判断题区混入普通选择题）。
    return q => (q.judge ? 12 : 0);
  }
  if (key === 'choice') {
    // 选择题：必须原生带选项，优先概念辨析类
    return q => {
      let hasOpts = q.options && q.options.length >= 2;
      if (!hasOpts) return 0.1;
      if (q.judge) return 0.05;                     // 派生判断题不占选择位
      if (isPureExpression(q)) return 3;          // 纯算式留给计算题区
      if (q.type === 'shape_choice') return 11;
      if (q._unitType === 'shape') return 10;
      if (isApplicationLike(q)) return 6;         // 应用题留给应用题区
      if (q.type === 'choice') return 9;
      return 0.5;
    };
  }
  // 填空题：简短、答案可直接书写、偏概念与口算
  return q => {
    if (q.judge) return 0.05;                               // 派生判断题不占填空位（答案是「正确/错误」）
    if (!isTypableAnswer(q.answer)) return 0.15;
    let wordy = isWordyQuestion(q);
    let hasOpts = q.options && q.options.length >= 2;
    if (isPureExpression(q)) return 2.5;                        // 竖式计算留给计算题区
    if (isApplicationLike(q) && wordy) return 1.2;              // 情境题留给应用题区
    if (hasOpts) return 0.6;                                    // v83r: 带≥2选项的选择题（含合数题这种答案可书写的）不进填空区，让选择题区收
    if (q.type === 'fill' && !wordy) return 12;
    if (q.type === 'fill') return 7;
    if (!wordy && isNumericAnswer(q.answer)) return 8;
    if (!wordy) return 4;
    return 1.5;
  };
}

// 生成整份试卷
// 自动生成解题步骤（计算题/应用题）
function generateSteps(q, unit) {
  let t = (q.question || '').replace(/\s/g,'');
  let ans = q.answer !== undefined ? String(q.answer) : '';
  let m;

  // ── 分数乘法 a/b × c ──
  m = t.match(/^(\d+)\/(\d+)×(\d+)=？$/);
  if (m) {
    let a=+m[1], b=+m[2], c=+m[3];
    let steps=[`分数乘整数：分子与整数相乘，分母不变`,
      `${a}/${b} × ${c} = (${a}×${c})/${b} = ${a*c}/${b}`];
    if (gcd(a*c, b) > 1) steps.push(`约分：${a*c}/${b} = ${fracStr(a*c, b)}`);
    steps.push(`所以 ${a}/${b} × ${c} = ${fracStr(a*c, b)}`);
    return steps;
  }
  // ── 同分母分数加法 ──
  m = t.match(/^(\d+)\/(\d+)\+(\d+)\/(\d+)=？$/);
  if (m) {
    let n1=+m[1], d1=+m[2], n2=+m[3], d2=+m[4];
    if (d1 === d2) {
      let steps=[`同分母分数相加：分母不变，分子相加`,
        `${n1}/${d1} + ${n2}/${d2} = ${n1+n2}/${d1}`];
      if (gcd(n1+n2, d1) > 1) steps.push(`约分：${n1+n2}/${d1} = ${fracStr(n1+n2, d1)}`);
      steps.push(`所以结果是 ${fracStr(n1+n2, d1)}`);
      return steps;
    }
    return [`异分母分数相加：先通分，再按同分母分数相加`, `答案：${ans}`];
  }
  // ── 除以分数 n ÷ (1/k) ──
  m = t.match(/^(\d+)÷\(1\/(\d+)\)=？$/);
  if (m) {
    let n=+m[1], k=+m[2];
    return [`除以一个分数等于乘它的倒数，1/${k} 的倒数是 ${k}`,
      `${n} ÷ (1/${k}) = ${n} × ${k} = ${n*k}`];
  }
  // ── 解方程 ax+b=c ──
  m = t.match(/^解方程：(\d+)x\+(\d+)=(\d+),x=？$/);
  if (m) {
    let a=+m[1], b=+m[2], c=+m[3];
    return [`等式两边同时减去 ${b}`,
      `${a}x = ${c} - ${b} = ${c-b}`,
      `两边同时除以 ${a}：x = ${c-b} ÷ ${a} = ${(c-b)/a}`];
  }
  // ── 解比例 a:b = x:c ──
  m = t.match(/^(\d+):(\d+)=x:(\d+)，x=？$/);
  if (m) {
    let a=+m[1], b=+m[2], c=+m[3];
    return [`比例的基本性质：两内项之积 = 两外项之积`,
      `${a} × ${c} = ${b} × x`,
      `x = ${a}×${c} ÷ ${b} = ${a*c} ÷ ${b} = ${a*c/b}`];
  }
  // ── 百分数 ↔ 分数互化 ──
  m = t.match(/^(\d+)%=几分之几（约分）？$/);
  if (m) {
    let p=+m[1];
    return [`把百分数写成分数：${p}% = ${p}/100`,
      `约分：${p}/100 = ${fracStr(p, 100)}`];
  }
  // ── 圆周长 / 面积 ──
  m = t.match(/r=(\d+)/);
  if (m && /周长/.test(t)) {
    let r=+m[1];
    return [`圆的周长公式：C = 2πr`,
      `C = 2 × 3.14 × ${r} = ${fmt(+(2*3.14*r).toFixed(2))}`];
  }
  if (m && /面积/.test(t)) {
    let r=+m[1];
    return [`圆的面积公式：S = πr²`,
      `S = 3.14 × ${r} × ${r} = ${fmt(+(3.14*r*r).toFixed(2))}`];
  }
  // ── 三角形面积 ──
  m = t.match(/三角形的?底是(\d+)cm、高是(\d+)cm/);
  if (m) {
    let b=+m[1], h=+m[2];
    return [`三角形面积公式：S = 底 × 高 ÷ 2`,
      `S = ${b} × ${h} ÷ 2 = ${b*h} ÷ 2 = ${b*h/2}（平方厘米）`];
  }
  // ── 平行四边形面积 ──
  m = t.match(/平行四边形的?底是(\d+)cm、高是(\d+)cm/);
  if (m) {
    let b=+m[1], h=+m[2];
    return [`平行四边形面积公式：S = 底 × 高`,
      `S = ${b} × ${h} = ${b*h}（平方厘米）`];
  }
  // ── 梯形面积 ──
  m = t.match(/梯形的?上底是(\d+)cm、下底是(\d+)cm、高是(\d+)cm/);
  if (m) {
    let a=+m[1], b=+m[2], h=+m[3];
    return [`梯形面积公式：S = (上底 + 下底) × 高 ÷ 2`,
      `S = (${a} + ${b}) × ${h} ÷ 2 = ${a+b} × ${h} ÷ 2 = ${(a+b)*h/2}（平方厘米）`];
  }
  // ── 已知部分求总数 ──
  m = t.match(/^总数的1\/(\d+)是(\d+)，总数是多少？$/);
  if (m) {
    let k=+m[1], n=+m[2];
    return [`把总数看作单位"1"，总数的 1/${k} 是 ${n}`,
      `总数 = ${n} ÷ 1/${k} = ${n} × ${k} = ${n*k}`];
  }
  // ── 植树问题（兼容"种一棵（两端都种）"与"种一棵树"两种题干）──
  m = t.match(/^一条路长(\d+)米，每隔(\d+)米种一棵(?:（两端都种）|树)?，共几棵？$/);
  if (m) {
    let L=+m[1], g=+m[2];
    return [`先求间隔数：${L} ÷ ${g} = ${L/g}（个间隔）`,
      `两端都种：棵数 = 间隔数 + 1 = ${L/g} + 1 = ${L/g+1}（棵）`];
  }
  // ── 负数加减（仅含负号的算式走此分支，纯正数走下方竖式分支）──
  m = t.match(/^(-?\d+)([+-])(-?\d+)=？$/);
  if (m && (m[1].indexOf('-')===0 || m[3].indexOf('-')===0)) {
    let a=+m[1], op=m[2], b=+m[3];
    if (op === '+') {
      if ((a<0&&b>0)||(a>0&&b<0)) return [`异号两数相加：取绝对值较大加数的符号，用较大的绝对值减去较小的绝对值`,
        `${a} + ${b} = ${Math.abs(a)>Math.abs(b)?Math.abs(a):Math.abs(b)} - ${Math.abs(a)>Math.abs(b)?Math.abs(b):Math.abs(a)} = ${a+b}`];
      if (a<0&&b<0) return [`同号两数相加：取相同的符号（负号），并把绝对值相加`,
        `${a} + ${b} = -(${Math.abs(a)} + ${Math.abs(b)}) = ${a+b}`];
      return [`同号两数相加：符号为正，把绝对值相加`, `${a} + ${b} = ${a+b}`];
    }
    return [`减去一个数，等于加上这个数的相反数`,
      `${a} - ${b} = ${a} + (${-b}) = ${a-b}`];
  }
  // ── 平均数 ──
  m = t.match(/^数据((?:\d+、)+\d+)的平均数是？$/);
  if (m) {
    let ds=m[1].split('、').map(Number);
    let sum=ds.reduce((x,y)=>x+y,0);
    return [`平均数 = 总数量 ÷ 总个数`,
      `总和 = ${ds.join(' + ')} = ${sum}，个数 = ${ds.length}`,
      `平均数 = ${sum} ÷ ${ds.length} = ${fmt(+(sum/ds.length).toFixed(2))}`];
  }
  // ── 鸡兔同笼 ──
  m = t.match(/^鸡兔同笼，共(\d+)个头(\d+)只脚，兔有几只？$/);
  if (m) {
    let h=+m[1], f=+m[2];
    return [`假设笼子里全是鸡，则脚应有 ${2*h} 只`,
      `比实际少 ${f-2*h} 只脚，每把一只鸡换成兔多 2 只脚`,
      `兔 = (${f} - ${2*h}) ÷ 2 = ${f-2*h} ÷ 2 = ${(f-2*h)/2}（只）`];
  }
  // ── 纯算式（竖式/脱式）──
  m = t.match(/^([\d.]+)([+\-×÷])([\d.]+)=？$/);
  if (m) {
    let a=+m[1], op=m[2], b=+m[3];
    let r = op==='+' ? a+b : op==='-' ? a-b : op==='×' ? a*b : +(a/b).toFixed(2);
    // v81：整数乘法补竖式分解。4 年级「三位数乘两位数」专项 90 道题、3 年级两个乘法单元
    // 原先只有一行「235 × 27 = 6345」，孩子看不到怎么算出来的，这里逐位拆开。
    if (op === '×' && Number.isInteger(a) && Number.isInteger(b)) {
      let vs = verticalMulSteps(a, b);
      if (vs) return vs;
    }
    let steps=[`${a} ${op} ${b} = ${fmt(r)}`];
    if (op==='×' && (String(a).includes('.') || String(b).includes('.'))) {
      const da=(String(a).split('.')[1]||'').length, db=(String(b).split('.')[1]||'').length;
      steps.unshift(`小数乘法：先按整数乘法计算，再看两个因数共有 ${da+db} 位小数，从积的右边起数出 ${da+db} 位点上小数点`);
    }
    if (op==='+' || op==='-') {
      // v81：整数加减法不该说「小数点对齐」
      const dec = String(a).includes('.') || String(b).includes('.');
      steps.unshift(dec ? `小数点对齐（也就是相同数位对齐），从低位算起`
                        : `相同数位对齐，从个位算起`);
    }
    if (op==='÷') steps.unshift(`除数是整数：按整数除法计算，商的小数点与被除数对齐`);
    return steps;
  }

  // ── 行程·求路程 ──
  m = t.match(/^汽车每小时行(\d+)千米，(\d+)小时行多少千米？$/);
  if (m) {
    let v=+m[1], hh=+m[2];
    return [`路程 = 速度 × 时间`,
      `${v} × ${hh} = ${v*hh}（千米）`];
  }
  // ── 行程·相遇 ──
  m = t.match(/^甲、乙两车从相距(\d+)千米的两地同时相向开出，甲车每小时行(\d+)千米，乙车每小时行(\d+)千米，几小时后两车相遇？$/);
  if (m) {
    let s=+m[1], v=+m[2], w=+m[3];
    return [`相遇时间 = 总路程 ÷ 速度和`,
      `速度和 = ${v} + ${w} = ${v+w}（千米/时）`,
      `${s} ÷ ${v+w} = ${s/(v+w)}（小时）`];
  }
  // ── 行程·求时间 ──
  m = t.match(/^一辆汽车每小时行(\d+)千米，要行驶(\d+)千米，需要多少小时？$/);
  if (m) {
    let v=+m[1], s=+m[2];
    return [`时间 = 路程 ÷ 速度`,
      `${s} ÷ ${v} = ${s/v}（小时）`];
  }
  // ── 工程·合做效率（通分再相加，须先于独做分支匹配）──
  m = t.match(/^一项工程(.)队独做(\d+)天完成，(.)队独做(\d+)天完成，两队合做每天完成工程的几分之几？$/);
  if (m) {
    let a=+m[2], b=+m[4];
    return [`把这项工程看作单位"1"：${m[1]}每天完成 1/${a}，${m[3]}每天完成 1/${b}`,
      `通分：1/${a} + 1/${b} = ${b}/${a*b} + ${a}/${a*b}`,
      `两队合做每天完成 ${a+b}/${a*b}`];
  }
  // ── 工程·独做效率（甲队/乙队/甲单独做，兼容"独做/单独做"两种表述）──
  m = t.match(/^一项工程.{0,6}?(\d+)天完成，.{0,4}?每天完成(工程的)?几分之几？$/);
  if (m) {
    let d=+m[1];
    return [`把这项工程看作单位"1"`,
      `每天完成 = 1 ÷ ${d} = 1/${d}`];
  }
  // ── 数与形：连续奇数求和（1+3+5+…+(2n-1)=n²）──
  m = t.match(/^1\+3\+5\+…\+(\d+)=？$/);
  if (m) {
    let last=+m[1], n=(last+1)/2;
    return [`从1开始的连续奇数相加，和 = 加数个数的平方`,
      `末项 = ${last} = 2n−1，所以共有 n = ${n} 个加数`,
      `和 = ${n}² = ${n*n}`];
  }
  // ── 数与形：第n层比第n-1层多几个（n²−(n−1)²=2n−1）──
  m = t.match(/^(\d+)²−(\d+)²=？$/);
  if (m) {
    let n=+m[1];
    return [`大正方形数 − 小正方形数 = 最外层拐角形的小正方形数`,
      `${n}² − ${n-1}² = ${n*n} − ${(n-1)*(n-1)} = ${2*n-1}`,
      `规律：第${n}层（L形）比第${n-1}层多 2×${n}−1 = ${2*n-1} 个`];
  }
  // ── 鸽巢问题：至少数 = 商 + 1 ──
  m = t.match(/^(\d+)支铅笔放进(\d+)个笔筒里，总有一个笔筒里至少放进几支铅笔？$/);
  if (m) {
    let n=+m[1], d=+m[2], q2=Math.floor(n/d);
    return [`把铅笔看作物体，笔筒看作抽屉`,
      `${n} ÷ ${d} = ${q2}……${n-q2*d}`,
      `至少数 = 商 + 1 = ${q2} + 1 = ${q2+1}（支）`];
  }
  m = t.match(/^(\d+)本书分给(\d+)个同学，总有一个同学至少分到几本书？$/);
  if (m) {
    let n=+m[1], d=+m[2], q2=Math.floor(n/d);
    return [`把书看作物体，同学看作抽屉`,
      `${n} ÷ ${d} = ${q2}……${n-q2*d}`,
      `至少数 = 商 + 1 = ${q2} + 1 = ${q2+1}（本）`];
  }

  // ── 应用题通用：数量关系 + 列式 ──
  if (q.sectionTitle && q.sectionTitle.includes('应用')) {
    let nums = (t.match(/(\d+\.?\d*)/g) || []).map(Number).filter(n => !isNaN(n));
    let steps = [];
    let an = parseFloat(ans);
    if (nums.length >= 2) {
      let [a,b] = nums.slice(0,2);
      if (a*b === an) { steps.push(`根据题意列式：${a} × ${b} = ${a*b}`); steps.push(`答：${ans}`); return steps; }
      if (b && +(a/b).toFixed(2) === an) { steps.push(`根据题意列式：${a} ÷ ${b} = ${fmt(+(a/b).toFixed(2))}`); steps.push(`答：${ans}`); return steps; }
      // v81：原逻辑到这里只会说「根据题意分析数量关系」这种空话，改由通用讲解引擎接手
      let smart2 = buildSmartSteps(q, unit);
      if (smart2 && smart2.length) { q.stepsGeneric = true; return smart2; }
      steps.push(`根据题意分析数量关系，列式计算`);
      steps.push(`答：${ans}`);
      return steps;
    }
    // v81：不再只说套话，先让通用讲解引擎试一次
    let smartApp = buildSmartSteps(q, unit);
    if (smartApp && smartApp.length) { q.stepsGeneric = true; return smartApp; }
    steps.push(`根据题意分析数量关系，得出结果`);
    steps.push(`答：${ans}`);
    return steps;
  }

  // ── 填空 / 选择 / 兜底 ──
  // v81：旧兜底只吐一行「答案：x」，实测 89% 的题因此拿不到任何讲解，改走通用讲解引擎
  let smart = buildSmartSteps(q, unit);
  if (smart && smart.length) { q.stepsGeneric = true; return smart; }
  return [`答案：${ans}`];
}

// ============================================================
// v81：通用分步讲解引擎（S3 · 解析讲解回填）
// ============================================================
// 背景（实测 630 道去重题）：题库里没有一道题自带 explain 或 steps，
// 所有解析都由 generateSteps 现场生成；而旧兜底只吐一行「答案：x」，
// 导致 89% 的题在错题本和答案解析页里看不到任何讲解。
// 这里补三层，任何一层命中都保证返回 ≥2 步：
//   L1 句式语义规则 —— 六年级高频句式（比例尺/折扣/成数/比/倒数/圆/圆柱圆锥/
//       统计/鸽巢/方向/数与形/公因数公倍数/互化…）
//   L2 分数关系 + 关键词驱动列式 —— 只在「结果与答案精确一致」或「题干有明确
//       运算信号」时才列式，绝不瞎凑算式
//   L3 单元知识卡 —— 用单元自带的 summary / fidx / method 生成
//       「考点 → 公式 → 思路 → 答案」，保证任何题都有学科内容
// 三层全落空时也有「读题 → 方法 → 答案」三段，并附选项对照。

// 整数乘法竖式分解：把位数少的因数拆位，逐位去乘再相加。
// 一位数乘多位数时改拆另一个因数的数位（更符合口算习惯）。
function verticalMulSteps(a, b) {
  if (!Number.isInteger(a) || !Number.isInteger(b) || a <= 0 || b <= 0) return null;
  const top = Math.max(a, b), bot = Math.min(a, b);
  const topStr = String(top), botStr = String(bot);
  // 表内乘法：直接出口诀
  if (topStr.length === 1 && botStr.length === 1) {
    return ['用乘法口诀计算', `${a} × ${b} = ${a * b}`];
  }
  const steps = [];
  if (botStr.length === 1) {
    // 多位数 × 一位数：按数位拆开分别相乘（242 = 200 + 40 + 2，注意是「数字×位值」）
    const ds = topStr.split('').map(Number);
    const place = ds.map((d, i) => Math.pow(10, ds.length - 1 - i));
    const seg = ds.map((d, i) => d * place[i]);
    steps.push(`用 ${bot} 去乘 ${top} 的每一位：${top} = ${seg.join(' + ')}`);
    const parts = [];
    ds.forEach((d, i) => {
      const v = seg[i] * bot;
      parts.push(v);
      steps.push(`${seg[i]} × ${bot} = ${v}`);
    });
    steps.push(`再把各部分相加：${parts.join(' + ')} = ${a * b}`);
    return steps;
  }
  // 多位数 × 多位数：标准竖式，用下面因数的每一位从个位起依次去乘
  const unitName = ['个', '十', '百', '千', '万'];
  steps.push(`用竖式计算 ${a} × ${b}：把 ${top} 写在上面，用 ${bot} 的每一位从个位起依次去乘`);
  const partials = [];
  botStr.split('').reverse().forEach((ch, i) => {
    const d = Number(ch);
    if (d === 0) return;
    const base = top * d, val = base * Math.pow(10, i);
    partials.push(val);
    if (i === 0) steps.push(`先用个位上的 ${d} 去乘：${top} × ${d} = ${base}`);
    else steps.push(`再用${unitName[i] || i}位上的 ${d} 去乘：${top} × ${d} = ${base}，表示 ${base} 个${unitName[i] || ''}，也就是 ${val}`);
  });
  if (!partials.length) return null;
  if (partials.length === 1) steps.push(`所以 ${a} × ${b} = ${partials[0]}`);
  else steps.push(`把两次乘得的数相加：${partials.join(' + ')} = ${a * b}`);
  return steps;
}

// 按题目上的 _unitName 反查单元对象，给 L3 提供 summary / fidx / method。
// 组卷时题目来自多个单元，只能逐题反查；广西真题没有单元归属，返回 null。
function unitMetaFor(q) {
  if (!q || !q._unitName || q._unitName === '广西真题') return null;
  try {
    const hit = findUnitByName(state.currentGrade, q._unitName);
    return hit ? hit.unit : null;
  } catch (e) { return null; }
}

// 提取题干中的数字（先剥掉 1:600,000 这类千分位逗号，避免被当成两个数）
function stepNums(t) {
  return (String(t).replace(/(\d),(\d{3})/g, '$1$2').match(/\d+(?:\.\d+)?/g) || []).map(Number);
}

// 从一组素材里挑与本题最相关的一条：按题干汉字命中数打分，命中答案额外加权。
// 固定取第一条会出现「题问乘真分数积怎么变，却讲分数乘整数法则」这种跑题的讲解。
function pickRelevant(list, t, ans) {
  if (!list || !list.length) return null;
  const sAns = String(ans === undefined ? '' : ans);
  let best = list[0], bestScore = -1;
  list.forEach(function (s) {
    const str = String(s);
    let sc = 0;
    for (let i = 0; i < t.length; i++) {
      const ch = t.charAt(i);
      if (ch >= '\u4e00' && ch <= '\u9fa5' && str.indexOf(ch) >= 0) sc++;
    }
    if (sAns && sAns.length <= 6 && str.indexOf(sAns) >= 0) sc += 5;
    if (sc > bestScore) { bestScore = sc; best = s; }
  });
  return best;
}

// L3：单元知识卡（每个单元都有 summary / fidx / method 三套教学素材）
function stepsFromUnitCard(unit, ans, t) {
  if (!unit) return null;
  const steps = [];
  const tip = pickRelevant(unit.summary, t || '', ans);
  if (tip) steps.push('考点：' + tip);
  if (unit.fidx && unit.fidx.length) {
    const f = unit.fidx[0];
    steps.push('公式：' + f.t + ' —— ' + f.f);
  }
  const way = pickRelevant((unit.method || []).map(function (m) { return m && m.s; }), t || '', ans);
  if (way) steps.push('思路：' + way);
  steps.push('正确答案：' + ans);
  return steps.length >= 2 ? steps : null;
}

// 选择题专属最后一步：把四个选项摊开对照
function stepOptionsLine(q) {
  if (!q.options || !q.options.length) return null;
  const txt = q.options.map(function (o, i) {
    return String.fromCharCode(65 + i) + '. ' + (typeof o === 'object' ? o.value : o);
  }).join('；');
  return '选项对照：' + txt;
}

function buildSmartSteps(q, unit) {
  const t = String(q.question || '').replace(/\s/g, '');
  const ans = q.answer !== undefined ? String(q.answer) : '';
  // 答案数值：支持 '3:4' 之外的纯数与 '5/6' 这类分数答案
  let an = NaN;
  const fm = ans.match(/^(-?\d+(?:\.\d+)?)\/(-?\d+(?:\.\d+)?)$/);
  if (fm) an = parseFloat(fm[1]) / parseFloat(fm[2]);
  else if (/^-?\d+(?:\.\d+)?$/.test(ans)) an = parseFloat(ans);
  const ansIsPlainNum = /^-?\d+(?:\.\d+)?$/.test(ans);
  const near = function (x) { return !isNaN(an) && isFinite(x) && Math.abs(x - an) < 1e-6; };
  let m;

  /* ---------- L1 · 句式语义规则 ---------- */

  // 倒数：a/b → b/a
  m = t.match(/^(\d+)\/(\d+)的倒数是？$/);
  if (m) {
    // v84t：分子为 1 时倒数是整数，不写 n/1（与题库答案口径一致）
    const rec = (+m[1] === 1) ? `${m[2]}` : `${m[2]}/${m[1]}`;
    return ['求一个分数的倒数，就是把分子和分母调换位置',
      `${m[1]}/${m[2]} 的倒数是 ${rec}`];
  }
  m = t.match(/^(\d+)的倒数是？$/);
  if (m) {
    const n = +m[1];
    if (n === 1) return ['1 的倒数是它本身', '1 的倒数是 1'];
    return ['整数 n（n≠0）的倒数是 1/n', `${n} 的倒数是 1/${n}`];
  }

  // 比例尺：图上距离 → 实际距离（厘米化千米）
  m = t.match(/比例尺1:([\d,]+)/);
  if (m && /(实际距离|两地实际)/.test(t)) {
    const sc = +String(m[1]).replace(/,/g, '');
    const cm = (t.match(/距离是?(\d+(?:\.\d+)?)厘米/) || t.match(/(\d+(?:\.\d+)?)厘米/) || [])[1];
    if (cm) {
      const c = +cm, total = c * sc, km = total / 100000;
      return ['比例尺 = 图上距离 : 实际距离，所以实际距离 = 图上距离 × 比例尺的后项',
        `实际距离 = ${c} × ${sc} = ${total}（厘米）`,
        `${total} 厘米 = ${total / 100} 米 = ${fmt(+km.toFixed(4))} 千米`];
    }
  }

  // 折扣：已知原价求现价
  m = t.match(/原价(\d+(?:\.\d+)?)元，打(\d+(?:\.\d+)?)折/);
  if (m) {
    const p = +m[1], d = +m[2], rate = d / 10;
    return [`打 ${d} 折就是按原价的十分之几出售：${d} 折 = ${d}/10 = ${fmt(+rate.toFixed(4))}`,
      `现价 = 原价 × 折扣 = ${p} × ${fmt(+rate.toFixed(4))} = ${fmt(+(p * rate).toFixed(4))}（元）`];
  }
  // 折扣：已知现价求原价
  m = t.match(/打(\d+(?:\.\d+)?)折后现价是(\d+(?:\.\d+)?)元，原价/);
  if (m) {
    const d = +m[1], now = +m[2], rate = d / 10;
    return [`打 ${d} 折 = 原价的 ${fmt(+rate.toFixed(4))}，即「原价 × ${fmt(+rate.toFixed(4))} = 现价」`,
      `原价 = 现价 ÷ 折扣 = ${now} ÷ ${fmt(+rate.toFixed(4))} = ${fmt(+(now / rate).toFixed(4))}（元）`];
  }
  // 折扣的含义
  m = t.match(/打(\d+(?:\.\d+)?)折出售，现价是原价的百分之几/);
  if (m) {
    const d = +m[1];
    return [`几折就表示十分之几，也就是百分之几十`,
      `${d} 折 = ${d}/10 = ${Math.round(d * 10)}%`];
  }
  // 成数：增产 n 成
  m = t.match(/增产(\d+(?:\.\d+)?)成/);
  if (m) {
    const c = +m[1], p = c * 10;
    return [`一成就是十分之一，也就是 10%`,
      `增产 ${c} 成 = 增产 ${p}%，今年产量 = 1 + ${p}% = ${100 + p}%`];
  }

  // 百分数 → 分数
  m = t.match(/^(\d+(?:\.\d+)?)%等于几分之几/);
  if (m) {
    const p = +m[1];
    const steps = [`百分数化分数：先把百分数写成分母是 100 的分数，再约成最简分数`, `${p}% = ${p}/100`];
    const g = gcd(p * 100, 100) / 100;
    if (p % 1 === 0 && gcd(p, 100) > 1) steps.push(`约分：${p}/100 = ${fracStr(p, 100)}`);
    return steps;
  }
  // 分数 → 小数
  m = t.match(/^把(\d+)\/(\d+)化成小数是？$/);
  if (m) return ['分数化小数：用分子除以分母', `${m[1]} ÷ ${m[2]} = ${fmt(+(+m[1] / +m[2]).toFixed(4))}`];
  // 小数 → 百分数
  m = t.match(/^把(\d*\.\d+)化成百分数是？$/);
  if (m) {
    const v = +m[1];
    return ['小数化百分数：小数点向右移动两位，再添上百分号',
      `${v} = ${fmt(+(v * 100).toFixed(4))}%`];
  }

  // 比：比值
  m = t.match(/^(\d+):(\d+)的比值是？$/);
  if (m) {
    const a = +m[1], b = +m[2];
    return ['比值 = 前项 ÷ 后项，结果可以是整数或分数',
      `${a} : ${b} = ${a} ÷ ${b} = ${a}/${b}`,
      `约成最简：${fracStr(a, b)}`];
  }
  // 比：化简（6:8化简后 / 把10:15化简后 / 化简比 12:18 = ？）
  m = t.match(/(\d+):(\d+)化简后|化简比(\d+):(\d+)/);
  if (m) {
    const a = +(m[1] || m[3]), b = +(m[2] || m[4]), g = gcd(a, b);
    return ['化简比：前项和后项同时除以它们的最大公因数',
      `${a} 和 ${b} 的最大公因数是 ${g}`,
      `${a}:${b} = ${a / g}:${b / g}`];
  }
  // 比：小数比化最简整数比
  m = t.match(/^(\d*\.\d+):(\d*\.\d+)化成最简整数比是？$/);
  if (m) {
    const a = +m[1], b = +m[2];
    const k = Math.pow(10, Math.max((String(a).split('.')[1] || '').length, (String(b).split('.')[1] || '').length));
    const ia = Math.round(a * k), ib = Math.round(b * k), g = gcd(ia, ib);
    return ['先把小数比化成整数比：前项后项同时扩大相同的倍数',
      `${a}:${b} = ${ia}:${ib}`,
      `再同时除以最大公因数 ${g}：${ia / g}:${ib / g}`];
  }
  // 比：按比分配（已知和）
  m = t.match(/之和是(\d+(?:\.\d+)?)，甲:乙=(\d+):(\d+)，甲是/);
  if (m) {
    const s = +m[1], a = +m[2], b = +m[3], tot = a + b;
    return ['按比分配：先求总份数，再求每一份是多少',
      `总份数 = ${a} + ${b} = ${tot}，每份 = ${s} ÷ ${tot} = ${fmt(+(s / tot).toFixed(4))}`,
      `甲占 ${a} 份：${fmt(+(s / tot).toFixed(4))} × ${a} = ${fmt(+(s * a / tot).toFixed(4))}`];
  }
  // 比：已知一项求另一项
  m = t.match(/甲:乙=(\d+):(\d+)，乙是(\d+(?:\.\d+)?)，甲是/);
  if (m) {
    const a = +m[1], b = +m[2], y = +m[3];
    return ['先求出一份是多少，再算甲占几份',
      `每份 = ${y} ÷ ${b} = ${fmt(+(y / b).toFixed(4))}`,
      `甲 = ${fmt(+(y / b).toFixed(4))} × ${a} = ${fmt(+(y * a / b).toFixed(4))}`];
  }
  // 比：前项加某数、比值不变
  m = t.match(/^(\d+):(\d+)的前项加上(\d+)，要使比值不变，后项应加上/);
  if (m) {
    const a = +m[1], b = +m[2], add = +m[3], na = a + add, k = na / a;
    return ['比的前项和后项同时乘或除以相同的数（0 除外），比值不变',
      `前项变成 ${a} + ${add} = ${na}，相当于扩大到原来的 ${fmt(+k.toFixed(4))} 倍`,
      `后项也要扩大同样的倍数：${b} × ${fmt(+k.toFixed(4))} = ${fmt(+(b * k).toFixed(4))}`,
      `所以后项应加上 ${fmt(+(b * k).toFixed(4))} - ${b} = ${fmt(+(b * k - b).toFixed(4))}`];
  }

  // 解比例：x 可能在四个位置中的任意一个（9:x=3:4 / 2:3=4:x …）
  m = t.match(/^(\d+(?:\.\d+)?):(x|\d+(?:\.\d+)?)=(\d+(?:\.\d+)?):(x|\d+(?:\.\d+)?)，?则?x=[?？]$/);
  if (m) {
    const p = [m[1], m[2], m[3], m[4]];
    const xi = p.indexOf('x');
    const vals = p.map(function (v) { return v === 'x' ? null : parseFloat(v); });
    if (xi >= 0) {
      if (xi === 0 || xi === 3) {
        const other = vals[xi === 0 ? 3 : 0], prod = vals[1] * vals[2];
        return ['比例的基本性质：两个外项的积 = 两个内项的积',
          `${xi === 0 ? 'x' : other} 和 ${xi === 0 ? other : 'x'} 是外项，${vals[1]} 和 ${vals[2]} 是内项`,
          `${xi === 0 ? `x × ${other}` : `${other} × x`} = ${vals[1]} × ${vals[2]} = ${prod}`,
          `x = ${prod} ÷ ${other} = ${fmt(+(prod / other).toFixed(4))}`];
      }
      const other = vals[xi === 1 ? 2 : 1], prod = vals[0] * vals[3];
      return ['比例的基本性质：两个外项的积 = 两个内项的积',
        `${vals[0]} 和 ${vals[3]} 是外项，${xi === 1 ? 'x' : other} 和 ${xi === 1 ? other : 'x'} 是内项`,
        `${vals[0]} × ${vals[3]} = ${xi === 1 ? `x × ${other}` : `${other} × x`} = ${prod}`,
        `x = ${prod} ÷ ${other} = ${fmt(+(prod / other).toFixed(4))}`];
    }
  }
  // 图形按 n:1 放大
  m = t.match(/按(\d+(?:\.\d+)?):1放大后，\S{0,8}长是多少/);
  if (m) {
    const k = +m[1], len = (t.match(/长(\d+(?:\.\d+)?)厘米/) || [])[1];
    if (len) return [`图形按 ${k}:1 放大，每条边都扩大到原来的 ${k} 倍`,
      `长 = ${len} × ${k} = ${fmt(+(len * k).toFixed(4))}（厘米）`];
  }
  m = t.match(/按(\d+(?:\.\d+)?):1放大后，\S{0,12}面积是原图形的几倍/);
  if (m) {
    const k = +m[1];
    return [`图形按 ${k}:1 放大，每条边都扩大到原来的 ${k} 倍`,
      `面积扩大的倍数 = 边长扩大倍数的平方：${k}² = ${fmt(+(k * k).toFixed(4))}`,
      `所以面积是原来的 ${fmt(+(k * k).toFixed(4))} 倍`];
  }
  // 温度升降（跨零点的减法）
  m = t.match(/从(-?\d+)℃下降到(-?\d+)℃/);
  if (m) {
    const c1 = +m[1], c2 = +m[2];
    return ['下降的温度 = 原来的温度 − 下降后的温度',
      `${c1} − (${c2}) = ${c1} + ${-c2} = ${fmt(+(c1 - c2).toFixed(4))}（℃）`];
  }
  m = t.match(/从(-?\d+)℃上升到(-?\d+)℃/);
  if (m) {
    const c1 = +m[1], c2 = +m[2];
    return ['上升的温度 = 上升后的温度 − 原来的温度',
      `${c2} − (${c1}) = ${c2} + ${-c1} = ${fmt(+(c2 - c1).toFixed(4))}（℃）`];
  }

  // 圆：直径 / 半径扩倍
  m = t.match(/半径是(\d+(?:\.\d+)?)\S{0,3}，?它的直径/);
  if (m) {
    const r = +m[1];
    return ['同一个圆里，直径是半径的 2 倍：d = 2r',
      `d = 2 × ${r} = ${fmt(+(2 * r).toFixed(4))}（${(t.match(/半径是\d+(?:\.\d+)?(\S{0,3})/) || [])[1] || ''}）`];
  }
  m = t.match(/半径扩大(\d+(?:\.\d+)?)倍，面积扩大/);
  if (m) {
    const k = +m[1];
    return ['圆的面积 S = πr²，面积与半径的平方成正比',
      `半径扩大 ${k} 倍，面积就扩大 ${k}² = ${fmt(+(k * k).toFixed(4))} 倍`];
  }
  m = t.match(/半径扩大(\d+(?:\.\d+)?)倍，周长扩大/);
  if (m) {
    const k = +m[1];
    return ['圆的周长 C = 2πr，周长与半径成正比',
      `半径扩大 ${k} 倍，周长也扩大 ${k} 倍`];
  }
  // 已知直径求半径 / 半径扩倍时直径同步扩倍
  m = t.match(/直径是(\d+(?:\.\d+)?)\S{0,3}，?它的半径/);
  if (m) {
    const d = +m[1];
    return ['同一个圆里，半径是直径的一半：r = d ÷ 2',
      `r = ${d} ÷ 2 = ${fmt(+(d / 2).toFixed(4))}`];
  }
  m = t.match(/半径扩大(\d+(?:\.\d+)?)倍，直径扩大/);
  if (m) {
    const k = +m[1];
    return ['直径 d = 2r，直径和半径成正比',
      `半径扩大 ${k} 倍，直径也扩大 ${k} 倍`];
  }
  // 已知半径求周长
  m = t.match(/半径是(\d+(?:\.\d+)?)\S{0,3}，?它的周长/);
  if (m) {
    const r = +m[1];
    return ['圆的周长公式：C = 2πr',
      `C = 2 × 3.14 × ${r} = ${fmt(+(2 * 3.14 * r).toFixed(4))}`];
  }

  // 圆柱 / 圆锥（π 取 3.14）
  m = t.match(/一个(圆柱|圆锥).{0,12}底面半径(\d+(?:\.\d+)?)厘米、高(\d+(?:\.\d+)?)厘米，它的(侧面积|表面积|体积)/);
  if (m) {
    const shape = m[1], r = +m[2], h = +m[3], kind = m[4];
    if (shape === '圆锥') {
      if (kind === '体积') return ['圆锥的体积等于与它等底等高的圆柱体积的三分之一：V = 1/3 πr²h',
        `V = 1/3 × 3.14 × ${r}² × ${h} = 1/3 × 3.14 × ${fmt(+(r * r).toFixed(4))} × ${h}`,
        `V = ${fmt(+(3.14 * r * r * h / 3).toFixed(4))}（立方厘米）`];
    } else {
      if (kind === '侧面积') return ['圆柱的侧面积 = 底面周长 × 高：S侧 = 2πrh',
        `S侧 = 2 × 3.14 × ${r} × ${h} = ${fmt(+(2 * 3.14 * r * h).toFixed(4))}（平方厘米）`];
      if (kind === '表面积') return ['圆柱的表面积 = 侧面积 + 两个底面积：S = 2πrh + 2πr²',
        `侧面积 = 2 × 3.14 × ${r} × ${h} = ${fmt(+(2 * 3.14 * r * h).toFixed(4))}`,
        `两个底面积 = 2 × 3.14 × ${r}² = ${fmt(+(2 * 3.14 * r * r).toFixed(4))}`,
        `表面积 = ${fmt(+(2 * 3.14 * r * h + 2 * 3.14 * r * r).toFixed(4))}（平方厘米）`];
      if (kind === '体积') return ['圆柱的体积 = 底面积 × 高：V = πr²h',
        `V = 3.14 × ${r}² × ${h} = 3.14 × ${fmt(+(r * r).toFixed(4))} × ${h}`,
        `V = ${fmt(+(3.14 * r * r * h).toFixed(4))}（立方厘米）`];
    }
  }

  // 统计：众数 / 中位数 / 平均数
  m = t.match(/^数据([\d、.]+)的众数是？$/);
  if (m) {
    const ds = m[1].split('、').map(Number);
    const cnt = {};
    ds.forEach(function (d) { cnt[d] = (cnt[d] || 0) + 1; });
    let best = ds[0], bc = 0;
    ds.forEach(function (d) { if (cnt[d] > bc) { bc = cnt[d]; best = d; } });
    return ['众数是一组数据中出现次数最多的那个数',
      `逐个统计：${ds.map(function (d) { return d + ' 出现 ' + cnt[d] + ' 次'; }).join('，')}`,
      `出现次数最多的是 ${best}（${bc} 次），所以众数是 ${best}`];
  }
  m = t.match(/^数据([\d、.]+)的中位数是？$/);
  if (m) {
    const ds = m[1].split('、').map(Number).sort(function (a, b) { return a - b; });
    const n = ds.length, mid = n % 2 ? ds[(n - 1) / 2] : (ds[n / 2 - 1] + ds[n / 2]) / 2;
    return ['求中位数要先按从小到大的顺序排列',
      `排序后：${ds.join('、')}，一共有 ${n} 个数`,
      n % 2 ? `奇数个数，取正中间的第 ${(n + 1) / 2} 个：${mid}` : `偶数个数，取中间两个数的平均数：(${ds[n / 2 - 1]} + ${ds[n / 2]}) ÷ 2 = ${fmt(+mid.toFixed(4))}`];
  }

  // 鸽巢问题（鸽子版）
  m = t.match(/把(\d+)只鸽子飞进(\d+)个鸽巢/);
  if (m) {
    const n = +m[1], d = +m[2], q2 = Math.floor(n / d);
    return ['把鸽子看作物体、鸽巢看作抽屉，用「至少数 = 商 + 1」',
      `${n} ÷ ${d} = ${q2}……${n - q2 * d}`,
      `至少数 = ${q2} + 1 = ${q2 + 1}（只）`];
  }

  // 植树问题（四类：两端都种 +1 / 只种一端 不变 / 两端都不种 −1 / 封闭图形 不变）
  m = t.match(/(\d+(?:\.\d+)?)米.{0,20}?每隔(\d+(?:\.\d+)?)米/);
  if (m && /种|放|栽|摆|插|安/.test(t)) {
    const L = +m[1], g = +m[2], n = L / g;
    let delta, why;
    if (/两端都不种|两端都不栽|两端都不放|两端都不摆/.test(t)) { delta = -1; why = '两端都不种：棵数 = 间隔数 − 1'; }
    else if (/只在一端|只种一端|另一端不放|只有一端|一端放/.test(t)) { delta = 0; why = '只种一端（另一端不放）：棵数 = 间隔数'; }
    else if (/圆|周长|封闭|一圈|池塘/.test(t)) { delta = 0; why = '封闭图形（围成一圈）：棵数 = 间隔数'; }
    else { delta = 1; why = '两端都种：棵数 = 间隔数 + 1'; }
    return ['先求间隔数：间隔数 = 总长 ÷ 间距',
      `${L} ÷ ${g} = ${fmt(+n.toFixed(4))}（个间隔）`,
      why,
      delta === 0 ? `棵数 = 间隔数 = ${fmt(+n.toFixed(4))}`
        : `棵数 = ${fmt(+n.toFixed(4))} ${delta > 0 ? '+' : '−'} 1 = ${fmt(+(n + delta).toFixed(4))}`];
  }
  // 敲钟间隔 / 爬楼层数（间隔数 = 个数 − 1）
  m = t.match(/敲(\d+)下/);
  if (m && /间隔/.test(t)) {
    const n = +m[1];
    return [`敲 ${n} 下，第 1 下就是起点，中间只有 ${n} − 1 个间隔`, `${n} − 1 = ${n - 1}（个间隔）`];
  }
  m = t.match(/从(\d+)楼走到(\d+)楼/);
  if (m) {
    const a2 = +m[1], b2 = +m[2];
    return ['从第 a 层走到第 b 层，实际走的层数 = b − a（起点那层不用走）', `${b2} − ${a2} = ${b2 - a2}（层）`];
  }

  // 角度：已知一个角求另一个角（直角 90° / 平角 180° / 对顶角 / 邻补角）
  m = t.match(/已知∠?(\d+)=(\d+(?:\.\d+)?)°，?∠?(\d+)=/);
  if (m) {
    const known = +m[2];
    if (/组成一个直角|成直角|直角分成|将直角分成|分成∠1和∠2/.test(t) && near(90 - known))
      return ['直角是 90°，两个角合起来正好是一个直角',
        `∠${m[3]} = 90° − ${known}° = ${fmt(+(90 - known).toFixed(4))}°`];
    if (/对顶角/.test(t) && near(known))
      return ['两条直线相交，相对的两个角（对顶角）大小相等',
        `∠${m[3]} = ∠${m[1]} = ${known}°`];
    if (/邻补角/.test(t) && near(180 - known))
      return ['相邻的两个角合起来是一个平角（180°），这样的两个角互为邻补角',
        `∠${m[3]} = 180° − ${known}° = ${fmt(+(180 - known).toFixed(4))}°`];
    if (/平角/.test(t) && near(180 - known))
      return ['平角是 180°，两个角合起来正好是一个平角',
        `∠${m[3]} = 180° − ${known}° = ${fmt(+(180 - known).toFixed(4))}°`];
    if (near(180 - known))
      return ['直线上相邻的几个角合起来是一个平角（180°）',
        `∠${m[3]} = 180° − ${known}° = ${fmt(+(180 - known).toFixed(4))}°`];
  }
  // 角度：一条直线上三个角，已知两个求第三个
  m = t.match(/已知∠(\d+)=(\d+(?:\.\d+)?)°，?∠(\d+)=(\d+(?:\.\d+)?)°，?∠(\d+)=/);
  if (m) {
    const x = +m[2], y = +m[4], z = 180 - x - y;
    if (near(z)) return ['一条直线上的三个角合起来正好是一个平角（180°）',
      `∠${m[5]} = 180° − ${x}° − ${y}° = ${fmt(+z.toFixed(4))}°`];
  }
  // 折纸折角：折过去的部分与原来重合，露出的角是折起角的 2 倍。
  // 只在答案吻合时才输出——不同配图的几何关系可能不同，宁可不讲也不能讲错。
  m = t.match(/折痕折起.{0,8}，?已知∠(\d+)=(\d+(?:\.\d+)?)°，?∠(\d+)=/);
  if (m) {
    const known = +m[2];
    if (near(known / 2)) return ['折过去的部分和原来的部分完全重合，所以露出的大角是折起小角的 2 倍',
      `∠${m[3]} = ${known}° ÷ 2 = ${fmt(+(known / 2).toFixed(4))}°`];
    if (near(known)) return ['折叠只是改变位置，角的大小不变',
      `∠${m[3]} = ∠${m[1]} = ${known}°`];
  }
  // 三角板拼角：一副三角板能拼出的角一定是 15° 的整数倍
  m = t.match(/三角板.{0,24}能拼出(\d+)°的角吗/);
  if (m) {
    const d = +m[1], ok = d % 15 === 0;
    return ['一副三角板上只有 30°、60°、90° 和 45°、45°、90°，拼出来的角一定是 15° 的整数倍',
      `${d}° ${ok ? '是' : '不是'} 15° 的整数倍（${d} ÷ 15 = ${fmt(+(d / 15).toFixed(4))}）`,
      ok ? `所以能拼出 ${d}° 的角` : `所以不能拼出 ${d}° 的角`];
  }

  // 工程问题：合做效率
  m = t.match(/单独做(\d+)天完成，\S{0,8}单独做(\d+)天完成，\S{0,8}合做每天完成/);
  if (m) {
    const a = +m[1], b = +m[2];
    return ['把整项工程看作单位「1」，工作效率 = 1 ÷ 工作时间',
      `两人每天分别完成 1/${a} 和 1/${b}`,
      `通分相加：1/${a} + 1/${b} = ${b}/${a * b} + ${a}/${a * b} = ${a + b}/${a * b}`];
  }
  // 工程问题：n 天完成工程的几分之几
  m = t.match(/独做(\d+)天完成，\S{0,8}(\d+)天完成工程的几分之几/);
  if (m) {
    const d = +m[1], n = +m[2];
    return ['把整项工程看作单位「1」，每天完成 1 ÷ 总天数',
      `每天完成 1/${d}，${n} 天就完成 ${n} 个 1/${d}`,
      `${n} × 1/${d} = ${n}/${d}`];
  }

  // 位置与方向：两个观测点方向相对
  m = t.match(/^(.+)在(.+)的(南|北)偏(东|西)(\d+)°方向上，那么/);
  if (m) {
    // 捕获组：m[3]=南/北，m[4]=东/西，m[5]=角度（勿偏移，早期版本曾误用 m[4]/m[5]/m[6]）
    const flip = { 南: '北', 北: '南', 东: '西', 西: '东' };
    const d = flip[m[3]], e = flip[m[4]];
    return ['两人的位置互换后，要以另一个人为观测点重新看方向',
      '方向要改成相反方向：南↔北，东↔西，偏转的角度不变',
      `${m[3]}偏${m[4]}${m[5]}° 的相反方向是 ${d}偏${e}${m[5]}°`];
  }
  // 位置与方向：同一种方向的两种说法（互余）
  m = t.match(/^「(南|北)偏(东|西)(\d+)°」方向的另一种说法是/);
  if (m) {
    const x = +m[3], y = 90 - x;
    return ['同一个方向可以用两组基准来描述，两组角度相加是 90°',
      `${m[1]}偏${m[2]}${x}° = ${m[2]}偏${m[1]}${y}°（因为 ${x}° + ${y}° = 90°）`];
  }

  // 数与形：正方形数
  m = t.match(/拼到第(\d+)层时用了(\d+)个小正方形，再拼上第(\d+)层后一共/);
  if (m) {
    const n = +m[3];
    return ['从 1 开始拼，每层都是一个大正方形，第 n 层一共 n² 个小正方形',
      `拼到第 ${n} 层时，一共是 ${n}² = ${n * n}（个）`];
  }

  // 最大公因数 / 最小公倍数
  m = t.match(/^(\d+)和(\d+)的最大公因数是？$/);
  if (m) {
    const a = +m[1], b = +m[2], g = gcd(a, b);
    return ['最大公因数是两个数公有因数中最大的那个',
      `${a} 的因数与 ${b} 的因数中，公有的最大的是 ${g}`,
      `所以最大公因数是 ${g}`];
  }
  m = t.match(/^(\d+)和(\d+)的最小公倍数是？$/);
  if (m) {
    const a = +m[1], b = +m[2], g = gcd(a, b), l = a * b / g;
    return ['最小公倍数 = 两数的乘积 ÷ 最大公因数',
      `${a} 和 ${b} 的最大公因数是 ${g}`,
      `最小公倍数 = ${a} × ${b} ÷ ${g} = ${l}`];
  }

  // 长方形周长 / 面积（低年级高频）
  m = t.match(/长(\d+(?:\.\d+)?)[\u4e00-\u9fa5]{0,2}、?宽(\d+(?:\.\d+)?)/);
  if (m && /周长/.test(t)) {
    const a = +m[1], b = +m[2];
    return ['长方形周长 = （长 + 宽）× 2', `(${a} + ${b}) × 2 = ${fmt(+((a + b) * 2).toFixed(4))}`];
  }
  if (m && /面积/.test(t)) {
    const a = +m[1], b = +m[2];
    return ['长方形面积 = 长 × 宽', `${a} × ${b} = ${fmt(+(a * b).toFixed(4))}`];
  }
  // 单价 × 数量
  m = t.match(/每个(\d+(?:\.\d+)?)元，买(\d+(?:\.\d+)?)个/);
  if (m) {
    const p = +m[1], n = +m[2];
    return ['总价 = 单价 × 数量', `${p} × ${n} = ${fmt(+(p * n).toFixed(4))}（元）`];
  }
  // 比一个数大/小几
  m = t.match(/比(\d+(?:\.\d+)?)大(\d+(?:\.\d+)?)的数是/);
  if (m) return ['求比一个数大几的数，用加法', `${m[1]} + ${m[2]} = ${fmt(+(+m[1] + +m[2]).toFixed(4))}`];
  m = t.match(/比(\d+(?:\.\d+)?)小(\d+(?:\.\d+)?)的数是/);
  if (m) return ['求比一个数小几的数，用减法', `${m[1]} - ${m[2]} = ${fmt(+(+m[1] - +m[2]).toFixed(4))}`];

  /* ---------- L2 · 分数关系反推（结果必须与答案精确一致才输出） ---------- */
  m = t.match(/(\d+)\/(\d+)/);
  if (m && +m[2] !== 0) {
    const a = +m[1], b = +m[2];
    // 取分数之外的数字作为参与运算的量
    const rest = t.slice(0, m.index) + ' ' + t.slice(m.index + m[0].length);
    const nums = stepNums(rest);
    for (let i = nums.length - 1; i >= 0; i--) {
      const n = nums[i];
      if (near(n * a / b)) return ['求一个数的几分之几是多少，用乘法计算',
        `${n} × ${a}/${b} = ${n} × ${a} ÷ ${b} = ${fmt(+(n * a / b).toFixed(4))}`];
      if (near(n / (a / b))) return ['已知一个数的几分之几是多少，求这个数，用除法计算',
        `${n} ÷ ${a}/${b} = ${n} × ${b}/${a} = ${fmt(+(n * b / a).toFixed(4))}`];
    }
  }

  /* ---------- L2b · 关键词驱动列式（无运算信号就绝不猜） ---------- */
  if (ansIsPlainNum && !isNaN(an)) {
    const nums = stepNums(t.replace(/(\d+)\/(\d+)/g, ''));   // 排除分数内部数字
    if (nums.length >= 2 && nums.length <= 5) {
      let ops = [];
      if (/一共|总共|共有|合计|和是|相加|之和|共多少|一共有/.test(t)) ops.push('+');
      if (/还剩|剩下|还差|相差|多多少|少多少|比\S{1,8}多|比\S{1,8}少/.test(t)) ops.push('-');
      if (/每个|每组|每行|每份|倍|面积|体积|总价|周长/.test(t)) ops.push('×');
      if (/平均|可以分成|分成|速度|每小时|每天|单价/.test(t)) ops.push('÷');
      // 题干里没有任何运算信号就绝不猜：宁可交给单元知识卡，也不能编一条错的算式
      if (!ops.length) return null;
      for (let oi = 0; oi < ops.length; oi++) {
        const op = ops[oi];
        for (let i = 0; i < nums.length; i++) {
          for (let j = 0; j < nums.length; j++) {
            if (i === j) continue;
            const a = nums[i], b = nums[j];
            const r = op === '+' ? a + b : op === '-' ? a - b : op === '×' ? a * b : (b ? a / b : NaN);
            if (!near(r)) continue;
            const why = op === '+' ? '求一共是多少，用加法'
              : op === '-' ? '求相差多少，用减法'
              : op === '×' ? '求几个几是多少，用乘法'
              : '求每份是多少，用除法';
            return [why, `${a} ${op} ${b} = ${fmt(+r.toFixed(4))}`, `所以答案是 ${ans}`];
          }
        }
      }
    }
  }

  /* ---------- L3 · 单元知识卡兜底 ---------- */
  const card = stepsFromUnitCard(unit, ans, t);
  if (card) {
    const opt = stepOptionsLine(q);
    if (opt) card.push(opt);
    return card;
  }

  /* ---------- 终极兜底：读题 → 方法 → 答案 ---------- */
  const last = ['先读题，找出题目给出的已知条件和要求的问题',
    '再选择本单元学过的方法列式或判断',
    '正确答案：' + ans];
  const opt2 = stepOptionsLine(q);
  if (opt2) last.push(opt2);
  return last;
}

// ============================================================
// v51：难度分级（基础 : 提高 : 拓展 = 6 : 3 : 1）
// ============================================================
const DIFF_NAMES = { 1: '基础', 2: '提高', 3: '拓展' };

// 绝对难度信号分（越大越难）：题干长度 / 策略词 / 多步运算 / 解析步骤数 / 题型
function difficultyScore(q) {
  let t = String((q && q.question) || '').replace(/<[^>]+>/g, '');
  let s = Math.min(t.length / 12, 3);   // 长度信号：应用题题干长
  if (/至少|最少|保证|怎样|为什么|规律|第\s*\d+\s*个/.test(t)) s += 2;   // 策略/探究词
  if (/\d+\s*[+−-]\s*\d+\s*[+−-]\s*\d+/.test(t)) s += 1;                // 两步以上加减
  if (/[×÷]/.test(t) && t.split(/[×÷]/).length >= 3) s += 1;           // 两步以上乘除
  // v81：stepsGeneric 表示这组步骤是通用引擎兜底生成的，不能当作「多步运算」的难度信号，
  // 否则几乎所有题都会 +1 分，把 6:3:1 的梯度压平。
  if (q && q.steps && q.steps.length >= 3 && !q.stepsGeneric) s += 1;
  if (q && q.type === 'fill') s += 0.5;
  return s;
}

function shuffleArr(a) {
  for (let i = a.length - 1; i > 0; i--) {
    let j = Math.floor(Math.random() * (i + 1));
    let t = a[i]; a[i] = a[j]; a[j] = t;
  }
  return a;
}

// 相对难度打标：按信号分在集合内排序，前 60% → 基础，中 30% → 提高，后 10% → 拓展。
// 同一题池内相对排名，保证任意单元/试卷都能得到 6:3:1 的难度梯度（原地打标）。
function tagRelativeDifficulty(arr) {
  if (!arr || !arr.length) return arr;
  let scored = arr.map(q => ({ q: q, s: difficultyScore(q) + Math.random() * 0.01 }));
  scored.sort((a, b) => a.s - b.s);
  let n = scored.length;
  let b = Math.round(n * 0.6), m = Math.round(n * 0.9);
  scored.forEach((o, i) => { o.q.diff = (i < b) ? 1 : (i < m) ? 2 : 3; });
  return arr;
}

// 题目难度：显式 q.diff 优先（相对打标结果），否则退回启发式
function questionDifficulty(q) {
  if (q && q.diff) return q.diff;
  let t = String((q && q.question) || '').replace(/<[^>]+>/g, '');
  if (/至少|最少|最多几次|怎样|为什么|规律|第\s*\d+\s*个/.test(t)) return 3;
  let appWord = /每|一共|还剩|还差|小时|分钟|千米|公斤|千克|棵|支|块|页|天/.test(t);
  if (appWord && t.length >= 18) return 2;
  if (/\d+\s*[+−-]\s*\d+\s*[+−-]\s*\d+/.test(t)) return 2;
  if (/[×÷]/.test(t) && t.split(/[×÷]/).length >= 3) return 2;
  if (q && q.steps && q.steps.length >= 3 && !q.stepsGeneric) return 2;  // v81：同 difficultyScore，排除兜底步骤
  return 1;
}

// n 题的 6:3:1 配比（四舍五入后把余量给拓展档）
function diffMixFor(n) {
  let b = Math.round(n * 0.6), a = Math.round(n * 0.3);
  let c = n - b - a;
  if (c < 0) { b += c; c = 0; }   // n 很小时保证总数不超
  return [b, a, c];
}

// 从候选题中挑 n 道：题面去重 → 相对打标 → 按难度 6:3:1 抽取（各档内随机）；
// 某档候选不足时在该档内循环复用（重复题仍留在原难度档，保持由易到难）。
// 输出按 基础→提高→拓展 排序。
function pickDifficultyMix(cands, n) {
  let seen = new Set();
  let uniq = [];
  (cands || []).forEach(q => {
    let t = String((q && q.question) || '');
    if (seen.has(t)) return;
    seen.add(t);
    uniq.push(q);
  });
  tagRelativeDifficulty(uniq);
  let byDiff = { 1: [], 2: [], 3: [] };
  uniq.forEach(q => byDiff[q.diff].push(q));
  [1, 2, 3].forEach(d => shuffleArr(byDiff[d]));
  let want = diffMixFor(n);
  let out = [];
  [1, 2, 3].forEach(d => {
    let band = byDiff[d];
    if (!band.length) return;
    for (let k = 0; k < want[d - 1]; k++) out.push(band[k % band.length]);
  });
  // 个别档整档为空：按 基础→提高→拓展 顺序从全量补齐
  if (out.length < n) {
    let orderedAll = byDiff[1].concat(byDiff[2], byDiff[3]);
    let fi = 0;
    while (out.length < n && orderedAll.length) { out.push(orderedAll[fi % orderedAll.length]); fi++; }
  }
  while (out.length < n) out.push({ question: '', answer: '', type: 'fill' });
  return out;
}

// v69：卷面结构自适应。
// 单元考试只考本单元，但部分单元可出题量远不足 30（一年级「图形拼组」只有 1 种题），
// 硬套 30 题卷面会组出「卷头写 30 题、实际只有 4 题」的残卷。
// 这里按 20/30/20/30 的分区权重等比收缩题数，并用最大余数法把 100 分精确拆到每一题，
// 保证「卷面题数」与「满分 100」两条承诺同时兑现。
// v69：可以安全地把一道选择题改成填空题吗？
// 「平移不改变图形的（　）和（　）」答案是「大小和形状」——题干 2 个空、答案却是 1 段。
// 强行 forceFill 会渲染出 2 个输入框对 1 个答案，孩子根本填不出来。这类题一律保留选项。
function canForceFill(q) {
  if (countFillBlanks(q) < 2) return true;
  const parts = String(q.answer == null ? '' : q.answer)
    .split(/[,，、\/]+/).map(s => s.trim()).filter(s => s !== '');
  return parts.length >= 2;
}

// ============================================================
// v73：判断题派生器
// 广西卷 1-6 年级全学段必考判断题（南宁二上真卷「四、我会判断」5 分、
// 桂林/钦州六上「判断题」5-10 分），但本站题库里一道原生判断题都没有。
// 与其给 131 个单元逐个手写判断题生成器（工程量大且必然有单元漏配），
// 不如从本单元题池里的「数值答案题」自动派生：
//     原题 「25 × 4 = ？」 答案 100
//     派生 「25 × 4 = 100（　）」答案 正确   ← 50% 走这条
//     　　 「25 × 4 = 90（　）」 答案 错误   ← 50% 走这条（错值在真值附近扰动）
// 这样任何有数值答案的单元都能稳定产出判断题，且随单元知识点自然变化。
// ============================================================

// 把「疑问句题干 + 答案」拼成一句可直接判断对错的陈述
function judgeStatement(question, value) {
  let t = String(question || '').trim();
  if (!t || value === '' || value == null) return '';
  // 「括号里填几？」「在（　）里填上合适的数」这类元描述句式，
  // 改造成陈述句后语义是断裂的（"2+3=4，括号里填几"），一律不派生。
  if (/括号|填几|填上|里填|填一填|填[“"]/.test(t)) return '';
  // v83t：强图依赖题面（"图中阴影部分占几分之几""看图回答""上图是..."）也拒绝派生。
  // 派生后会变成「图中阴影部分占几分之几？A/B（）」，题面文本里仍有「图中」三个字，
  // 孩子必须看到原图才能判断对错；如果派生时不带图，体验就是「题干说看图却看不到图」。
  // （虽然 v83t 已让 deriveJudgeQuestions 透传 svg 兜底，但叙述型陈述「3/9 约分后等于 1/3」
  //  比「图中阴影部分占几分之几 1/4（）」更标准、命题质量也更高，故一并拒绝。）
  if (/图中阴影|图中阴影部分|看图|上图|下图|左图|右图/.test(t)) return '';
  // 只在题干末尾留一个判断空位，供孩子打 √ / ×
  const BLANK = '（　　）';
  let s = '';
  if (/=\s*[？?]\s*$/.test(t)) {
    // 「25 × 4 = ？」→「25 × 4 = 100」
    s = t.replace(/=\s*[？?]\s*$/, '= ' + value);
  } else if (/（\s*）|\(\s*\)|＿+|_{2,}/.test(t)) {
    // 「36 里面有（　）个 6」→「36 里面有 6 个 6」（只填唯一一个空，多空题不派生）
    if ((t.match(/（\s*）|\(\s*\)|＿+|_{2,}/g) || []).length !== 1) return '';
    s = t.replace(/（\s*）|\(\s*\)|＿+|_{2,}/, String(value));
    s = s.replace(/[？?]\s*$/, '');            // 「5/9 里面有（　）个 1/9？」→ 去掉残留问号
  } else if (/[？?]\s*$/.test(t)) {
    // 「一个数的 3 倍是 24，这个数是？」
    s = t.replace(/[？?]\s*$/, '') + String(value);
  } else {
    return '';
  }
  if (/[？?]/.test(s)) return '';              // 还有问号就不是一个陈述句
  if (s.length > 46) return '';                // 太长的陈述不适合做判断题
  return s + BLANK;
}

// 在真值附近造一个「像那么回事但确实错」的值
function judgeWrongValue(correct) {
  let c = String(correct).trim();
  // 分数 a/b：分子分母互换或分子 ±1
  let fm = c.match(/^(-?\d+)\/(\d+)$/);
  if (fm) {
    let a = +fm[1], b = +fm[2];
    if (a !== b && b !== 0) return a + '/' + (a === 1 ? b + 1 : Math.max(1, a - 1));
    return a + '/' + (b + 1);
  }
  let v = parseFloat(c);
  if (isNaN(v)) return '';
  let isInt = /^-?\d+$/.test(c);
  let mag = Math.max(1, Math.abs(v));
  let delta = Math.max(1, Math.round(mag * 0.25));       // 25% 幅度的扰动
  let cand = v + (Math.random() < 0.5 ? delta : -delta);
  if (cand < 0) cand = v + delta;                        // 小学阶段不出现负数
  if (isInt) cand = Math.round(cand);
  else cand = Math.round(cand * 100) / 100;
  if (String(cand) === c) cand = isInt ? cand + 1 : cand + 0.5;
  if (String(cand) === c) return '';
  return String(cand);
}

// 从题池派生 n 道判断题（题面去重，正确/错误各约一半）
function deriveJudgeQuestions(pool, n, usedText) {
  let out = [];
  if (!pool || !pool.length || n <= 0) return out;
  let src = shuffleArr(pool.slice());
  let localText = new Set();
  let wrongQuota = Math.floor(n / 2);                    // 保证错题（答案=错误）占一半
  for (let i = 0; i < src.length && out.length < n; i++) {
    let q = src[i];
    if (!q || q.judge || q._derived) continue;
    let ans = String(q.answer == null ? '' : q.answer).trim();
    if (ans === '' || ans.length > 12) continue;
    if (!/^-?\d+(\.\d+)?$/.test(ans) && !/^-?\d+\/\d+$/.test(ans)) continue; // 只派生数值/分数答案
    let wantWrong = wrongQuota > 0 && (n - out.length) <= wrongQuota * 2;
    let shown = ans;
    if (wantWrong) {
      let w = judgeWrongValue(ans);
      if (w === '') continue;
      shown = w;
      wrongQuota--;
    }
    let stmt = judgeStatement(q.question, shown);
    if (!stmt) continue;
    if (usedText && usedText.has(stmt)) continue;
    if (localText.has(stmt)) continue;
    localText.add(stmt);
    if (usedText) usedText.add(stmt);
    // v83t：派生判断题时拷 svg —— 否则原题「图中阴影部分占几分之几？」这种带图题
    // 派生后变成「图中阴影部分占几分之几？A/B （）」，孩子没有图根本判断不了对错，
    // 且题目下方还显「图中」三个字却看不到配图，体验完全崩塌。
    out.push({
      type: 'choice',
      judge: true,
      question: stmt,
      options: ['正确', '错误'],
      answer: (shown === ans) ? '正确' : '错误',
      answerIdx: (shown === ans) ? 0 : 1,
      svg: q.svg,                                    // v83t：把原题的 svg 透传
      _unitType: q._unitType,
      _unitName: q._unitName,
      _core: q._core,
      _derived: true,
      _origQ: q.question,                            // v83t：便于回溯源题
    });
  }
  // 错题配额没用完（可派生的题太少）：把已有的判断题随机翻一半为「错误」
  if (out.length && wrongQuota > 0) {
    let flip = shuffleArr(out.slice()).slice(0, Math.min(wrongQuota, Math.floor(out.length / 2)));
    flip.forEach(j => { j.answer = '错误'; j.answerIdx = 1; });
  }
  return out;
}

// 注：v73 起 buildPaperStructure(grade, capQ) 已上移到 GX_SECTIONS_* 定义处，
// 按广西真题六分区结构生成（此处不再有旧的四分区版本）。

// v73.2：把「广西真实期末卷」原题替换进已组好卷子的对应分区。
// 只在 GX_REAL 命中 grade-sem-type 键时生效；未命中的卷（单元考/期中/无真卷年级）
// 保持程序化生成，由卷头 badget 标注「模拟」。
// 注：题库题形与题池一致（calc/fill/choice/judge/app），可直接就地替换，不影响分区标签与分值。
function gxRealKey(g, sem, type) { return g + '-' + sem + '-' + type; }
function injectRealIntoPaper(questions, STRUCT, grade, sem, type) {
  let bank = (window.GX_REAL && window.GX_REAL[gxRealKey(grade, sem, type)]) || null;
  if (!bank) return { realCount: 0, region: '' };
  let region = (bank.meta && bank.meta.region) || '广西';
  let realCount = 0;
  STRUCT.forEach(sec => {
    let real = (bank[sec.key] || []);
    if (!real.length) return;
    real = shuffleArr(real.slice());
    let idxs = [];
    questions.forEach((q, i) => { if (q._section === sec.key) idxs.push(i); });
    let n = Math.min(real.length, idxs.length, sec.count);
    for (let k = 0; k < n; k++) {
      let rq = real[k];
      let item = {
        question: rq.q,
        answer: rq.a,
        type: rq.type,
        _section: sec.key,
        sectionTitle: sec.title,
        score: questions[idxs[k]].score,
        num: questions[idxs[k]].num,
        _real: true,
        _unitName: '广西真题',
        _region: region,
        diff: rq.diff || 1,
      };
      if (rq.opts) item.options = rq.opts.slice();
      if (rq.judge) { item.judge = true; if (!item.options) item.options = ['正确', '错误']; }
      // 填空/计算/应用：答案可书面输入的统一转填空；选择题无选项也降级填空
      if ((sec.key === 'fill' || sec.key === 'calc' || sec.key === 'app') && isTypableAnswer(item.answer) && canForceFill(item)) {
        item.forceFill = true;
      } else if (sec.key === 'choice' && (!item.options || item.options.length < 2) && canForceFill(item)) {
        item.forceFill = true;
      }
      if (!item.steps) item.steps = generateSteps(item, unitMetaFor(item));
      questions[idxs[k]] = item;
      realCount++;
    }
  });
  return { realCount: realCount, region: region };
}

function generateExamPaper() {
  let { units, all, rangeText } = getExamUnits();
  if (!units || units.length === 0) return null;

  let seen = new Set();
  // v73：候选池 90 → 120。六分区结构下每个分区都要挑 5~9 道，
  // 池子太小时严格去重轮选不满，会退到「放宽重复」轮，卷面就出现雷同题。
  let pool = buildQuestionPool(units, 120, seen, true);

  // 单元题量不足时，用同册其他单元补充（相当于试卷中的"复习巩固"部分）。
  // 单元考试只考本单元，绝不混入其他单元，故跳过补充。
  if (pool.length < 60 && all && all.length > units.length && examState.type !== 'unit') {
    let others = all.filter(u => units.indexOf(u) === -1);
    pool = pool.concat(buildQuestionPool(others, 90 - pool.length, seen, false));
  }
  if (pool.length === 0) return null;

  // v73：先看清池子有多大，再决定卷面题数（顺序反过来了）。
  // 旧版是「先定死 30 题、再去组卷」——池子不够时只能靠克隆凑数，
  // 于是出现「6上·分数乘法 估 40 题、实际只组出 21 题且夹带克隆」的怪相。
  // 这里用视觉去重口径（题面+图形）数一遍真实容量，据此封顶，
  // 卷头如实写明题数，让孩子拿到的是一份每题都不同的卷子。
  let capQ = GX_PAPER_TOTAL;
  let capLimited = false;
  let realCap = new Set(pool.map(q => visKey(q))).size;
  if (realCap > 0 && realCap < capQ) { capQ = realCap; capLimited = true; }
  capQ = Math.max(5, Math.min(GX_PAPER_TOTAL, capQ));
  let STRUCT = buildPaperStructure(examState.grade, capQ);

  // v73：派生判断题并注入题池（广西卷 1-6 年级全学段必考「判断题」区）。
  // 必须在分区选题之前注入，这样判断题也能参与相对难度打标与题面去重。
  // 多派生 3 倍候选（至少 12 道），保证挑得出 5 道互不重复、且对错各半。
  let judgeNeed = STRUCT.filter(s => s.key === 'judge').reduce((a, s) => a + s.count, 0);
  if (judgeNeed > 0) {
    deriveJudgeQuestions(pool, Math.max(judgeNeed * 3, 12), null).forEach(j => pool.push(j));
  }

  // v50：不足整卷需求时允许少量重复以凑满整卷（卷面题数必须兑现）。
  // 单元考试只克隆本单元题池，绝不混入其他单元。
  // v69：整卷题数改为 capQ（单元考试会按出题能力收缩），填充目标随之下调，
  // 避免小池子被无谓地复制成一堆同题。
  let baseLen = pool.length;
  // v73：补位目标由 capQ+2 下调为 capQ。克隆题是卷面雷同的头号来源，
  // 池子被放大到 120 之后，只有确实凑不够整卷时才需要克隆兜底。
  let padTo = Math.max(capQ, 12);
  if (baseLen > 0 && pool.length < padTo) {
    // v73：克隆补位时跳过派生判断题——判断题题干都从同一批原题派生，
    // 克隆后必然出现一模一样的陈述句，是最扎眼的一类重复。
    let plain = [];
    for (let k = 0; k < baseLen; k++) if (!pool[k].judge) plain.push(k);
    let src = plain.length ? plain : null;
    let ki = 0;
    while (pool.length < padTo && src) {
      pool.push(Object.assign({}, pool[src[ki++ % src.length]]));
    }
  }

  // v51：题池整体相对打标（前60%基础/中30%提高/后10%拓展），供分区按 6:3:1 选题
  tagRelativeDifficulty(pool);

  let used = new Set();
  let usedText = new Set();   // 跨分区共享的题面文本去重（v49：杜绝视觉重复题）
  let questions = [];

  STRUCT.forEach(sec => {
    // v51：分区内部按 6:3:1 难度配比选题（基础→提高→拓展）；
    // 某难度档候选不足时回退为原逻辑按题型分值选题，保证分区题数不减。
    let mix = diffMixFor(sec.count);
    let picked = [];
    [1, 2, 3].forEach(d => {
      if (!mix[d - 1]) return;
      let baseScorer = getSectionScorer(sec.key);
      let sub = pickFromPool(pool, used, mix[d - 1], q => (questionDifficulty(q) === d ? baseScorer(q) : 0), usedText);
      picked = picked.concat(sub);
    });
    if (picked.length < sec.count && sec.key === 'judge') {
      // v73：本单元一道判断题都派生不出来（全部是非数值答案的概念题）
      // ——降级为普通选择题顶上，保证分区题数不缺。
      picked = picked.concat(pickFromPool(pool, used, sec.count - picked.length, getSectionScorer('choice'), usedText));
    }
    if (picked.length < sec.count) {
      picked = picked.concat(pickFromPool(pool, used, sec.count - picked.length, getSectionScorer(sec.key), usedText));
    }
    picked.forEach((q, k) => {
      let item = Object.assign({}, q);
      // v69：自适应卷面里同一分区各题分值可能差 1 分（最大余数法），逐题取用
      item.score = (sec.scores && sec.scores[k] != null) ? sec.scores[k] : sec.score;
      item.sectionTitle = sec.title;
      item._section = sec.key;               // v73：分区键，供题型标签与 PC 端排版使用
      item.forceFill = false;
      if (sec.key === 'fill' || sec.key === 'calc') {
        // 填空/计算：一律书面作答
        // v83r：原生选择题（type 为 choice/shape_choice 且 options≥2）即使答案可书写，
        // 也保留为选择题作答 —— 强行 forceFill 会让"下面哪个数是合数？"这类带 4 个数字
        // 选项的题只剩题干和输入框，4 个选项整体消失，渲染后"题干不完整"。
        // 真要补的只有：① 选项缺失（mc() 兜底就补齐了）② 单空答案无法多空作答。
        const nativeChoice = (item.type === 'choice' || item.type === 'shape_choice') &&
                             Array.isArray(item.options) && item.options.length >= 2;
        if (!nativeChoice && isTypableAnswer(item.answer) && canForceFill(item)) item.forceFill = true;
      } else if (sec.key === 'app') {
        // 应用题：能算出数值的写答案，否则保留选项
        if (isNumericAnswer(item.answer) || !item.options || item.options.length < 2) {
          if (isTypableAnswer(item.answer) && canForceFill(item)) item.forceFill = true;
        }
      } else if (sec.key === 'choice') {
        // 选择题：没有选项就退化为填空
        if ((!item.options || item.options.length < 2) && canForceFill(item)) item.forceFill = true;
      }
      // v73：judge（判断题）一律保留选项作答——「正确 / 错误」二选一，不能转成填空。
      questions.push(item);
    });
  });

  // 为每道题生成解题步骤
  questions.forEach((q, i) => {
    q.num = i + 1;
    if (!q.steps) q.steps = generateSteps(q, unitMetaFor(q));
  });

  // 配图保底：每套卷至少含 MIN_IMG 张配图题（真实试卷均有图形/图表题）。
  // 当考查范围本身不含足够图形题时，从同册"全册题池"补充，替换选择题区里的非配图题。
  // 注意：期末考 units===all（整册），不能用 all.length>units.length 判断，否则期末保底永远不触发。
  const MIN_IMG = 5;
  let imgNow = questions.filter(q => String(q.svg || '').includes('<')).length;
  // 配图题来源：期末/期中/月考从同册"全册题池"补充；单元考试只从"本单元题池"补充，绝不混入其他单元图形题。
  const imgSrc = (examState.type === 'unit') ? units : all;
  if (imgNow < MIN_IMG && imgSrc && imgSrc.length) {
    // 用独立 seen：初始题池构建时已把大量配图题计入 seen，若沿用会把可补充的配图题全部排除，保底失效。
    // 去重铁律：按题面文本去重（跨单元模板题题面可能相同而答案不同，按题面+答案去重会导致重复题）。
    let seenText = new Set(questions.map(q => visKey(q)));
    // v84s：再兜一层「题面+答案」去重。visKey 对带图题是「题面+图形」，
    // 于是同一道题的无图版与有图版会被判成两张不同的图，配图保底就把有图版补进卷面，
    // 结果卷面上出现两道题干与答案完全相同的题（如「从上面看一个圆柱，看到的形状是？」）。
    // 按「题面+答案」判重不会误伤参数化图形题（同题面、不同图、不同答案，如不同时刻的钟面）。
    let seenQA = new Set(questions.map(q => String(q.question) + '|' + String(q.answer)));
    // 采样量放大到 200：配图题集中在少数单元（如 6 下仅 9 种），target 过小会漏捞导致保底补不满。
    let imgPool = [];
    buildQuestionPool(imgSrc, 200, new Set(), false).forEach(q => {
      if (!String(q.svg || '').includes('<')) return;
      const qa = String(q.question) + '|' + String(q.answer);
      if (seenQA.has(qa)) return;
      if (seenText.has(visKey(q))) return;
      seenQA.add(qa);
      seenText.add(visKey(q));
      imgPool.push(q);
    });
    // v73.2：去掉操作题后，配图题优先补进「选择题」区，其次「解决问题」「填空题」区
    // （替换后保持原分区标签，题型不串区）；判断题区不参与替换（换掉就不成其为判断题了）。
    const noImg = o => !o.q.judge && !String(o.q.svg || '').includes('<');
    let replSlots = questions.map((q, i) => ({ q, i }))
      .filter(o => (o.q._section === 'choice' || (!o.q._section && o.q.sectionTitle && o.q.sectionTitle.includes('选择'))) && noImg(o))
      .concat(questions.map((q, i) => ({ q, i }))
        .filter(o => (o.q._section === 'app' || o.q._section === 'fill') && noImg(o)));
    let pi = 0, si = 0;
    while (imgNow < MIN_IMG && pi < imgPool.length && si < replSlots.length) {
      let cand = imgPool[pi++];
      let slot = replSlots[si++];
      let item = Object.assign({}, cand);
      item.score = slot.q.score;
      item.sectionTitle = slot.q.sectionTitle;
      item._section = slot.q._section;         // v73：保持原分区（题型标签不能串区）
      item.forceFill = false;
      if (slot.q._section === 'choice' && (!item.options || item.options.length < 2) && canForceFill(item)) item.forceFill = true;
      if (!item.steps) item.steps = generateSteps(item, unitMetaFor(item));
      item.num = slot.q.num;
      questions[slot.i] = item;
      imgNow++;
    }
  }

  let typeName = (EXAM_TYPES.find(t => t.key === examState.type) || {}).name.replace(/\s/g, '');
  let cnGrade = ['一', '二', '三', '四', '五', '六'][examState.grade - 1];
  let semName = examState.semester === 1 ? '上册' : '下册';

  // v51：卷面注明难度分布（基础/提高/拓展）
  let dcnt = { 1: 0, 2: 0, 3: 0 };
  questions.forEach(q => { dcnt[questionDifficulty(q)]++; });
  // v73：单元出题能力不足导致卷面收缩时，如实告诉孩子/家长，不假装是 30 题卷
  let capNote = capLimited ? ` · 本单元可出题量仅 ${capQ} 题` : '';

  // v73.2：真题注入——把「广西真实期末卷」原题替换进对应分区（其余程序化生成并标注模拟）
  let realInfo = injectRealIntoPaper(questions, STRUCT, examState.grade, examState.semester, examState.type);
  // 注入后重算难度分布，使卷头「基础/提高/拓展」反映真实题目
  dcnt = { 1: 0, 2: 0, 3: 0 };
  questions.forEach(q => { dcnt[questionDifficulty(q)]++; });

  // 卷头真题/模拟徽标：含真题干则标真题来源，否则标广西真题风格（模拟）
  let badge = realInfo.realCount > 0
    ? `真题（广西·${realInfo.region}）·含 ${realInfo.realCount}/${questions.length} 道真题干`
    : '模拟卷·广西真题风格';

  return {
    title: `${cnGrade}年级数学${semName} ${typeName}`,
    sub: `考查范围：${rangeText} · 满分100分 · 共${questions.length}题 · 基础${dcnt[1]}／提高${dcnt[2]}／拓展${dcnt[3]}${capNote} · ${badge}`,
    badge: badge,
    realCount: realInfo.realCount,
    questions: questions,
    typeName: typeName,
    structure: STRUCT.map(s => s.title),      // v73：卷面分区（供 PC 端与打印使用）
  };
}

function startExam() {
  if (!examState.type) { showToast('请先选择考试类型'); return; }

  showToast('正在组卷…');
  // 组卷前先切换年级上下文，保证题目难度与年级匹配
  state.currentGrade = examState.grade;
  state.currentSemester = examState.semester;
  setTimeout(() => {
    let paper = generateExamPaper();
    if (!paper || paper.questions.length === 0) {
      showToast('组卷失败，请换个范围试试');
      return;
    }

    state.quizMode = 'exam';
    state.quizTitle = paper.title;
    state.examPaper = paper;
    state.quizQuestions = paper.questions;
    state.quizIndex = 0;
    state.quizScore = 0;
    state.quizCorrect = 0;
    state.quizWrong = 0;
    state.quizWrongQuestions = [];
  state.qStatus = [];
  state.wrongMap = {};
  state.userAnswers = [];
  state.quizStartTime = Date.now();

    // 考试计时器（70分钟）
    if (state.examTimer) clearInterval(state.examTimer);
    state.examEndTime = Date.now() + 70 * 60 * 1000;
    state.examTimer = setInterval(() => {
      let remain = Math.max(0, Math.ceil((state.examEndTime - Date.now()) / 1000));
      let m = Math.floor(remain / 60), s = remain % 60;
      let timerEl = document.getElementById('examTimer');
      if (timerEl) timerEl.textContent = `用时 ${m}:${s.toString().padStart(2,'0')}`;
      if (remain <= 0) { clearInterval(state.examTimer); state.examTimer = null; finishQuiz(); }
    }, 1000);

    showPage('quiz');
    document.getElementById('backBtn').style.display = 'block';
    document.getElementById('backBtn').onclick = () => goBack();
    renderQuestion();
  }, 60);
}

function renderQuestion() {
  let q = state.quizQuestions[state.quizIndex];
  // v84 P3：概念/短语/多空填空题在渲染前改写成可点选形态（选择题 / 逐空词卡），
  // 保证「任何题都不许必须打字」。幂等，改写后打 _ikNorm 标记。
  if (window.InputKit && InputKit.normalizeConceptFill) {
    let nq = InputKit.normalizeConceptFill(q, state.quizQuestions);
    if (nq) q = nq;
  }
  state.selectedAnswer = null;
  state.answered = false;
  // v73.2：题号导航状态（0 未答 / 1 答对 / 2 答错），按当前题量校正长度
  if (!state.qStatus || state.qStatus.length !== state.quizQuestions.length) {
    state.qStatus = new Array(state.quizQuestions.length).fill(0);
  }

  // 更新进度
  document.getElementById('quizProgress').textContent = `第 ${state.quizIndex + 1} / ${state.quizQuestions.length} 题`;
  let isExam = state.quizMode === 'exam';
  document.getElementById('quizScore').textContent = isExam ? ('得分 ' + state.quizScore) : ('正确 ' + state.quizScore);

  // 考试模式：整页启用紧凑排版
  document.getElementById('page-quiz').classList.toggle('exam-mode', isExam);

  // 考试模式：试卷抬头只在第 1 题完整展示，之后收起为紧凑一行
  let paperHeader = document.getElementById('examPaperHeader');
  if (isExam && state.examPaper) {
    paperHeader.style.display = 'block';
    paperHeader.classList.toggle('compact', state.quizIndex > 0);
    document.getElementById('examPaperTitle').textContent = state.examPaper.title;
    document.getElementById('examPaperSub').textContent = state.examPaper.sub;
  } else {
    paperHeader.style.display = 'none';
  }
  let progress = (state.quizIndex + 1) / state.quizQuestions.length * 100;
  document.getElementById('progressFill').style.width = progress + '%';

  let card = document.getElementById('questionCard');
  let typeTag = getQuestionTypeTag(q);
  let html = '';

  // 考试模式：分区大标题只在该分区第一题出现，其余题显示细分区条
  if (q.sectionTitle) {
    let prev = state.quizIndex > 0 ? state.quizQuestions[state.quizIndex - 1] : null;
    let isSectionStart = !prev || prev.sectionTitle !== q.sectionTitle;
    if (isSectionStart) {
      html += `<div class="exam-section-title">${q.sectionTitle}</div>`;
    } else {
      html += `<div class="exam-section-slim">${q.sectionTitle.split('（')[0]}</div>`;
    }
  }
  let qScore = (typeof q.score === 'number') ? q.score : 10;
  let scoreBadge = (typeof q.score === 'number') ? `<span class="exam-score-badge">${qScore}分</span>` : '';
  // v51：难度徽标（基础/提高/拓展）
  let diffLv = questionDifficulty(q);
  let diffBadge = `<span class="diff-badge diff-${diffLv}">${DIFF_NAMES[diffLv]}</span>`;
  html += `<div class="question-type-tag">${typeTag} ${scoreBadge}${diffBadge}</div>`;

  // 题干长度自适应字号：长应用题改用小字号 + 左对齐，短算式保留大字
  let qText = String(q.question || '');
  let plainLen = qText.replace(/<[^>]+>/g, '').length;
  let sizeClass = plainLen > 34 ? ' long' : (plainLen > 18 ? ' medium' : '');
  // 考试模式加题号，贴近真实卷面
  let qNo = isExam ? `<span class="q-no">${state.quizIndex + 1}.</span>` : '';
  let qHtml = qText.replace(/\n/g, '<br>');

  if ((q.type === 'choice' || q.type === 'shape_choice') && !q.forceFill) {
    if (q.svg) {
      html += `<div class="shape-container"><svg viewBox="0 0 120 100" xmlns="http://www.w3.org/2000/svg">${q.svg}</svg></div>`;
    }
    html += `<div class="question-text${sizeClass}">${qNo}${qHtml}</div>`;
    // 选项排布：长选项单列左对齐，短选项两列节省高度
    let maxOptLen = Math.max(...q.options.map(o => String(typeof o === 'object' ? o.value : o).length));
    let gridClass = maxOptLen > 8 ? ' wide' : (maxOptLen <= 6 && q.options.length >= 3 ? ' two-col' : '');
    html += `<div class="options-grid${gridClass}">`;
    let labels = ['A', 'B', 'C', 'D'];
    q.options.forEach((opt, i) => {
      let val = typeof opt === 'object' ? opt.value : opt;
      // v69 兜底：选项超过 4 个时，旧代码 labels[i] 为 undefined 会渲染出「undefined」
      let label = typeof opt === 'object' ? opt.label : (labels[i] || String.fromCharCode(65 + i));
      html += `<button class="option-btn" data-idx="${i}" onclick="selectOption(${i})">
        <span class="option-label">${label}</span>
        <span class="option-value">${val}</span>
      </button>`;
    });
    html += `</div>`;
  } else if (q.type === 'fill' || q.forceFill) {
    if (q.svg) {
      html += `<div class="shape-container"><svg viewBox="0 0 120 100" xmlns="http://www.w3.org/2000/svg">${q.svg}</svg></div>`;
    }
    html += `<div class="question-text${sizeClass}">${qNo}${qHtml}</div>`;
    // v84：零打字输入面板。孩子不会打字，填空题一律改点选（数字/符号键盘、词卡、词块）。
    // InputKit 未加载时 render 返回 ''，输入框不带 readonly —— 自动降级为原生打字，不会答不了题。
    let ikHtml = (window.InputKit && window.InputKit.render) ? window.InputKit.render(q) : '';
    let roAttr = ikHtml ? ' data-ik-ro="1"' : '';
    let ikCls = ikHtml ? ' ik-target' : '';
    // v84：回跳到已答过的题时回填原答案（旧版跳回来输入框是空的，孩子点的答案凭空消失）
    let saved = String(state.userAnswers[state.quizIndex] == null ? '' : state.userAnswers[state.quizIndex]);
    let savedParts = /[,，、]/.test(saved) ? saved.split(/[,，、]+/).map(s => s.trim()) : [saved];
    // v69：题干含 2 个及以上空位时，逐空渲染输入框（旧版只有 1 个框，孩子根本没法作答）
    let blanks = countFillBlanks(q);
    if (blanks >= 2) {
      html += `<div class="multi-blank-row">`;
      for (let bi = 0; bi < blanks; bi++) {
        html += `<span class="mb-item"><span class="mb-no">${bi + 1}</span>` +
          `<input type="text" class="answer-input answer-input-multi${ikCls}" placeholder="第${bi + 1}空" ` +
          `value="${String(savedParts[bi] || '').replace(/"/g, '&quot;')}" ` +
          `inputmode="${ikHtml ? 'none' : (q.inputType || 'text')}"${roAttr} onkeydown="if(event.key==='Enter')submitAnswer()"></span>`;
      }
      html += `</div>`;
      html += `<div class="mb-tip">共 ${blanks} 个空，请${ikHtml ? '点上方空位切换，再点下面键盘' : '按顺序分别填写'}</div>`;
    } else {
      html += `<input type="text" class="answer-input${ikCls}" id="answerInput" ` +
        `placeholder="${ikHtml ? '点下面的数字键作答' : '输入答案'}" ` +
        `value="${saved.replace(/"/g, '&quot;')}" ` +
        `inputmode="${ikHtml ? 'none' : (q.inputType || 'text')}"${roAttr} onkeydown="if(event.key==='Enter')submitAnswer()">`;
    }
    if (ikHtml) html += ikHtml;
  }

  card.innerHTML = html;
  // v84：面板渲染后把输入框设为只读（防软键盘弹出 + 防手输全角符号）
  if (window.InputKit && card.querySelector('.ik')) window.InputKit.bind(card);
  document.getElementById('feedback').className = 'feedback';
  document.getElementById('submitBtn').textContent = '提交答案';
  document.getElementById('submitBtn').onclick = submitAnswer;
  renderQuizNav();

  // 自动聚焦输入框
  if (q.type === 'fill' || q.forceFill) {
    setTimeout(() => {
      let input = document.getElementById('answerInput') || document.querySelector('.answer-input-multi');
      if (input) input.focus();
    }, 100);
  }
}

// v69：数一数题干里有几个空位（（ ）/ ( ) / ＿＿ / __）
function countFillBlanks(q) {
  let t = String((q && q.question) || '');
  let m = t.match(/（\s*）|\(\s*\)|＿+|_{2,}/g);
  return m ? m.length : 0;
}

// v69：填空题判分——支持单空、多空（逗号/顿号/斜杠分隔），并保留数值容差
// v84r：数值容差改用 core.js 的 looseNumericEquals。
//   修复 P0：旧逻辑 parseFloat("8/5") 与 parseFloat("8/3") 都取到 8 → 分母写错也判对；
//   「7个十和4个一」与「7个十和5个一」都取到 7 → 个位写错也判对。
//   现在：分数用交叉相乘精确判等，含中文（计数器/带单位）只用精确字符串比较。
function fillAnswerEquals(user, correct) {
  let u = String(user == null ? '' : user).trim();
  let c = String(correct == null ? '' : correct).trim();
  if (u === c) return true;
  if (typeof looseNumericEquals === 'function') {
    if (looseNumericEquals(u, c)) return true;
  } else if (u !== '' && c !== '' && !isNaN(parseFloat(u)) && !isNaN(parseFloat(c)) && parseFloat(u) === parseFloat(c)) {
    return true; // 兜底（core.js 未加载时保留旧行为，正常不会发生）
  }
  let up = u.split(/[,，、\/]+/).map(s => s.trim()).filter(s => s !== '');
  let cp = c.split(/[,，、\/]+/).map(s => s.trim()).filter(s => s !== '');
  if (up.length > 1 && up.length === cp.length) {
    return up.every((v, i) => v === cp[i] ||
      (typeof looseNumericEquals === 'function'
        ? looseNumericEquals(v, cp[i])
        : (v !== '' && !isNaN(parseFloat(v)) && !isNaN(parseFloat(cp[i])) && parseFloat(v) === parseFloat(cp[i]))));
  }
  return false;
}

// v69：读取填空题作答（自动兼容单框与多框）
function readFillAnswer() {
  let multi = document.querySelectorAll('.answer-input-multi');
  if (multi && multi.length) {
    let parts = [];
    multi.forEach(el => parts.push(String(el.value || '').trim()));
    if (parts.every(p => p === '')) return '';
    return parts.join(',');
  }
  let input = document.getElementById('answerInput');
  return input ? String(input.value || '').trim() : '';
}

function getQuestionTypeTag(q) {
  // v73：卷面上题型的判定以「真题分区」为准——填空题区里即使保留了选项，
  // 它在卷面上仍然是填空题；判断题是真题必有的独立题型，优先识别。
  // v83r：但若实际并未 forceFill、且题是 type=choice/shape_choice，说明这题是选择题误进填空区，
  // 此时标签按真实类型显示（孩子看到 4 个选项 + 「选择题」标签才能对齐）。
  if (q.judge) return '判断题';
  if (q._section === 'calc') return '计算题';
  if (q._section === 'app') return '解决问题';
  if (q._section === 'fill' && q.forceFill) return '填空题';
  if (q._section === 'fill') {
    // 未 forceFill 的填空区选择题：按真实类型显示
    if (q.type === 'shape_choice') return '图形题';
    if (q.type === 'choice') return '选择题';
    return '填空题';
  }
  if (q._section === 'choice') return '选择题';
  if (q._section === 'judge') return '判断题';
  if (q.type === 'fill') return '填空题';
  if (q.type === 'shape_choice') return '图形题';
  if (q.type === 'choice') return '选择题';
  return '练习题';
}

// v73.2：题号导航——整卷（练习/考试）全部题号可点击跳转，不强制顺序作答
function renderQuizNav() {
  let nav = document.getElementById('quizNav');
  if (!nav) return;
  let N = state.quizQuestions.length;
  let html = '';
  for (let i = 0; i < N; i++) {
    let cls = 'qn-num';
    if (i === state.quizIndex) cls += ' current';
    let st = state.qStatus[i] || 0;
    if (st === 1) cls += ' ok';
    else if (st === 2) cls += ' bad';
    html += `<button class="${cls}" onclick="jumpToQuestion(${i})">${i + 1}</button>`;
  }
  nav.innerHTML = html;
}

function jumpToQuestion(i) {
  if (i < 0 || i >= state.quizQuestions.length) return;
  state.quizIndex = i;
  state.answered = false;
  state.selectedAnswer = null;
  renderQuestion();
}

// 记录本次作答对错，并校正累计计数（支持回跳改答，避免重复计分）
function recordAnswer(isCorrect, qScore) {
  let prev = state.qStatus[state.quizIndex] || 0;
  if (prev === 1) { state.quizCorrect--; if (state.quizMode === 'exam') state.quizScore -= qScore; }
  else if (prev === 2) { state.quizWrong--; }
  if (isCorrect) { state.quizCorrect++; if (state.quizMode === 'exam') state.quizScore += qScore; }
  else { state.quizWrong++; }
  state.qStatus[state.quizIndex] = isCorrect ? 1 : 2;
}

function selectOption(idx) {
  if (state.answered) return;
  state.selectedAnswer = idx;
  document.querySelectorAll('.option-btn').forEach((btn, i) => {
    btn.classList.toggle('selected', i === idx);
  });
}

function submitAnswer() {
  if (!state.wrongMap) state.wrongMap = {};
  if (!state.qStatus) state.qStatus = [];
  let q = state.quizQuestions[state.quizIndex];

  if (!state.answered) {
    // 提交答案
    let userAnswer = '';
    let isCorrect = false;

    if ((q.type === 'choice' || q.type === 'shape_choice') && !q.forceFill) {
      if (state.selectedAnswer === null) {
        showToast('请选择一个答案');
        return;
      }
      let selectedOpt = q.options[state.selectedAnswer];
      userAnswer = typeof selectedOpt === 'object' ? selectedOpt.value : selectedOpt;
      let correctOpt = q.type === 'choice' && typeof q.options[q.answerIdx] === 'object'
        ? q.options[q.answerIdx].value : q.answer;
      isCorrect = userAnswer === correctOpt || userAnswer === q.answer;
    } else if (q.type === 'fill' || q.forceFill) {
      userAnswer = readFillAnswer();
      if (userAnswer === '') {
        showToast('请输入答案');
        return;
      }
      isCorrect = fillAnswerEquals(userAnswer, q.answer);
    }

    state.answered = true;
    state.userAnswers[state.quizIndex] = userAnswer;

    // 标记对错
    if ((q.type === 'choice' || q.type === 'shape_choice') && !q.forceFill) {
      document.querySelectorAll('.option-btn').forEach((btn, i) => {
        let optVal = typeof q.options[i] === 'object' ? q.options[i].value : q.options[i];
        if (optVal === q.answer) {
          btn.classList.add('correct');
        } else if (i === state.selectedAnswer && !isCorrect) {
          btn.classList.add('wrong');
        }
      });
    } else if (q.type === 'fill' || q.forceFill) {
      let multi = document.querySelectorAll('.answer-input-multi');
      if (multi && multi.length) {
        let cp = String(q.answer || '').split(/[,，、\/]+/).map(s => s.trim());
        multi.forEach((el, i) => {
          el.classList.add(fillAnswerEquals(el.value, cp[i]) ? 'correct' : 'wrong');
          el.disabled = true;
        });
      } else {
        let input = document.getElementById('answerInput');
        if (input) {
          input.classList.add(isCorrect ? 'correct' : 'wrong');
          input.disabled = true;
        }
      }
      // v84：本题已判分，锁掉点选面板，防止孩子继续改答案导致与已记录的成绩不一致
      document.querySelectorAll('#questionCard .ik').forEach(el => el.classList.add('locked'));
    }

    // 显示反馈
    let feedback = document.getElementById('feedback');
    let qScore = (typeof q.score === 'number') ? q.score : 10;
    if (isCorrect) {
      recordAnswer(true, qScore);
      delete state.wrongMap[state.quizIndex];   // v73.2：回跳改答为正确，移出待入库错题
      feedback.className = 'feedback correct show bounce';
      let praises = ['答对了！太棒了！', '真厉害！继续加油！', '完美！你真聪明！', '不错不错！'];
      feedback.innerHTML = `✓ ${pick(praises)}`;
      // v53：错题重练答对即视为「已掌握」，自动移出错题库
      if (state.quizMode === 'wrong' && state.quizWrongSourceIds && state.quizWrongSourceIds[state.quizIndex]) {
        let srcId = state.quizWrongSourceIds[state.quizIndex];
        removeFromWrongBank(srcId);
        feedback.innerHTML += ` <span class="master-badge">已掌握，自动移出错题本</span>`;
      }
    } else {
      recordAnswer(false, qScore);
      feedback.className = 'feedback wrong show shake';
      // v51 错题公式卡联动：答错时内嵌该单元的万能公式卡（做错 → 回看公式 → 重做）
      let fidxHtml = '';
      if (state.quizMode === 'unit') {
        let hit = findUnitByName(state.currentGrade, state.quizTitle);
        fidxHtml = unitFormulaHtml(hit && hit.unit);
        if (fidxHtml) fidxHtml = `<div class="fb-fidx">${fidxHtml}</div>`;
      }
      feedback.innerHTML = `再想想！正确答案是：<span class="correct-answer">${q.answer}</span>${fidxHtml}`;
      // 加入错题
      state.wrongMap[state.quizIndex] = {
        index: state.quizIndex,
        question: q,
        userAnswer: userAnswer,
        unitName: state.quizTitle,
        grade: state.currentGrade
      };
    }

    document.getElementById('submitBtn').textContent = state.quizIndex < state.quizQuestions.length - 1 ? '下一题 →' : '查看结果 →';

  } else {
    // 下一题
    if (state.quizIndex < state.quizQuestions.length - 1) {
      state.quizIndex++;
      renderQuestion();
    } else {
      finishQuiz();
    }
  }
}

function finishQuiz() {
  // 停止计时器
  if (state.examTimer) { clearInterval(state.examTimer); state.examTimer = null; }

  const total = state.quizQuestions.length;
  const isExam = state.quizMode === 'exam';
  state.userAnswers = state.userAnswers || [];
  state.qStatus = state.qStatus || [];

  // 把未作答的题目统一记为错误，避免成绩页缺项
  for (let i = 0; i < total; i++) {
    if (!state.qStatus[i]) {
      state.qStatus[i] = 2;
      state.quizWrong++;
      let q = state.quizQuestions[i];
      if (!state.wrongMap[i]) state.wrongMap[i] = { index: i, question: q, userAnswer: '', unitName: state.quizTitle, grade: state.currentGrade };
      if (state.userAnswers[i] === undefined) state.userAnswers[i] = '';
    }
  }

  // 记录错题
  Object.values(state.wrongMap).forEach(w => {
    addToWrongBank(w.question, w.userAnswer, w.unitName, w.grade);
  });

  // 组装本次错题详情（供云端/家长端查看）
  const quizWrongDetails = Object.values(state.wrongMap).map(w => ({
    unitName: w.unitName,
    grade: w.grade,
    userAnswer: (w.userAnswer === undefined || w.userAnswer === null) ? '' : String(w.userAnswer),
    question: {
      question: w.question.question,
      options: w.question.options || [],
      answer: (w.question.answer === undefined || w.question.answer === null) ? '' : String(w.question.answer),
      explain: w.question.explain || '',
      svg: w.question.svg || ''
    }
  }));
  // 记录历史
  recordHistory(state.currentGrade, state.quizTitle, state.quizCorrect, total, quizWrongDetails);
  if (typeof syncAfterQuiz === 'function') { syncAfterQuiz(); }

  // 渲染成绩页（第一步）
  renderMobileScorePage();
  showPage('result');
  document.getElementById('backBtn').style.display = 'none';
}

function renderMobileScorePage() {
  const total = state.quizQuestions.length;
  const isExam = state.quizMode === 'exam';
  const totalScore = isExam ? 100 : total;
  const score = isExam ? (state.quizScore || 0) : (state.quizCorrect || 0);
  const accuracy = totalScore ? Math.round(score / totalScore * 100) : 0;
  const level = getGradeLevel(accuracy);
  const timeUsed = formatDuration(Date.now() - (state.quizStartTime || Date.now()));
  const wrongItems = Object.values(state.wrongMap);
  const comment = generateTeacherComment(score, totalScore, accuracy, wrongItems, state.currentGrade, isExam);

  document.getElementById('resultScore').textContent = score;
  document.getElementById('resultTotal').textContent = '/' + totalScore;
  document.getElementById('teacherLevel').textContent = '等级：' + level.label;
  document.getElementById('teacherLevel').className = 'teacher-level ' + level.cls;
  document.getElementById('resultStars').textContent = level.stars;
  document.getElementById('resultCorrect').textContent = state.quizCorrect;
  document.getElementById('resultWrong').textContent = state.quizWrong;
  document.getElementById('resultAccuracy').textContent = accuracy + '%';
  document.getElementById('resultTime').textContent = timeUsed;
  document.getElementById('teacherComment').textContent = comment;

  // 各题得分明细
  let detailHtml = '';
  state.quizQuestions.forEach((q, i) => {
    const st = state.qStatus[i] || 2;
    const correct = st === 1;
    const qScore = isExam ? (q.score || 1) : 1;
    const got = correct ? qScore : 0;
    detailHtml += `<div class="m-score-row ${correct ? 'ok' : 'bad'}">`;
    detailHtml += `<span class="m-sr-no">第${i + 1}题</span>`;
    detailHtml += `<span class="m-sr-type">${questionTypeLabel(q.type)}</span>`;
    detailHtml += `<span class="m-sr-mark">${correct ? svgHandwrittenCheck(true) : svgHandwrittenCheck(false)}</span>`;
    detailHtml += `<span class="m-sr-score">${got.toFixed(qScore % 1 === 0 ? 0 : 1)}/${qScore.toFixed(qScore % 1 === 0 ? 0 : 1)}分</span>`;
    detailHtml += '</div>';
  });
  document.getElementById('questionScoreList').innerHTML = detailHtml;

  // v84 P4：知识点掌握度报告（按错题知识点聚类，最弱排前，<60% 标红 + 纸质联动建议）
  renderMasteryBlock();

  // 默认显示成绩页、隐藏答案解析
  document.getElementById('resultScoreCard').style.display = 'block';
  document.getElementById('examAnswerKey').style.display = 'none';
}

// v84 P4：把本次测验的错题按「知识点」聚类，生成掌握度报告。
// 知识点由 core.js 的 detectMathConcepts(题面) 归因；一道题可命中多个知识点。
function renderMasteryBlock() {
  var el = document.getElementById('masteryBlock');
  if (!el) return;
  var concepts = {};
  state.quizQuestions.forEach(function (q, i) {
    var st = state.qStatus[i] || 2;
    var correct = st === 1;
    var names = (typeof detectMathConcepts === 'function') ? detectMathConcepts(q.question) : [];
    if (!names || !names.length) return;
    names.forEach(function (n) {
      if (!concepts[n]) concepts[n] = { total: 0, correct: 0 };
      concepts[n].total++;
      if (correct) concepts[n].correct++;
    });
  });
  var keys = Object.keys(concepts);
  if (!keys.length) { el.innerHTML = ''; el.style.display = 'none'; return; }
  // 掌握度升序（最弱排前）
  keys.sort(function (a, b) {
    return (concepts[a].correct / concepts[a].total) - (concepts[b].correct / concepts[b].total);
  });
  var h = '<div class="detail-title">📊 知识点掌握度（按薄弱排序）</div>';
  keys.forEach(function (n) {
    var c = concepts[n];
    var pct = Math.round(c.correct / c.total * 100);
    var weak = pct < 60;
    var bar = pct + '%';
    h += '<div class="mastery-row' + (weak ? ' weak' : '') + '">';
    h += '<div class="mastery-top"><span class="mastery-name">' + n + '</span>'
      + '<span class="mastery-pct">' + bar + '（' + c.correct + '/' + c.total + '）</span></div>';
    h += '<div class="mastery-bar"><i style="width:' + bar + '"></i></div>';
    if (weak) h += '<div class="mastery-tip">⚠ 薄弱：建议配套纸质《同步练习》重点巩固「' + n + '」</div>';
    h += '</div>';
  });
  el.innerHTML = h;
  el.style.display = 'block';
}

function confirmScore() {
  renderMobileAnswerKey();
  document.getElementById('resultScoreCard').style.display = 'none';
  document.getElementById('examAnswerKey').style.display = 'block';
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function renderMobileAnswerKey() {
  const isExam = state.quizMode === 'exam';
  let secs = {};
  state.quizQuestions.forEach((q, i) => {
    const key = q.sectionTitle || '题目';
    if (!secs[key]) secs[key] = [];
    secs[key].push(Object.assign({}, q, { idx: i }));
  });

  let html = '';
  for (let [title, qs] of Object.entries(secs)) {
    html += `<div class="m-answer-section">${title}</div>`;
    qs.forEach(q => {
      const i = q.idx;
      const st = state.qStatus[i] || 2;
      const correct = st === 1;
      const ua = state.userAnswers[i] !== undefined ? String(state.userAnswers[i]) : '';
      html += `<div class="m-answer-item ${correct ? 'ok' : 'bad'}">`;
      html += `<div class="m-ai-head">`;
      html += `<span class="m-ai-no">第${q.num || (i + 1)}题</span>`;
      html += `<span class="m-ai-type">${questionTypeLabel(q.type)}</span>`;
      html += `<span class="m-ai-mark">${correct ? svgHandwrittenCheck(true) : svgHandwrittenCheck(false)}</span>`;
      html += '</div>';
      if (q.passage) html += `<div class="m-ai-passage">${q.passage}</div>`;
      html += `<div class="m-ai-stem">${q.question}</div>`;
      if (q.svg) html += `<div class="m-ai-svg"><svg viewBox="0 0 120 100" xmlns="http://www.w3.org/2000/svg">${q.svg}</svg></div>`;
      if (q.options && q.options.length) {
        html += '<div class="m-ai-opts">';
        q.options.forEach((opt, idx) => {
          const txt = typeof opt === 'object' ? opt.value : opt;
          let cls = '';
          if (txt === String(q.answer)) cls = ' correct';
          else if (txt === ua && !correct) cls = ' wrong';
          html += `<div class="m-ai-opt${cls}">${String.fromCharCode(65 + idx)}. ${txt}</div>`;
        });
        html += '</div>';
      }
      html += `<div class="m-ai-ans-row">`;
      html += `<span>你的答案：<b class="${correct ? 'ok' : 'bad'}">${ua !== '' ? ua : '未作答'}</b></span>`;
      html += `<span>正确答案：<b class="ok">${q.answer}</b></span>`;
      html += '</div>';
      if (q.explain) html += `<div class="m-ai-explain"><b>解析：</b>${q.explain}</div>`;
      if (q.steps && q.steps.length) html += `<div class="m-ai-steps"><b>步骤：</b>${q.steps.map((s, idx) => `<span>${idx + 1}. ${s}</span>`).join('')}</div>`;
      html += '</div>';
    });
  }
  document.getElementById('examAnswerKeyBody').innerHTML = html;
}

function backToStudy() {
  if (state.quizMode === 'unit' && state.quizTitle) {
    // 返回对应单元：切到单元练习页即可
    showPage('units');
  } else {
    goHome();
  }
}

function retryQuiz() {
  document.getElementById('examAnswerKey').style.display = 'none';
  if (state.quizMode === 'exam') {
    // 重新组一份同类型试卷
    startExam();
    return;
  }
  if (state.quizMode === 'unit') {
    // 重新生成同单元题目
    let units = KNOWLEDGE_BASE[state.currentGrade][state.currentSemester];
    let unit = units.find(u => u.name === state.quizTitle);
    if (unit) {
      state.quizQuestions = [];
      for (let i = 0; i < QUIZ_LENGTH; i++) state.quizQuestions.push(unit.gen());
      state.quizIndex = 0;
      state.quizScore = 0;
      state.quizCorrect = 0;
      state.quizWrong = 0;
      state.quizWrongQuestions = [];
  state.qStatus = [];
  state.wrongMap = {};
      state.qStatus = [];
      state.wrongMap = {};
      showPage('quiz');
      document.getElementById('backBtn').style.display = 'block';
      document.getElementById('backBtn').onclick = () => goBack();
      renderQuestion();
    }
  } else if (state.quizMode === 'wrong') {
    startWrongReview();
  } else {
    startQuickPractice(state.quizTitle === '基础运算' ? 'basic' : 'mixed');
  }
}

// ============================================================
// 错题库渲染
// ============================================================
function renderWrongBank() {
  let wrongBank = getWrongBank();
  let container = document.getElementById('wrongListContainer');

  if (wrongBank.length === 0) {
    container.innerHTML = `<div class="empty-state"><div class="empty-icon">${UI_ICON.svg('bookmark',30)}</div><div class="empty-text">错题库是空的，继续保持！</div></div>`;
    return;
  }

  let gradeNames = {1:'一年级',2:'二年级',3:'三年级',4:'四年级',5:'五年级',6:'六年级',7:'七年级',8:'八年级',9:'九年级'};
  let html = `<div class="u-fs13 u-c-light u-mb10">共 ${wrongBank.length} 道错题</div>`;

  // v84 P4：错题库按知识点聚类（高频薄弱点一眼可见，并联动纸质练习建议）
  let conceptMap = {};
  wrongBank.forEach(w => {
    let names = (typeof detectMathConcepts === 'function') ? detectMathConcepts((w.question && w.question.question) || '') : [];
    names.forEach(n => { conceptMap[n] = (conceptMap[n] || 0) + 1; });
  });
  let ckeys = Object.keys(conceptMap);
  if (ckeys.length) {
    ckeys.sort((a, b) => conceptMap[b] - conceptMap[a]);
    html += '<div class="wrong-cluster">';
    html += '<div class="detail-title">📚 错题知识点聚类（' + ckeys.length + ' 类）</div>';
    html += '<div class="cluster-tags">';
    ckeys.forEach(n => { html += '<span class="cluster-tag">' + n + ' <b>' + conceptMap[n] + '</b></span>'; });
    html += '</div>';
    html += '<div class="mastery-tip">高频薄弱点建议配套纸质《同步练习》对应章节重点巩固。</div>';
    html += '</div>';
  }

  html += '<div class="wrong-list">';

  wrongBank.forEach(w => {
    let q = w.question;
    let qText = q.question;
    let userAns = w.userAnswer;
    let correctAns = q.answer;

    // v51 错题公式卡联动：能定位到所属单元的错题，挂出该单元万能公式卡 + 一键练同类题
    let hit = findUnitByName(w.grade, w.unitName);
    let fidxHtml = unitFormulaHtml(hit && hit.unit);
    let fidxBlock = fidxHtml
      ? `<details class="wrong-fidx"><summary>本单元万能公式（错题联动）</summary><div class="wrong-fidx-body">${fidxHtml}</div></details>`
      : '';
    let similarBtn = hit
      ? `<button class="btn-similar" onclick="practiceSimilarWrong('${w.id}')">练同类题</button>`
      : '';

    // v81：解析讲解回填。老错题入库时可能只存了「答案：x」这种空壳步骤，
    // 这里统一判定「有效步骤」——少于 2 步或整段就是「答案：…」的，重新生成一次。
    let steps = q.steps;
    if (!steps || !steps.length || (steps.length === 1 && /^答案：/.test(steps[0]))) {
      steps = generateSteps(q, hit && hit.unit);
    }
    let explainBlock = q.explain
      ? `<div class="wrong-explain"><b>解析：</b>${q.explain}</div>`
      : '';
    let stepsBlock = (steps && steps.length)
      ? `<details class="wrong-steps" open><summary>分步讲解（${steps.length} 步）</summary>`
        + `<ol class="wrong-steps-ol">${steps.map(s => `<li>${s}</li>`).join('')}</ol></details>`
      : '';

    html += `<div class="wrong-item">
      <div class="wrong-item-header">
        <span class="wrong-item-tag">${gradeNames[w.grade] || ''} · ${w.unitName || ''}</span>
        <span class="u-fs11 u-c-lighter">错${w.count || 1}次</span>
      </div>
      <div class="wrong-item-question">${qText}</div>
      <div class="wrong-item-answer">
        你的答案：<span class="user-ans">${userAns}</span> ｜ 正确答案：<span class="correct-ans">${correctAns}</span>
      </div>
      ${explainBlock}
      ${stepsBlock}
      ${fidxBlock}
      <div class="wrong-item-actions">
        <button class="btn-retry" onclick="retryOneWrong('${w.id}')">重做</button>
        ${similarBtn}
        <button class="btn-delete" onclick="deleteOneWrong('${w.id}')">删除</button>
      </div>
    </div>`;
  });

  html += '</div>';
  container.innerHTML = html;
}

function retryOneWrong(id) {
  let wrongBank = getWrongBank();
  let w = wrongBank.find(x => x.id === id);
  if (!w) return;
  state.quizMode = 'wrong';
  state.quizTitle = '错题重做';
  state.quizQuestions = [w.question];
  state.quizWrongSourceIds = [w.id];
  state.quizIndex = 0;
  state.quizScore = 0;
  state.quizCorrect = 0;
  state.quizWrong = 0;
  state.quizWrongQuestions = [];
  state.qStatus = [];
  state.wrongMap = {};
  showPage('quiz');
  document.getElementById('backBtn').style.display = 'block';
  document.getElementById('backBtn').onclick = () => goBack();
  renderQuestion();
}

function deleteOneWrong(id) {
  removeFromWrongBank(id);
  renderWrongBank();
  showToast('已删除');
}

function clearAllWrong() {
  let mathItems = getWrongBank();
  if (mathItems.length === 0) {
    showToast('错题库已经是空的');
    return;
  }
  if (confirm('确定要清空数学错题吗？英语错题将保留。此操作不可撤销。')) {
    let data = loadData();
    data.wrong = (data.wrong || []).filter(w => w.module && w.module !== '数学');
    saveData(data);
    renderWrongBank();
    showToast('已清空数学错题库');
  }
}

// ============================================================
// v51：错题公式卡联动 + A4 打印导出
// ============================================================

// 按年级+单元名定位 KNOWLEDGE_BASE 中的单元（错题的 unitName 即练习时的 quizTitle）
function findUnitByName(grade, name) {
  if (!grade || !name) return null;
  let sems = KNOWLEDGE_BASE[grade];
  if (!sems) return null;
  for (let s = 1; s <= 2; s++) {
    let arr = sems[s];
    if (!arr) continue;
    for (let i = 0; i < arr.length; i++) {
      if (arr[i] && arr[i].name === name) return { unit: arr[i], grade: grade, sem: s, idx: i };
    }
  }
  return null;
}

// 单元万能公式卡 HTML（金色描边小卡，错题联动与答题反馈共用）
function unitFormulaHtml(unit) {
  if (!unit || !unit.fidx || !unit.fidx.length) return '';
  let h = '<div class="wrong-fidx-title">万能公式</div>';
  unit.fidx.forEach(f => {
    h += '<div class="wrong-fidx-card">'
      + '<span class="wrong-fidx-t">' + f.t + '</span>'
      + '<span class="wrong-fidx-f">' + f.f + '</span>'
      + (f.warn ? '<span class="wrong-fidx-warn">'+UI_ICON.svg('warn',13)+' ' + f.warn + '</span>' : '')
      + '</div>';
  });
  return h;
}

// 错题「练同类题」：定位所属单元后直接开一组新的单元练习
function practiceSimilarWrong(id) {
  let w = getWrongBank().find(x => x.id === id);
  if (!w) { showToast('错题不存在'); return; }
  let hit = findUnitByName(w.grade, w.unitName);
  if (!hit) { showToast('未找到对应单元'); return; }
  beginUnitQuiz(hit.idx, hit.grade, hit.sem);
}

// v51：A4 打印导出——把当前试卷（单元练习/考试卷）渲染为打印视图后调起打印
function printCurrentPaper() {
  let qs = (state.quizQuestions || []).slice();
  if (!qs.length) { showToast('当前没有可打印的试卷'); return; }

  let isExam = state.quizMode === 'exam';
  let title = isExam && state.examPaper ? state.examPaper.title
    : (state.quizTitle ? state.quizTitle + ' 练习卷' : '数学练习卷');
  let d = new Date();
  let dateStr = `${d.getFullYear()}年${d.getMonth() + 1}月${d.getDate()}日`;

  // 难度分布统计
  let dcnt = { 1: 0, 2: 0, 3: 0 };
  qs.forEach(q => { dcnt[questionDifficulty(q)]++; });
  let sub = isExam && state.examPaper ? state.examPaper.sub
    : `共 ${qs.length} 题 · ${dateStr}`;
  sub += ` · 难度：基础${dcnt[1]}／提高${dcnt[2]}／拓展${dcnt[3]}`;

  let h = `<div class="prt-head">
    <div class="prt-title">${title}</div>
    <div class="prt-sub">${sub}</div>
    <div class="prt-info">姓名：＿＿＿＿＿＿＿　班级：＿＿＿＿＿＿＿　得分：＿＿＿＿＿＿＿</div>
  </div>`;

  // 按分区组织（单元练习无分区则连续编号）
  let secs = [], cur = null;
  qs.forEach(q => {
    let st = q.sectionTitle || '';
    if (!cur || cur.title !== st) { cur = { title: st, qs: [] }; secs.push(cur); }
    cur.qs.push(q);
  });

  let labels = ['A', 'B', 'C', 'D'];
  let no = 0;
  secs.forEach(sec => {
    if (sec.title) h += `<div class="prt-sec">${sec.title}</div>`;
    sec.qs.forEach(q => {
      no++;
      let diffLv = questionDifficulty(q);
      let txt = String(q.question || '').replace(/\n/g, '<br>');
      h += '<div class="prt-q">';
      h += `<div class="prt-qtext"><span class="prt-no">${no}.</span>${txt}`
        + `<span class="prt-diff diff-${diffLv}">${DIFF_NAMES[diffLv]}</span>`
        + (typeof q.score === 'number' ? `<span class="prt-score">（${q.score}分）</span>` : '')
        + '</div>';
      if (q.svg) h += `<div class="prt-fig"><svg viewBox="0 0 120 100" xmlns="http://www.w3.org/2000/svg">${q.svg}</svg></div>`;
      if (q.options && q.options.length >= 2 && !q.forceFill) {
        h += '<div class="prt-opts">';
        q.options.forEach((o, i2) => {
          let val = typeof o === 'object' ? o.value : o;
          // v85：labels 只有 A~D，选项超 4 个时旧版打印出「undefined.」
          let lab = typeof o === 'object' ? o.label : (labels[i2] || String.fromCharCode(65 + i2));
          h += `<div class="prt-opt"><span class="prt-optlab">${lab}.</span> ${val}</div>`;
        });
        h += '</div>';
      } else {
        h += '<div class="prt-blank">答：＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿＿</div>';
      }
      h += '</div>';
    });
  });

  // 附：参考答案页（另起一页）
  h += '<div class="prt-answers"><div class="prt-ans-title">参考答案</div><div class="prt-ans-grid">';
  qs.forEach((q, i) => {
    h += `<div class="prt-ans-item"><b>${i + 1}.</b> ${q.answer}</div>`;
  });
  h += '</div></div>';

  let root = document.getElementById('printRoot');
  if (!root) { root = document.createElement('div'); root.id = 'printRoot'; document.body.appendChild(root); }
  root.innerHTML = h;
  window.print();
}

// ============================================================
// 统计页渲染
// ============================================================
function renderStats() {
  let data = loadData();
  let history = data.history || [];
  let wrongBank = (data.wrong || []).filter(w => !w.module || w.module === '数学');
  let stats = data.stats || {};

  // v82：正确率配色原本是两处各写一遍的三元表达式（阈值还散落在模板串里），
  // 收敛成一个档位函数，配色交给 .acc-* 语义类（css/style.css）。
  const accTier = a => (a >= 80 ? 'acc-hi' : a >= 60 ? 'acc-mid' : 'acc-lo');

  // 总览
  let totalDone = history.reduce((s, h) => s + h.total, 0);
  let totalCorrect = history.reduce((s, h) => s + h.score, 0);
  let overallAccuracy = totalDone > 0 ? Math.round(totalCorrect / totalDone * 100) : 0;
  let totalExercises = history.length;

  let overview = document.getElementById('statsOverview');
  overview.innerHTML = `
    <div class="stat-card highlight">
      <div class="stat-icon"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M7 3h8l4 4v14H7z"/><path d="M15 3v4h4"/></svg></div>
      <div class="stat-value">${totalExercises}</div>
      <div class="stat-label">练习次数</div>
    </div>
    <div class="stat-card success">
      <div class="stat-icon"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 13l4 4L19 7"/></svg></div>
      <div class="stat-value">${totalCorrect}</div>
      <div class="stat-label">答对题数</div>
    </div>
    <div class="stat-card danger">
      <div class="stat-icon"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 6l12 12M18 6L6 18"/></svg></div>
      <div class="stat-value">${wrongBank.length}</div>
      <div class="stat-label">错题数量</div>
    </div>
    <div class="stat-card warning">
      <div class="stat-icon"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-width="1.8" stroke-linejoin="round"><path d="M4 20V11M10 20V4M16 20v-7M21 20H3"/></svg></div>
      <div class="stat-value">${overallAccuracy}%</div>
      <div class="stat-label">总正确率</div>
    </div>
  `;

  // 各年级统计
  let gradeNames = {1:'一年级',2:'二年级',3:'三年级',4:'四年级',5:'五年级',6:'六年级',7:'七年级',8:'八年级',9:'九年级'};
  let tableHtml = `<thead><tr><th>年级</th><th>已做题数</th><th>答对</th><th>正确率</th></tr></thead><tbody>`;
  for (let g = 1; g <= 9; g++) {
    let s = stats[g] || { totalDone: 0, totalCorrect: 0 };
    let acc = s.totalDone > 0 ? Math.round(s.totalCorrect / s.totalDone * 100) : 0;
    tableHtml += `<tr>
      <td>${gradeNames[g]}</td>
      <td>${s.totalDone}</td>
      <td>${s.totalCorrect}</td>
      <td class="u-fw700 ${s.totalDone > 0 ? accTier(acc) : 'acc-none'}">${s.totalDone > 0 ? acc + '%' : '—'}</td>
    </tr>`;
  }
  tableHtml += '</tbody>';
  document.getElementById('gradeStatsTable').innerHTML = tableHtml;

  // 近期成绩
  let recent = history.slice(0, 10);
  let recentEl = document.getElementById('recentScores');
  if (recent.length === 0) {
    recentEl.innerHTML = `<div class="empty-state"><div class="empty-icon u-c-lighter"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-width="1.8" stroke-linejoin="round"><path d="M4 20V11M10 20V4M16 20v-7M21 20H3"/></svg></div><div class="empty-text">还没有练习记录</div></div>`;
  } else {
    recentEl.innerHTML = recent.map(r => {
      let rateLabel = r.accuracy >= 90 ? '优秀' : r.accuracy >= 60 ? '良好' : '加油';
      let date = new Date(r.time);
      let dateStr = `${date.getMonth()+1}/${date.getDate()}`;
      return `<div class="card u-flex u-ac u-g10 u-p12-16">
        <div class="u-fs12 u-fw700 u-c-ok u-bg-ok-s2 u-p3-10 u-rpill">${rateLabel}</div>
        <div class="u-f1">
          <div class="u-fw600 u-fs14">${gradeNames[r.grade]} · ${r.unitName}</div>
          <div class="u-fs12 u-c-lighter">${dateStr} · ${r.score}/${r.total}题</div>
        </div>
        <div class="u-fw700 u-fs18 ${accTier(r.accuracy)}">${r.accuracy}%</div>
      </div>`;
    }).join('');
  }
}

// ============================================================
// Toast
// ============================================================
let toastTimer = null;
function showToast(msg) {
  let toast = document.getElementById('toast');
  toast.textContent = msg;
  toast.classList.add('show');
  if (toastTimer) clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('show'), 2000);
}

